/** Carabiner rating icon. Filled = earned. Shape and an accessible label carry the meaning. */
export function Carabiner({ filled, size = 28 }: { filled: boolean; size?: number }) {
  return (
    <svg width={size} height={size * 1.4} viewBox="0 0 20 28" aria-hidden>
      <path
        d="M10 2c5 0 7 3 7 8v8c0 5-3 8-7 8s-7-3-7-8V10c0-5 2-8 7-8z"
        fill={filled ? '#e9b44c' : 'none'}
        stroke={filled ? '#7a5a1f' : '#8a8f94'}
        strokeWidth={2.4}
      />
      <path d="M6 9v10" stroke={filled ? '#7a5a1f' : '#8a8f94'} strokeWidth={2} strokeLinecap="round" />
      <rect x={4.4} y={12} width={3.2} height={6} rx={1.2} fill={filled ? '#c8643b' : '#b9bdc1'} />
    </svg>
  );
}

export function CarabinerRow({ count, size = 28 }: { count: number; size?: number }) {
  return (
    <div className="flex items-center gap-1" role="img" aria-label={`${count} of 3 carabiners`}>
      {[0, 1, 2].map((i) => (
        <Carabiner key={i} filled={i < count} size={size} />
      ))}
    </div>
  );
}
