import { AnimatePresence, motion } from 'motion/react';
import { useEffect, useMemo, useState } from 'react';
import { REACH_DIFFICULTY_BONUS, ROPE_REQUIRED, STAMINA_COST } from '../../engine/config.ts';
import {
  BELAYER_ACTION_INFO,
  BELAYER_SIGNAL_TEXT,
  CLIMBER_ACTION_INFO,
  CLIMBER_SIGNAL_TEXT,
  TEAMWORK_POLICY_TEXT,
} from '../../engine/labels.ts';
import { BLOCK_REASON_TEXT, structurallyBlocked } from '../../engine/legality.ts';
import { difficultyAt } from '../../engine/routes.ts';
import {
  BELAYER_ACTIONS,
  BELAYER_SIGNALS,
  CLIMBER_ACTIONS,
  CLIMBER_SIGNALS,
  TEAMWORK_POLICIES,
  type BelayerAction,
  type BelayerSignal,
  type ClimberAction,
  type ClimberSignal,
  type GameState,
  type PublicDeclaration,
  type Role,
  type RouteDefinition,
  type Submission,
  type TeamworkPolicy,
} from '../../engine/types.ts';
import { sfx } from '../../audio/sound.ts';
import { IconLock } from '../ui/Icons.tsx';
import { Button } from '../ui/Primitives.tsx';
import { HandCard } from './ActionCard.tsx';

export interface ActionPanelProps {
  role: Role;
  state: GameState;
  route: RouteDefinition;
  partner: PublicDeclaration | null;
  busy?: boolean;
  submitLabel?: string;
  onSubmit(sub: Submission): void;
  /** Called when the player changes their public signal or teamwork preference before committing. */
  onDeclare?(signal: ClimberSignal | BelayerSignal | null, policy: TeamworkPolicy): void;
  initialDeclaration?: PublicDeclaration | null;
  /** Tutorial: only this card may be chosen. */
  only?: ClimberAction | BelayerAction;
  /** Tutorial: hide signals and Teamwork controls. */
  hideExtras?: boolean;
}

const successChance = (target: number, bonus: number) => Math.max(0, Math.min(6, 7 - (target - bonus))) / 6;

/** Climber card advice: structural blocks disable a card; rope-dependent risks only warn. */
function climberCardState(state: GameState, route: RouteDefinition, action: ClimberAction) {
  const block = structurallyBlocked(state, route, action);
  if (block) return { disabledReason: BLOCK_REASON_TEXT[block].replace(/^The climber/, 'You').replace('.', ''), warning: null };
  const need = ROPE_REQUIRED[action];
  if (state.rope < need) {
    const short = need - state.rope;
    return {
      disabledReason: null,
      warning: short === 1 ? `Needs ${need} rope (have ${state.rope}). Belayer must Feed.` : `Needs ${need} rope (have ${state.rope}). Only Feed + a Teamwork rescue can cover it.`,
    };
  }
  return { disabledReason: null, warning: null };
}

export function ActionPanel({ role, state, route, partner, busy, submitLabel, onSubmit, onDeclare, initialDeclaration, only, hideExtras }: ActionPanelProps) {
  const [action, setAction] = useState<ClimberAction | BelayerAction | null>(null);
  const [inspected, setInspected] = useState<ClimberAction | BelayerAction | null>(null);
  const [signal, setSignal] = useState<ClimberSignal | BelayerSignal | null>((initialDeclaration?.signal as ClimberSignal | null) ?? null);
  const [policy, setPolicy] = useState<TeamworkPolicy>(initialDeclaration?.teamworkPolicy ?? 'NEVER');
  const [sheet, setSheet] = useState(false);

  useEffect(() => {
    setAction(null);
    setInspected(null);
  }, [state.round]);

  const cards = useMemo(() => {
    const coach = (a: ClimberAction | BelayerAction) => (only && only !== a ? 'Follow the coach for this lesson.' : null);
    if (role === 'climber') {
      return CLIMBER_ACTIONS.map((a) => {
        const info = CLIMBER_ACTION_INFO[a];
        const st = climberCardState(state, route, a);
        let short = info.short;
        if ((a === 'STEP' || a === 'REACH') && !st.disabledReason) {
          const dest = state.position + (a === 'STEP' ? 1 : 2);
          const target = difficultyAt(route, dest) + (a === 'REACH' ? REACH_DIFFICULTY_BONUS : 0);
          short = `Roll ${target}+ · ${Math.round(successChance(target, 0) * 100)}%`;
        }
        if (a === 'REST') short = route.restHolds.includes(state.position) ? '+3 stamina' : '+1 stamina';
        return { action: a, ...info, short, costs: { stamina: STAMINA_COST[a], rope: ROPE_REQUIRED[a] }, ...st, disabledReason: st.disabledReason ?? coach(a) };
      });
    }
    return BELAYER_ACTIONS.map((a) => {
      const info = BELAYER_ACTION_INFO[a];
      let warning: string | null = null;
      if (a === 'FEED' && state.rope >= state.config.ropeMax) warning = 'Rope is already at the maximum.';
      if (a === 'TAKE_IN' && state.rope <= state.config.ropeMin) warning = 'There is no rope to take in.';
      if (a === 'TAKE_IN' && state.rope === 1) warning = 'The climber will have 0 rope.';
      return { action: a, ...info, costs: undefined, disabledReason: coach(a), warning };
    });
  }, [role, state, route, only]);

  const signals = role === 'climber' ? CLIMBER_SIGNALS : BELAYER_SIGNALS;
  const signalText = (s: string) => (role === 'climber' ? CLIMBER_SIGNAL_TEXT[s as ClimberSignal] : BELAYER_SIGNAL_TEXT[s as BelayerSignal]);

  const chooseSignal = (s: ClimberSignal | BelayerSignal | null) => {
    setSignal(s);
    sfx('tap');
    onDeclare?.(s, policy);
  };
  const choosePolicy = (p: TeamworkPolicy) => {
    setPolicy(p);
    sfx('tap');
    onDeclare?.(signal, p);
  };

  const submit = () => {
    if (!action) return;
    sfx('commit');
    const sub: Submission =
      role === 'climber'
        ? { role: 'climber', action: action as ClimberAction, signal: signal as ClimberSignal | null, teamworkPolicy: policy }
        : { role: 'belayer', action: action as BelayerAction, signal: signal as BelayerSignal | null, teamworkPolicy: policy };
    onSubmit(sub);
  };

  const focus = cards.find((c) => c.action === (inspected ?? action)) ?? null;
  const actionName = action ? cards.find((c) => c.action === action)!.name : null;

  return (
    <div className="flex flex-col gap-1.5" data-testid={`${role}-action-panel`}>
      <div className="grid grid-cols-4 gap-1.5 pt-1.5" role="group" aria-label={`${role === 'climber' ? 'Climber' : 'Belayer'} action cards`}>
        {cards.map((c) => (
          <HandCard
            key={c.action}
            role={role}
            action={c.action}
            name={c.name}
            short={c.short}
            costs={c.costs}
            selected={action === c.action}
            unavailable={!!c.disabledReason}
            warned={!!c.warning}
            label={`${c.name}: ${c.rules}${c.disabledReason ? ` Unavailable: ${c.disabledReason}` : ''}${c.warning ? ` Warning: ${c.warning}` : ''}`}
            onPress={() => {
              setInspected(c.action);
              if (c.disabledReason) {
                sfx('blocked');
                return;
              }
              setAction(c.action);
              sfx('card');
            }}
          />
        ))}
      </div>

      <p className={`line-clamp-2 h-[2.1rem] text-[0.72rem] leading-snug text-sand/90 ${hideExtras ? 'tiny:hidden' : ''}`} aria-live="polite" data-testid="card-detail">
        {focus ? (
          <>
            <b className="text-cream">{focus.name}:</b> {focus.rules}{' '}
            {focus.disabledReason ? <b className="text-[var(--warn)]">{focus.disabledReason}</b> : focus.warning ? <b className="text-[var(--warn)]">{focus.warning}</b> : null}
          </>
        ) : (
          'Tap a card to choose it. Your choice stays secret until both of you lock in.'
        )}
      </p>

      <div className="flex gap-2">
        {!hideExtras && (
          <button
            type="button"
            onClick={() => setSheet(true)}
            className="focus-ring flex min-h-12 min-w-0 flex-1 flex-col justify-center rounded-2xl bg-white/10 px-3 text-left text-cream"
            data-testid="signal-button"
            aria-haspopup="dialog"
          >
            <span className="text-[0.6rem] font-black uppercase tracking-wider text-sand/75">Signal · Teamwork</span>
            <span className="truncate text-[0.8rem] font-bold">
              {signal ? `“${signalText(signal)}”` : 'No signal'}
              {state.teamworkAvailable && policy !== 'NEVER' ? ` · ${TEAMWORK_POLICY_TEXT[policy].name}` : ''}
            </span>
          </button>
        )}
        <Button variant="rope" size="lg" className={hideExtras ? 'w-full' : 'flex-[1.25]'} disabled={!action || busy} onClick={submit} data-testid="lock-in">
          <IconLock size={20} /> {busy ? 'Locking in…' : actionName ? `${submitLabel ?? 'Lock in'} ${actionName}` : 'Choose a card'}
        </Button>
      </div>

      <AnimatePresence>
        {sheet && (
          <motion.div
            className="fixed inset-0 z-50 flex items-end bg-black/50"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setSheet(false)}
          >
            <motion.div
              role="dialog"
              aria-modal="true"
              aria-label="Signal and Teamwork"
              className="mx-auto w-full max-w-lg rounded-t-3xl bg-pine-900 px-4 pt-4 text-cream shadow-[var(--shadow-lift)]"
              style={{ paddingBottom: 'max(var(--safe-bottom), 1rem)' }}
              initial={{ y: 40 }}
              animate={{ y: 0 }}
              exit={{ y: 40 }}
              onClick={(e) => e.stopPropagation()}
            >
              <div className="mb-1.5 flex items-center justify-between text-xs font-black uppercase tracking-wider text-sand/80">
                <span>Signal to your partner (public)</span>
                {signal && (
                  <button type="button" className="focus-ring rounded px-1 text-sand/70 underline" onClick={() => chooseSignal(null)}>
                    clear
                  </button>
                )}
              </div>
              <div className="flex flex-wrap gap-1.5" role="radiogroup" aria-label="Signal">
                {signals.map((s) => (
                  <button
                    key={s}
                    type="button"
                    onClick={() => chooseSignal(s)}
                    role="radio"
                    aria-checked={signal === s}
                    className={`focus-ring min-h-10 rounded-full px-3 text-[0.85rem] font-bold transition ${signal === s ? 'bg-rope text-pine-950' : 'bg-white/10 text-cream'}`}
                  >
                    “{signalText(s)}”
                  </button>
                ))}
              </div>
              <div className="mb-1.5 mt-4 text-xs font-black uppercase tracking-wider text-sand/80">
                Teamwork token {state.teamworkAvailable ? '(public preference)' : '— already used'}
              </div>
              <div className="grid grid-cols-3 gap-1.5" role="radiogroup" aria-label="Teamwork preference">
                {TEAMWORK_POLICIES.map((p) => (
                  <button
                    key={p}
                    type="button"
                    role="radio"
                    disabled={!state.teamworkAvailable && p !== 'NEVER'}
                    onClick={() => choosePolicy(p)}
                    aria-checked={policy === p}
                    className={`focus-ring min-h-11 rounded-xl px-2 py-1.5 text-center text-[0.8rem] font-extrabold leading-tight transition disabled:opacity-40 ${
                      policy === p ? 'bg-turquoise-deep text-cream ring-2 ring-cream/60' : 'bg-white/10 text-cream'
                    }`}
                  >
                    {TEAMWORK_POLICY_TEXT[p].name}
                  </button>
                ))}
              </div>
              <p className="mt-1.5 text-xs text-sand/80">{TEAMWORK_POLICY_TEXT[policy].detail}</p>
              {partner && partner.teamworkPolicy !== 'NEVER' && state.teamworkAvailable && (
                <p className="mt-1 text-xs text-sand/80">Your partner prefers: {TEAMWORK_POLICY_TEXT[partner.teamworkPolicy].name}. Either preference can trigger the token.</p>
              )}
              <Button className="mt-4 w-full" onClick={() => setSheet(false)} data-testid="signal-done">
                Done
              </Button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
