import { AnimatePresence, motion } from 'motion/react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { navigate } from '../app/router.tsx';
import { GameTable } from '../components/game/GameTable.tsx';
import { Resolution } from '../components/game/Resolution.tsx';
import { ResultsPanel } from '../components/game/ResultsPanel.tsx';
import { IconEye, IconLock } from '../components/ui/Icons.tsx';
import { Button, Panel, Screen, ScreenHeader, GameScreen, CompactHeader } from '../components/ui/Primitives.tsx';
import { ROUTES, getRoute } from '../data/routes/index.ts';
import type { Role, Submission } from '../engine/types.ts';
import { askAi } from '../offline/aiClient.ts';
import type { LocalMatchRecord } from '../offline/db.ts';
import {
  acceptHandoff,
  applyAiAnswer,
  forfeitLocal,
  humanRoleOf,
  markRevealSeen,
  otherRole,
  pendingAiTask,
  rematchLocal,
  submitHuman,
} from '../offline/localGame.ts';
import { loadMatch, personalBests, saveMatch, type PersonalBest } from '../offline/repository.ts';

export function LocalGameScreen({ id }: { id: string }) {
  const [record, setRecord] = useState<LocalMatchRecord | null | undefined>(undefined);
  const [aiThinking, setAiThinking] = useState(false);
  const [pb, setPb] = useState<PersonalBest | null>(null);
  const [confirmLeave, setConfirmLeave] = useState(false);
  const latest = useRef<LocalMatchRecord | null>(null);

  useEffect(() => {
    let alive = true;
    void loadMatch(id).then((r) => alive && setRecord(r));
    return () => {
      alive = false;
    };
  }, [id]);

  const update = useCallback(async (next: LocalMatchRecord) => {
    latest.current = next;
    setRecord(next);
    await saveMatch(next);
  }, []);

  useEffect(() => {
    latest.current = record ?? null;
  }, [record]);

  // Drive the AI partner whenever it owes a decision (announce or submit).
  useEffect(() => {
    if (!record) return;
    const task = pendingAiTask(record);
    if (!task) return;
    let cancelled = false;
    setAiThinking(true);
    const started = Date.now();
    void askAi(task).then(async (answer) => {
      // A short beat so the partner feels like a partner, not a vending machine.
      const wait = Math.max(0, (task.kind === 'submit' ? 500 : 150) - (Date.now() - started));
      await new Promise((r) => setTimeout(r, wait));
      if (cancelled || !latest.current) return;
      setAiThinking(false);
      await update(applyAiAnswer(latest.current, task, answer));
    });
    return () => {
      cancelled = true;
    };
  }, [record, update]);

  useEffect(() => {
    if (record && record.core.state.status !== 'in_progress') {
      void personalBests().then((all) => setPb(all[record.routeId] ?? null));
    }
  }, [record]);

  if (record === undefined) return <Screen><p className="p-8 text-center text-cream">Loading climb…</p></Screen>;
  if (record === null)
    return (
      <Screen>
        <ScreenHeader title="Game not found" onBack={() => navigate({ name: 'home' })} />
        <Panel>This saved game could not be found on this device.</Panel>
      </Screen>
    );

  const route = getRoute(record.routeId);
  const { state } = record.core;
  const human = humanRoleOf(record);
  const role: Role = human ?? record.activeRole ?? 'climber';
  const names = { climber: record.players.climber.name, belayer: record.players.belayer.name };
  const showReveal = !!record.lastResult && !record.revealSeen;
  const finished = state.status !== 'in_progress';
  const modeLabel = record.mode === 'solo' ? `Solo · AI partner (${record.players[otherRole(role)].difficulty})` : 'Pass & Play';

  const onSubmit = (sub: Submission) => void update(submitHuman(record, sub));

  const nextRoute = ROUTES.find((r) => r.order === route.order + 1);

  return (
    <GameScreen>
      <CompactHeader
        title={route.name}
        subtitle={`${route.grade} · ${modeLabel}`}
        onBack={() => navigate({ name: 'home' })}
        right={
          !finished && (
            <Button variant="ghost" size="sm" onClick={() => setConfirmLeave(true)}>
              Give up
            </Button>
          )
        }
      />

      {record.mode === 'pass_and_play' && record.handoff && !finished && !showReveal ? (
        <Handoff role={record.activeRole ?? 'climber'} name={names[record.activeRole ?? 'climber']} round={state.round} onReady={() => void update(acceptHandoff(record))} />
      ) : finished && !showReveal ? (
        <div className="mx-auto flex min-h-0 w-full max-w-lg flex-1 flex-col justify-center overflow-y-auto">
          <ResultsPanel
            state={state}
            route={route}
            personalBest={pb}
            onRematch={() => {
              const r = rematchLocal(record);
              void saveMatch(r).then(() => navigate({ name: 'local', id: r.id }, true));
            }}
            onNextRoute={
              state.status === 'won' && nextRoute
                ? () => {
                    const r = rematchLocal(record, nextRoute.id);
                    void saveMatch(r).then(() => navigate({ name: 'local', id: r.id }, true));
                  }
                : null
            }
            onHome={() => navigate({ name: 'home' })}
          />
        </div>
      ) : (
        <GameTable
          route={route}
          state={state}
          role={role}
          names={names}
          myCommitted={!!record.core.pending[role]}
          partnerCommitted={!!record.core.pending[otherRole(role)]}
          partner={record.core.declarations[otherRole(role)]}
          mine={record.core.declarations[role]}
          busy={aiThinking}
          onSubmit={onSubmit}
          banner={
            aiThinking ? (
              <div className="self-start rounded-xl bg-pine-950/80 px-3 py-1.5 text-sm font-bold text-cream" role="status">
                {names[otherRole(role)]} is thinking…
              </div>
            ) : null
          }
        />
      )}

      <AnimatePresence>
        {showReveal && record.lastResult && (
          <Resolution
            key={record.lastResult.round}
            result={record.lastResult}
            route={route}
            clippedAfter={state.clippedBolts}
            names={names}
            onDone={() => void update(markRevealSeen(record))}
          />
        )}
      </AnimatePresence>

      <AnimatePresence>
        {confirmLeave && (
          <motion.div className="fixed inset-0 z-50 grid place-items-center bg-black/60 p-4" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} role="dialog" aria-modal="true" aria-label="Give up this climb?">
            <Panel className="max-w-sm">
              <h2 className="font-display text-2xl font-bold">Lower off?</h2>
              <p className="mt-1 text-ink-soft">This ends the climb as a failed ascent. You can always start again.</p>
              <div className="mt-4 flex gap-2">
                <Button variant="secondary" className="flex-1" onClick={() => setConfirmLeave(false)}>
                  Keep climbing
                </Button>
                <Button
                  variant="danger"
                  className="flex-1"
                  onClick={() => {
                    setConfirmLeave(false);
                    void update(forfeitLocal(record));
                  }}
                >
                  Give up
                </Button>
              </div>
            </Panel>
          </motion.div>
        )}
      </AnimatePresence>
    </GameScreen>
  );
}

/** Pass-and-play privacy screen: covers the whole table until the right player is holding the device. */
function Handoff({ role, name, round, onReady }: { role: Role; name: string; round: number; onReady: () => void }) {
  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="mx-auto flex max-w-md flex-1 flex-col items-center justify-center gap-5 text-center" data-testid="handoff">
      <div className={`grid h-20 w-20 place-items-center rounded-full ${role === 'climber' ? 'bg-ember-deep' : 'bg-turquoise-deep'} text-cream shadow-[var(--shadow-lift)]`}>
        <IconLock size={36} />
      </div>
      <div>
        <div className="text-xs font-black uppercase tracking-[0.3em] text-sand/70">Round {round}</div>
        <h2 className="font-display mt-1 text-3xl font-bold text-cream">Pass the device to {name}</h2>
        <p className="mt-2 text-sand/80">The {role}'s turn is private. Everyone else, look away — no peeking at the cards!</p>
      </div>
      <Button size="lg" variant="rope" onClick={onReady} data-testid="handoff-ready">
        <IconEye /> I'm {name} — show my cards
      </Button>
    </motion.div>
  );
}
