import { motion, useReducedMotion } from 'motion/react';

/** Friendly illustrated climber, drawn around its hands at (0, 0). */
export function Climber({ highlight = false, celebrating = false }: { highlight?: boolean; celebrating?: boolean }) {
  const reduced = useReducedMotion();
  return (
    <g aria-hidden>
      {highlight && <circle cx={4} cy={12} r={26} fill="#fbf5ea" opacity={0.22} />}
      <motion.g
        animate={celebrating && !reduced ? { y: [0, -8, 0] } : { y: 0 }}
        transition={celebrating ? { repeat: Infinity, duration: 0.9 } : { duration: 0.2 }}
      >
        {/* legs */}
        <path d="M2,22 L-6,36 L-10,44" stroke="#2a3b4a" strokeWidth={5} strokeLinecap="round" fill="none" />
        <path d="M8,22 L16,32 L14,42" stroke="#2a3b4a" strokeWidth={5} strokeLinecap="round" fill="none" />
        <path d="M-13,45 l6,0" stroke="#1d2422" strokeWidth={4} strokeLinecap="round" />
        <path d="M12,43 l6,0" stroke="#1d2422" strokeWidth={4} strokeLinecap="round" />
        {/* torso */}
        <rect x={-3} y={4} width={15} height={20} rx={6} fill="#3f9c94" />
        {/* harness */}
        <rect x={-4} y={19} width={17} height={5} rx={2} fill="#e07a3f" />
        <circle cx={4} cy={24} r={2.5} fill="#e9b44c" />
        {/* arms reaching up to the hold */}
        {celebrating ? (
          <>
            <path d="M0,8 L-12,-8" stroke="#e8b48c" strokeWidth={4.5} strokeLinecap="round" />
            <path d="M10,8 L22,-8" stroke="#e8b48c" strokeWidth={4.5} strokeLinecap="round" />
          </>
        ) : (
          <>
            <path d="M0,8 L-6,-2" stroke="#e8b48c" strokeWidth={4.5} strokeLinecap="round" />
            <path d="M10,8 L8,-3" stroke="#e8b48c" strokeWidth={4.5} strokeLinecap="round" />
          </>
        )}
        {/* head + helmet */}
        <circle cx={5} cy={-1} r={6.5} fill="#e8b48c" />
        <path d="M-2,-2 a7.2,7.2 0 0 1 14,0 z" fill="#e07a3f" />
        <rect x={-2.5} y={-3} width={15} height={2.4} rx={1.2} fill="#c8643b" />
        <circle cx={7.5} cy={1} r={1} fill="#1d2422" />
      </motion.g>
    </g>
  );
}

/** Belayer standing at the base, rope through a device at the waist. */
export function Belayer({ x, y, highlight = false }: { x: number; y: number; highlight?: boolean }) {
  return (
    <g aria-hidden transform={`translate(${x},${y})`}>
      {highlight && <ellipse cx={0} cy={-30} rx={26} ry={36} fill="#fbf5ea" opacity={0.18} />}
      <path d="M-5,-18 L-8,-2" stroke="#3b3a5a" strokeWidth={6} strokeLinecap="round" />
      <path d="M5,-18 L8,-2" stroke="#3b3a5a" strokeWidth={6} strokeLinecap="round" />
      <path d="M-11,-1 l6,0 M6,-1 l6,0" stroke="#1d2422" strokeWidth={4} strokeLinecap="round" />
      <rect x={-9} y={-44} width={18} height={27} rx={7} fill="#c8643b" />
      <rect x={-10} y={-22} width={20} height={5} rx={2} fill="#2f8f83" />
      <path d="M-7,-38 L4,-26 L12,-26" stroke="#d9a07a" strokeWidth={4.5} strokeLinecap="round" fill="none" />
      <path d="M8,-38 L14,-30" stroke="#d9a07a" strokeWidth={4.5} strokeLinecap="round" />
      <rect x={8} y={-28} width={6} height={7} rx={2} fill="#4b5257" />
      <circle cx={0} cy={-52} r={8} fill="#d9a07a" />
      <path d="M-8,-54 a8.4,8.4 0 0 1 16,0 z" fill="#2f5d50" />
      <rect x={-8.5} y={-55} width={17} height={2.4} rx={1.2} fill="#1e3d34" />
      <circle cx={3} cy={-51} r={1.1} fill="#1d2422" />
    </g>
  );
}
