import type { ReactNode } from 'react';
import type { GameState, RouteDefinition } from '../../engine/types.ts';
import { IconBolt, IconClock, IconHeart, IconRope, IconStamina, IconTeam } from '../ui/Icons.tsx';

/**
 * Shared status bar: stamina, rope, recovery and round on one row, protection and Teamwork on a
 * second short row. Compact enough for a phone screen with no scrolling.
 */
export function Hud({ state, route, emphasis, dense = false }: { state: GameState; route: RouteDefinition; emphasis: 'climber' | 'belayer' | 'neutral'; dense?: boolean }) {
  const runout = state.position - state.lastClippedPosition;
  const nextBolt = route.bolts.find((b) => b > state.position);
  const roundsLeft = state.config.maxRounds - state.round + 1;
  return (
    <div className="paper rounded-2xl px-2.5 py-1.5 text-ink shadow-[var(--shadow-card)]" aria-label="Team status" data-testid="hud">
      <div className="grid grid-cols-[auto_auto_auto_1fr] items-center gap-x-3">
        <Meter
          label="Stamina"
          value={state.stamina}
          max={state.config.maxStamina}
          color="#e07a3f"
          icon={<IconStamina size={14} />}
          strong={emphasis === 'climber'}
        />
        <Meter label="Rope" value={state.rope} max={state.config.ropeMax} color="#b8862d" icon={<IconRope size={14} />} strong={emphasis === 'belayer'} />
        <Meter label="Recovery" value={state.recoveryTokens} max={state.config.recoveryTokens} color="var(--bad)" icon={<IconHeart size={14} />} />
        <div className="justify-self-end text-right leading-none">
          <div className="text-[0.56rem] font-black uppercase tracking-wider text-ink-soft">Round</div>
          <div className="flex items-center justify-end gap-1 text-sm font-extrabold tabular-nums">
            <IconClock size={13} className="text-pine-600" />
            {state.round}/{state.config.maxRounds}
          </div>
          <div className={`text-[0.6rem] font-bold ${roundsLeft <= 3 ? 'text-danger' : 'text-ink-soft'}`}>{roundsLeft} left</div>
        </div>
      </div>
      <div className={`mt-1 flex flex-wrap items-center gap-x-2.5 border-t ${dense ? 'tiny:hidden' : ''} border-black/10 pt-1 text-[0.66rem] font-bold leading-tight text-ink-soft`}>
        <span className="flex items-center gap-0.5">
          <IconBolt size={12} /> Clip: {state.lastClippedPosition === 0 ? 'ground' : `bolt ${state.lastClippedPosition}`}
        </span>
        {runout >= 3 && <span className="rounded bg-[var(--warn)] px-1 text-ink">runout {runout}: big fall</span>}
        <span>Height {state.position}/{route.length}</span>
        {nextBolt && <span>Next bolt {nextBolt}</span>}
        <span className="flex items-center gap-0.5">
          <IconTeam size={12} /> Teamwork {state.teamworkAvailable ? 'ready' : 'used'}
        </span>
      </div>
    </div>
  );
}

function Meter({ label, value, max, color, icon, strong }: { label: string; value: number; max: number; color: string; icon: ReactNode; strong?: boolean }) {
  return (
    <div className="min-w-0 leading-none" role="meter" aria-label={`${label} ${value} of ${max}`} aria-valuemin={0} aria-valuemax={max} aria-valuenow={value}>
      <div className={`text-[0.56rem] font-black uppercase tracking-wider ${strong ? 'text-ink' : 'text-ink-soft'}`}>{label}</div>
      <div className="mt-0.5 flex items-center gap-1">
        <span style={{ color }} aria-hidden>
          {icon}
        </span>
        <span className="flex gap-[2px]" aria-hidden>
          {Array.from({ length: max }, (_, i) => (
            <span key={i} className="h-2.5 w-2.5 rounded-full border-[1.5px]" style={{ borderColor: color, background: i < value ? color : 'transparent' }} />
          ))}
        </span>
        <span className="text-xs font-extrabold tabular-nums">{value}</span>
      </div>
    </div>
  );
}
