import { useEffect, useState } from 'react';
import { navigate } from '../app/router.tsx';
import { useSettings } from '../app/settings.tsx';
import { Avatar } from '../components/ui/Avatar.tsx';
import { Button, Panel, Screen, ScreenHeader } from '../components/ui/Primitives.tsx';
import { ROUTES, getRoute } from '../data/routes/index.ts';
import type { Role } from '../engine/types.ts';
import { createGame, joinGame, listMyOnlineGames, type OnlineGameSummary } from '../multiplayer/api.ts';
import { ensureSession } from '../multiplayer/auth.ts';
import { onlineConfigured } from '../multiplayer/client.ts';
import { useOnline } from '../hooks/useOnline.ts';
import { roomCodeSchema } from '../schemas/index.ts';
import { ProfileScreen } from './ProfileScreen.tsx';
import { Choice } from './SetupScreen.tsx';

export function OnlineScreen({ joinCode }: { joinCode?: string }) {
  const { profile } = useSettings();
  const online = useOnline();
  const [routeId, setRouteId] = useState(ROUTES[0]!.id);
  const [role, setRole] = useState<Role>('climber');
  const [code, setCode] = useState(joinCode ?? '');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [games, setGames] = useState<OnlineGameSummary[] | null>(null);
  const [identityReady, setIdentityReady] = useState(false);

  useEffect(() => {
    if (!onlineConfigured || !online) return;
    ensureSession()
      .then(() => {
        setIdentityReady(true);
        return listMyOnlineGames().then(setGames);
      })
      .catch((e: unknown) => setError(e instanceof Error ? e.message : String(e)));
  }, [online]);

  // Arriving from an invite link: join straight away once we have a nickname and identity.
  useEffect(() => {
    if (joinCode && profile.nickname && identityReady && !busy) void join(joinCode);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [joinCode, profile.nickname, identityReady]);

  if (!onlineConfigured) {
    return (
      <Screen>
        <ScreenHeader title="Play Online" onBack={() => navigate({ name: 'home' })} />
        <Panel className="mx-auto max-w-lg">
          <h2 className="font-display text-xl font-bold">Online play isn't set up in this build</h2>
          <p className="mt-2 text-ink-soft">
            This copy of On Belay was built without a game server (Supabase) configuration. Offline solo and pass-and-play work fully. See DEPLOYMENT.md to connect a server.
          </p>
          <Button className="mt-4" onClick={() => navigate({ name: 'setup', mode: 'solo' })}>
            Play offline instead
          </Button>
        </Panel>
      </Screen>
    );
  }

  if (!profile.nickname) {
    return <ProfileScreen onDone={() => undefined} />;
  }

  async function create() {
    setBusy(true);
    setError(null);
    try {
      const r = await createGame(routeId, role, profile.nickname, profile.avatar);
      navigate({ name: 'lobby', gameId: r.gameId });
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  }

  async function join(raw: string) {
    const parsed = roomCodeSchema.safeParse(raw);
    if (!parsed.success) return setError(parsed.error.issues[0]?.message ?? 'Invalid code');
    setBusy(true);
    setError(null);
    try {
      const r = await joinGame(parsed.data, profile.nickname, profile.avatar);
      navigate({ name: 'lobby', gameId: r.gameId }, true);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  }

  return (
    <Screen>
      <ScreenHeader
        title="Play Online"
        subtitle="Take turns whenever suits you — hours apart is fine"
        onBack={() => navigate({ name: 'home' })}
        right={
          <button type="button" onClick={() => navigate({ name: 'profile' })} className="focus-ring flex items-center gap-2 rounded-full bg-white/10 py-1 pl-1 pr-3 text-sm font-bold text-cream" aria-label="Edit profile">
            <Avatar id={profile.avatar} size={32} /> {profile.nickname}
          </button>
        }
      />
      {!online && <Panel className="mb-3 text-sm font-bold">You're offline. Connect to create or join an online game.</Panel>}
      {error && (
        <Panel className="mb-3 border-2 border-danger text-sm font-bold" as="div">
          <span role="alert">{error}</span>
        </Panel>
      )}
      <div className="grid gap-4 lg:grid-cols-3">
        <Panel>
          <h2 className="font-display text-xl font-bold">Join a friend</h2>
          <p className="text-sm text-ink-soft">Enter the 6-character room code they sent you.</p>
          <input
            className="focus-ring mt-2 block min-h-14 w-full rounded-xl border border-black/15 bg-white px-3 text-center font-mono text-2xl font-bold uppercase tracking-[0.3em]"
            value={code}
            maxLength={6}
            onChange={(e) => setCode(e.target.value.toUpperCase())}
            placeholder="ABC234"
            aria-label="Room code"
            autoCapitalize="characters"
            autoComplete="off"
            data-testid="room-code-input"
          />
          <Button className="mt-3 w-full" onClick={() => void join(code)} disabled={busy || !online || code.length !== 6} data-testid="join-room">
            Join room
          </Button>
        </Panel>
        <Panel className="lg:col-span-2">
          <h2 className="font-display text-xl font-bold">Start a private climb</h2>
          <div className="mt-2 grid gap-3 sm:grid-cols-2">
            <div className="flex flex-col gap-2" role="radiogroup" aria-label="Route">
              {ROUTES.map((r) => (
                <Choice key={r.id} selected={routeId === r.id} onClick={() => setRouteId(r.id)} title={`${r.name} · ${r.grade}`} detail={r.terrain} testId={`online-route-${r.id}`} />
              ))}
            </div>
            <div className="flex flex-col gap-2" role="radiogroup" aria-label="Preferred role">
              <Choice selected={role === 'climber'} onClick={() => setRole('climber')} title="I'll climb" detail="Your friend belays" testId="online-role-climber" />
              <Choice selected={role === 'belayer'} onClick={() => setRole('belayer')} title="I'll belay" detail="Your friend climbs" testId="online-role-belayer" />
              <Button className="mt-auto" onClick={() => void create()} disabled={busy || !online} data-testid="create-room">
                Create room
              </Button>
            </div>
          </div>
        </Panel>
      </div>
      {games && games.length > 0 && (
        <section className="mt-5">
          <h2 className="font-display mb-2 text-xl font-bold text-cream">Your online games</h2>
          <div className="grid gap-2 md:grid-cols-2">
            {games.map((g) => (
              <Panel key={g.id} className="flex items-center justify-between gap-3" as="article">
                <div className="min-w-0">
                  <div className="font-display truncate text-lg font-bold">{getRoute(g.routeId).name}</div>
                  <div className="text-sm text-ink-soft">
                    Room {g.roomCode} · {g.role ?? '—'} · {g.statusText}
                  </div>
                </div>
                <Button size="sm" variant={g.yourTurn ? 'primary' : 'secondary'} onClick={() => navigate(g.status === 'lobby' ? { name: 'lobby', gameId: g.id } : { name: 'onlineGame', gameId: g.id })}>
                  {g.yourTurn ? 'Your move' : 'Open'}
                </Button>
              </Panel>
            ))}
          </div>
        </section>
      )}
    </Screen>
  );
}
