import { diceForRound } from './rng.ts';
import { RulesError, forfeit, resolveRound } from './resolve.ts';
import { createInitialState } from './state.ts';
import type {
  BelayerSubmission,
  ClimberSubmission,
  GameConfig,
  GameState,
  PublicDeclaration,
  Role,
  RouteDefinition,
  Submission,
  TurnResult,
} from './types.ts';
import { DEFAULT_CONFIG } from './config.ts';

/**
 * A locally-held match: the game state plus the hidden pending submissions and the dice seed.
 * Used by offline modes (solo vs AI, pass-and-play) and the balance simulator. Online games keep
 * the same three pieces server-side, split across tables so the private parts stay private.
 */
export interface MatchCore {
  seed: string;
  state: GameState;
  pending: { climber: ClimberSubmission | null; belayer: BelayerSubmission | null };
  /** Public declarations (signal + Teamwork preference) made this round. */
  declarations: { climber: PublicDeclaration | null; belayer: PublicDeclaration | null };
  /** Increments on every accepted change. */
  version: number;
}

export function createMatchCore(route: RouteDefinition, seed: string, config: GameConfig = DEFAULT_CONFIG): MatchCore {
  return {
    seed,
    state: createInitialState(route, config),
    pending: { climber: null, belayer: null },
    declarations: { climber: null, belayer: null },
    version: 0,
  };
}

/** Publish a signal / Teamwork preference before committing. Does not commit an action. */
export function declare(m: MatchCore, role: Role, decl: Omit<PublicDeclaration, 'committed'>): MatchCore {
  if (m.state.status !== 'in_progress') throw new RulesError('game is over');
  if (m.pending[role]) throw new RulesError(`${role} has already committed this round`);
  return {
    ...m,
    declarations: { ...m.declarations, [role]: { ...decl, committed: false } },
    version: m.version + 1,
  };
}

export interface SubmitOutcome {
  match: MatchCore;
  resolved: TurnResult | null;
}

/**
 * Commit one player's private submission. If both are in, resolve the round with the match's
 * deterministic per-round dice and clear the pending actions.
 */
export function submit(m: MatchCore, route: RouteDefinition, sub: Submission, expectedRound?: number): SubmitOutcome {
  if (m.state.status !== 'in_progress') throw new RulesError('game is over');
  if (expectedRound !== undefined && expectedRound !== m.state.round) throw new RulesError('stale round');
  if (m.pending[sub.role]) throw new RulesError(`${sub.role} has already committed this round`);

  const pending = { ...m.pending, [sub.role]: sub } as MatchCore['pending'];
  const declarations = {
    ...m.declarations,
    [sub.role]: { signal: sub.signal, teamworkPolicy: sub.teamworkPolicy, committed: true },
  } as MatchCore['declarations'];

  if (pending.climber && pending.belayer) {
    const { state, result } = resolveRound(
      m.state,
      route,
      { climber: pending.climber, belayer: pending.belayer },
      diceForRound(m.seed, m.state.round),
    );
    return {
      match: {
        seed: m.seed,
        state,
        pending: { climber: null, belayer: null },
        declarations: { climber: null, belayer: null },
        version: m.version + 1,
      },
      resolved: result,
    };
  }
  return { match: { ...m, pending, declarations, version: m.version + 1 }, resolved: null };
}

export function forfeitMatch(m: MatchCore): MatchCore {
  return { ...m, state: forfeit(m.state), pending: { climber: null, belayer: null }, version: m.version + 1 };
}

export type TurnPhase =
  | 'waiting_for_both'
  | 'waiting_for_climber'
  | 'waiting_for_belayer'
  | 'ready_to_resolve'
  | 'route_completed'
  | 'route_failed';

export function phaseOf(status: GameState['status'], climberCommitted: boolean, belayerCommitted: boolean): TurnPhase {
  if (status === 'won') return 'route_completed';
  if (status === 'lost') return 'route_failed';
  if (climberCommitted && belayerCommitted) return 'ready_to_resolve';
  if (climberCommitted) return 'waiting_for_belayer';
  if (belayerCommitted) return 'waiting_for_climber';
  return 'waiting_for_both';
}
