import { DEFAULT_CONFIG } from './config.ts';
import type { BelayerAction, ClimberAction, GameConfig, GameState, GameStats, RouteDefinition } from './types.ts';

export function emptyStats(): GameStats {
  const belayerActionCounts: Record<BelayerAction, number> = { FEED: 0, TAKE_IN: 0, BRACE: 0, ENCOURAGE: 0 };
  const climberActionCounts: Record<ClimberAction, number> = { STEP: 0, REACH: 0, CLIP: 0, REST: 0 };
  return {
    falls: 0,
    tokensLost: 0,
    blockedActions: 0,
    rests: 0,
    clips: 0,
    teamworkUsedRound: null,
    teamworkUse: null,
    belayerActionCounts,
    climberActionCounts,
  };
}

/** Create the initial state for a route. */
export function createInitialState(route: RouteDefinition, config: GameConfig = DEFAULT_CONFIG): GameState {
  return {
    routeId: route.id,
    config: { ...config },
    status: 'in_progress',
    round: 1,
    position: 0,
    stamina: config.startStamina,
    rope: config.startRope,
    lastClippedPosition: 0,
    clippedBolts: [],
    recoveryTokens: config.recoveryTokens,
    teamworkAvailable: config.teamworkTokens > 0,
    stats: emptyStats(),
    history: [],
    result: null,
  };
}

/** Structural deep clone; state is plain JSON. */
export function cloneState(state: GameState): GameState {
  return JSON.parse(JSON.stringify(state)) as GameState;
}

/** Invariants that must hold for every reachable state. Returns a list of violations. */
export function checkInvariants(state: GameState, route: RouteDefinition): string[] {
  const v: string[] = [];
  const c = state.config;
  if (state.position < 0 || state.position > route.length) v.push(`position ${state.position} out of range`);
  if (state.stamina < 0 || state.stamina > c.maxStamina) v.push(`stamina ${state.stamina} out of range`);
  if (state.rope < c.ropeMin || state.rope > c.ropeMax) v.push(`rope ${state.rope} out of range`);
  if (state.recoveryTokens < 0 || state.recoveryTokens > c.recoveryTokens) v.push(`recovery ${state.recoveryTokens} out of range`);
  if (state.round < 1 || state.round > c.maxRounds) v.push(`round ${state.round} out of range`);
  if (state.lastClippedPosition !== 0 && !state.clippedBolts.includes(state.lastClippedPosition)) {
    v.push('lastClippedPosition is not a clipped bolt');
  }
  if (state.clippedBolts.some((b) => !route.bolts.includes(b))) v.push('clipped a non-bolt position');
  if (state.position < state.lastClippedPosition) v.push('climber is below the last clipped bolt');
  if (state.status === 'won' && state.position !== route.length) v.push('won without reaching the anchor');
  if (state.status === 'in_progress' && state.position === route.length) v.push('at anchor but still in progress');
  if (state.status === 'in_progress' && state.recoveryTokens <= 0) v.push('no recovery tokens but still in progress');
  return v;
}
