import { motion } from 'motion/react';
import type { ButtonHTMLAttributes, ReactNode } from 'react';
import { IconBack } from './Icons.tsx';

type Variant = 'primary' | 'secondary' | 'ghost' | 'danger' | 'rope';

const VARIANTS: Record<Variant, string> = {
  primary: 'bg-ember-deep text-cream shadow-[0_4px_0_#6e3311] hover:brightness-110 active:translate-y-[2px] active:shadow-[0_2px_0_#6e3311]',
  secondary: 'bg-cream text-pine-900 shadow-[0_4px_0_#c9b48f] hover:brightness-[1.02] active:translate-y-[2px] active:shadow-[0_2px_0_#c9b48f]',
  ghost: 'bg-white/10 text-cream hover:bg-white/15 border border-white/15',
  danger: 'bg-danger text-cream shadow-[0_4px_0_#7a2419] active:translate-y-[2px]',
  rope: 'bg-rope text-pine-950 shadow-[0_4px_0_#9c7224] active:translate-y-[2px] active:shadow-[0_2px_0_#9c7224]',
};

export function Button({
  variant = 'primary',
  className = '',
  children,
  size = 'md',
  ...rest
}: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: Variant; size?: 'sm' | 'md' | 'lg' }) {
  const sizes = { sm: 'min-h-10 px-4 text-sm', md: 'min-h-12 px-5 text-base', lg: 'min-h-14 px-6 text-lg' };
  return (
    <button
      type="button"
      className={`focus-ring inline-flex items-center justify-center gap-2 rounded-2xl font-extrabold tracking-wide transition disabled:opacity-45 disabled:shadow-none ${sizes[size]} ${VARIANTS[variant]} ${className}`}
      {...rest}
    >
      {children}
    </button>
  );
}

export function Panel({ children, className = '', as: As = 'section' }: { children: ReactNode; className?: string; as?: 'section' | 'div' | 'article' }) {
  return <As className={`paper rounded-[var(--radius-card)] p-4 text-ink shadow-[var(--shadow-card)] ${className}`}>{children}</As>;
}

export function ScreenHeader({ title, onBack, right, subtitle }: { title: string; subtitle?: string; onBack?: () => void; right?: ReactNode }) {
  return (
    <header className="flex items-center gap-3 py-2">
      {onBack && (
        <button type="button" onClick={onBack} className="focus-ring grid h-11 w-11 place-items-center rounded-full bg-white/10 text-cream" aria-label="Back">
          <IconBack />
        </button>
      )}
      <div className="min-w-0 flex-1">
        <h1 className="font-display truncate text-2xl font-bold text-cream">{title}</h1>
        {subtitle && <p className="truncate text-sm text-sand/80">{subtitle}</p>}
      </div>
      {right}
    </header>
  );
}

export function Screen({ children, className = '' }: { children: ReactNode; className?: string }) {
  return (
    <motion.main
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.25 }}
      className={`forest-bg safe-pad min-h-full ${className}`}
    >
      <div className="mx-auto w-full max-w-5xl">{children}</div>
    </motion.main>
  );
}

export function Pill({ children, className = '' }: { children: ReactNode; className?: string }) {
  return <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-extrabold ${className}`}>{children}</span>;
}

/** A row of pips for small counts (stamina, rope, tokens). Shows the number too. */
export function Pips({ value, max, label, color, icon }: { value: number; max: number; label: string; color: string; icon?: ReactNode }) {
  return (
    <div className="flex min-w-0 items-center gap-1.5" role="meter" aria-label={label} aria-valuemin={0} aria-valuemax={max} aria-valuenow={value}>
      {icon && <span className="shrink-0" style={{ color }}>{icon}</span>}
      <div className="flex gap-[3px]" aria-hidden>
        {Array.from({ length: max }, (_, i) => (
          <span
            key={i}
            className="h-3 w-3 rounded-full border-2 transition-colors sm:h-3.5 sm:w-3.5"
            style={{ borderColor: color, background: i < value ? color : 'transparent' }}
          />
        ))}
      </div>
      <span className="text-sm font-extrabold tabular-nums">{value}</span>
    </div>
  );
}

export function Toggle({ checked, onChange, label, description }: { checked: boolean; onChange: (v: boolean) => void; label: string; description?: string }) {
  return (
    <label className="flex min-h-12 cursor-pointer items-center justify-between gap-4 py-2">
      <span>
        <span className="block font-bold">{label}</span>
        {description && <span className="block text-sm text-ink-soft">{description}</span>}
      </span>
      <span className="relative inline-flex shrink-0">
        <input type="checkbox" role="switch" className="peer sr-only" checked={checked} onChange={(e) => onChange(e.target.checked)} />
        <span className="h-8 w-14 rounded-full bg-granite/50 transition peer-checked:bg-turquoise peer-focus-visible:outline peer-focus-visible:outline-3 peer-focus-visible:outline-rope" />
        <span className="absolute left-1 top-1 h-6 w-6 rounded-full bg-white shadow transition peer-checked:translate-x-6" />
      </span>
    </label>
  );
}

/**
 * Full-viewport screen for play: never scrolls as a page. Children lay out in a column and the
 * flexible part (the wall) absorbs whatever height the device has.
 */
export function GameScreen({ children, className = '' }: { children: ReactNode; className?: string }) {
  return (
    <main
      className={`forest-bg fixed inset-0 flex flex-col overflow-hidden ${className}`}
      style={{
        paddingTop: 'max(var(--safe-top), 0.5rem)',
        paddingBottom: 'max(var(--safe-bottom), 0.5rem)',
        paddingLeft: 'max(var(--safe-left), 0.75rem)',
        paddingRight: 'max(var(--safe-right), 0.75rem)',
      }}
    >
      <div className="mx-auto flex min-h-0 w-full max-w-5xl flex-1 flex-col gap-2 overflow-y-auto">{children}</div>
    </main>
  );
}

export function CompactHeader({ title, subtitle, onBack, right }: { title: string; subtitle?: string; onBack?: () => void; right?: ReactNode }) {
  return (
    <header className="flex shrink-0 items-center gap-2">
      {onBack && (
        <button type="button" onClick={onBack} className="focus-ring grid h-10 w-10 shrink-0 place-items-center rounded-full bg-white/10 text-cream" aria-label="Back">
          <IconBack size={20} />
        </button>
      )}
      <div className="min-w-0 flex-1 leading-tight">
        <h1 className="font-display truncate text-lg font-bold text-cream">{title}</h1>
        {subtitle && <p className="truncate text-xs text-sand/80">{subtitle}</p>}
      </div>
      {right}
    </header>
  );
}
