import { useOnline } from '../../hooks/useOnline.ts';
import { IconWifiOff } from './Icons.tsx';

/** Global offline indicator. Offline modes keep working; online games show their own state. */
export function NetworkBanner() {
  const online = useOnline();
  if (online) return null;
  return (
    <div className="fixed inset-x-0 top-0 z-[60] flex items-center justify-center gap-2 bg-ink/95 px-3 py-1.5 pt-[max(var(--safe-top),0.375rem)] text-sm font-bold text-cream" role="status" data-testid="offline-banner">
      <IconWifiOff size={16} /> You're offline. Solo and pass-and-play still work; online moves wait until you reconnect.
    </div>
  );
}
