import { motion } from 'motion/react';
import { useEffect, useState } from 'react';
import { navigate } from '../app/router.tsx';
import { useSettings } from '../app/settings.tsx';
import { IconBook, IconMountain, IconPlay, IconSettings, IconUsers } from '../components/ui/Icons.tsx';
import { Logo } from '../components/ui/Logo.tsx';
import { Button, GameScreen } from '../components/ui/Primitives.tsx';
import { listMatches } from '../offline/repository.ts';
import { unlockAudio } from '../audio/sound.ts';
import { onlineConfigured } from '../multiplayer/client.ts';

export function HomeScreen() {
  const { profile } = useSettings();
  const [resumable, setResumable] = useState(0);
  useEffect(() => {
    void listMatches().then((m) => setResumable(m.filter((r) => r.core.state.status === 'in_progress').length));
  }, []);

  const go = (fn: () => void) => () => {
    unlockAudio();
    fn();
  };

  return (
    <GameScreen>
      <HeroArt />
      <div className="relative z-10 flex min-h-0 flex-1 flex-col items-center justify-between gap-3">
        <div className="absolute right-0 top-0 z-20">
          <button
            type="button"
            onClick={() => navigate({ name: 'settings' })}
            className="focus-ring grid h-11 w-11 place-items-center rounded-full bg-white/10 text-cream"
            aria-label="Settings"
          >
            <IconSettings />
          </button>
        </div>
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.6 }} className="flex flex-col items-center pt-8 tiny:pt-4">
          <Logo />
          <p className="font-display mt-3 max-w-xs text-center text-xl italic text-sand tiny:mt-1 tiny:text-base">Two players. One rope. One shared ascent.</p>
        </motion.div>

        <motion.nav
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.2, duration: 0.5 }}
          className="flex w-full max-w-sm flex-col gap-2.5"
          aria-label="Main menu"
        >
          {resumable > 0 && (
            <Button variant="rope" size="lg" onClick={go(() => navigate({ name: 'continue' }))} data-testid="continue-game">
              Continue game <span className="rounded-full bg-pine-900/20 px-2 text-sm">{resumable}</span>
            </Button>
          )}
          <Button size="lg" onClick={go(() => navigate({ name: 'online' }))} data-testid="play-online">
            <IconUsers /> Play Online
          </Button>
          <Button variant="secondary" size="lg" onClick={go(() => navigate({ name: 'setup', mode: 'solo' }))} data-testid="play-offline">
            <IconPlay /> Play Offline
          </Button>
          <div className="grid grid-cols-2 gap-2.5">
            <Button variant="ghost" onClick={go(() => navigate({ name: profile.tutorialDone ? 'rules' : 'tutorial' }))}>
              <IconBook size={20} /> How to Play
            </Button>
            <Button variant="ghost" onClick={go(() => navigate({ name: 'routes' }))}>
              <IconMountain size={20} /> Routes
            </Button>
          </div>
          {!onlineConfigured && <p className="text-center text-xs text-sand/60">Online play needs a server connection configured for this build.</p>}
        </motion.nav>
        <footer className="text-center text-[0.66rem] text-sand/55 tiny:hidden">
          A game, not climbing instruction. Learn real rope skills from a qualified instructor.
        </footer>
      </div>
    </GameScreen>
  );
}

/** Layered mountain scene behind the menu. */
function HeroArt() {
  return (
    <svg className="pointer-events-none absolute inset-x-0 bottom-0 h-[65%] w-full" viewBox="0 0 400 300" preserveAspectRatio="xMidYMax slice" aria-hidden>
      <defs>
        <linearGradient id="hero-fade" x1="0" x2="0" y1="0" y2="1">
          <stop offset="0" stopColor="#16302a" stopOpacity="0" />
          <stop offset="1" stopColor="#0f201b" stopOpacity="0.9" />
        </linearGradient>
      </defs>
      <path d="M0 210 L60 130 L100 170 L160 80 L210 150 L260 100 L320 170 L400 120 L400 300 L0 300 Z" fill="#36685a" opacity="0.55" />
      <path d="M160 80 L176 102 L166 98 L156 110 L148 97 Z" fill="#fbf5ea" opacity="0.7" />
      <path d="M0 240 L70 190 L130 230 L200 170 L270 230 L340 190 L400 220 L400 300 L0 300 Z" fill="#2a5246" />
      {Array.from({ length: 18 }, (_, i) => (
        <path key={i} transform={`translate(${i * 24 - 4},${262 + (i % 3) * 6}) scale(${0.8 + (i % 4) * 0.15})`} d="M0,-40 L12,-14 L6,-14 L15,0 L-15,0 L-6,-14 L-12,-14 Z" fill="#16302a" />
      ))}
      <rect width="400" height="300" fill="url(#hero-fade)" />
    </svg>
  );
}
