import { z } from 'zod';
import {
  BELAYER_ACTIONS,
  BELAYER_SIGNALS,
  CLIMBER_ACTIONS,
  CLIMBER_SIGNALS,
  TEAMWORK_POLICIES,
} from '../engine/types.ts';

/** Schemas for data crossing a trust boundary: network payloads, IndexedDB, URL params. */

export const roleSchema = z.enum(['climber', 'belayer']);
export const teamworkPolicySchema = z.enum(TEAMWORK_POLICIES);

export const climberSubmissionSchema = z.object({
  role: z.literal('climber'),
  action: z.enum(CLIMBER_ACTIONS),
  signal: z.enum(CLIMBER_SIGNALS).nullable(),
  teamworkPolicy: teamworkPolicySchema,
});

export const belayerSubmissionSchema = z.object({
  role: z.literal('belayer'),
  action: z.enum(BELAYER_ACTIONS),
  signal: z.enum(BELAYER_SIGNALS).nullable(),
  teamworkPolicy: teamworkPolicySchema,
});

export const submissionSchema = z.discriminatedUnion('role', [climberSubmissionSchema, belayerSubmissionSchema]);

export const roomCodeSchema = z
  .string()
  .trim()
  .toUpperCase()
  .regex(/^[A-HJ-NP-Z2-9]{6}$/, 'Room codes are 6 letters and numbers');

export const nicknameSchema = z.string().trim().min(1, 'Pick a nickname').max(20, 'Keep it under 20 characters');

/** Minimal structural check of a stored game state; the engine re-validates on every action. */
export const gameStateShape = z
  .object({
    routeId: z.string(),
    status: z.enum(['in_progress', 'won', 'lost']),
    round: z.number().int().min(1),
    position: z.number().int().min(0),
    stamina: z.number().int().min(0),
    rope: z.number().int().min(0),
    lastClippedPosition: z.number().int().min(0),
    clippedBolts: z.array(z.number().int()),
    recoveryTokens: z.number().int().min(0),
    teamworkAvailable: z.boolean(),
    history: z.array(z.unknown()),
  })
  .passthrough();
