import { AnimatePresence, motion } from 'motion/react';
import { useMemo, useState } from 'react';
import { navigate } from '../app/router.tsx';
import { useSettings } from '../app/settings.tsx';
import { ClimbingWall } from '../components/climbing/ClimbingWall.tsx';
import { ActionPanel } from '../components/game/ActionPanel.tsx';
import { PartnerSignal } from '../components/game/GameTable.tsx';
import { Hud } from '../components/game/Hud.tsx';
import { Resolution } from '../components/game/Resolution.tsx';
import { Button, CompactHeader, GameScreen, Panel } from '../components/ui/Primitives.tsx';
import { FIRST_ASCENT } from '../data/routes/index.ts';
import { resolveRound } from '../engine/resolve.ts';
import { scriptedDice } from '../engine/rng.ts';
import { createInitialState } from '../engine/state.ts';
import type { BelayerSubmission, ClimberSubmission, GameState, Role, Submission, TurnResult } from '../engine/types.ts';

/**
 * Interactive tutorial. Every lesson is a real round resolved by the real engine; only the dice
 * and the partner's card are scripted so each lesson shows exactly one idea.
 */
interface Lesson {
  title: string;
  coach: string;
  role?: Role;
  only?: Submission['action'];
  partner?: ClimberSubmission | BelayerSubmission;
  dice?: number[];
  setup?: Partial<GameState>;
  after?: string;
}

const route = FIRST_ASCENT;
const climberPartner = (action: ClimberSubmission['action'], signal: ClimberSubmission['signal']): ClimberSubmission => ({ role: 'climber', action, signal, teamworkPolicy: 'NEVER' });
const belayerPartner = (action: BelayerSubmission['action'], signal: BelayerSubmission['signal']): BelayerSubmission => ({ role: 'belayer', action, signal, teamworkPolicy: 'NEVER' });

const LESSONS: Lesson[] = [
  {
    title: 'Two players, one rope',
    coach:
      'One of you climbs, one of you belays. Each round you both pick a card in secret, lock it in, and then both cards are revealed together. Reach the anchor at the top within 14 rounds — together.',
  },
  {
    title: 'Climber: Step',
    coach: 'You are the climber. Step moves you up one hold. It costs 1 stamina, needs 1 rope, and you roll a die: you need at least the number on the next hold (3 here). Your belayer will Feed you rope.',
    role: 'climber',
    only: 'STEP',
    partner: belayerPartner('FEED', 'ROPE_AVAILABLE'),
    dice: [4],
    after: 'The belayer’s card happens first: their Feed gave you the rope your Step used.',
  },
  {
    title: 'Rope is the tempo',
    coach: 'Every move uses rope, and your belayer can feed only 1 a round. Step again — notice the rope counter in the status board.',
    role: 'climber',
    only: 'STEP',
    partner: belayerPartner('FEED', 'ROPE_AVAILABLE'),
    dice: [5],
  },
  {
    title: 'Clip the bolt',
    coach: 'You’re at a bolt. Clipping protects you: if you fall, you stop at your last clipped bolt. Clip needs 2 rope (it uses 1) and always succeeds.',
    role: 'climber',
    only: 'CLIP',
    partner: belayerPartner('FEED', 'ROPE_AVAILABLE'),
  },
  {
    title: 'Encouragement',
    coach: 'The next hold is a 4. Your belayer is going to Encourage you, which adds +1 to your roll. Step up!',
    role: 'climber',
    only: 'STEP',
    partner: belayerPartner('ENCOURAGE', 'READY_FOR_MOVEMENT'),
    dice: [3],
    after: 'A 3 plus Encourage made 4 — just enough.',
  },
  {
    title: 'Rest holds',
    coach: 'You’re tired. This ledge is a rest hold: Rest here restores 3 stamina (elsewhere only 1). Rest is always allowed and uses no rope.',
    role: 'climber',
    only: 'REST',
    partner: belayerPartner('FEED', 'ROPE_AVAILABLE'),
  },
  {
    title: 'Dice and falls',
    coach: 'Not every move goes. Step for the next hold and see what happens when the die says no.',
    role: 'climber',
    only: 'STEP',
    partner: belayerPartner('FEED', 'STAY_STEADY'),
    dice: [1],
    after: 'A fall costs Recovery tokens (the team has 4). You drop one hold — but never below your last clipped bolt.',
  },
  {
    title: 'Belayer: Feed',
    coach: 'Now you are the belayer. Your climber signals “Going for a big move”: a Reach, which needs 2 rope. There is only 1 out. Feed, so the move is legal.',
    role: 'belayer',
    only: 'FEED',
    partner: climberPartner('REACH', 'BIG_MOVE'),
    dice: [6],
    setup: { position: 4, rope: 1, stamina: 5, clippedBolts: [2], lastClippedPosition: 2, round: 6 },
  },
  {
    title: 'Belayer: Brace',
    coach: 'Your climber is 3 holds above the last clip: if they fall it will be a big one (2 tokens). Brace absorbs the extra token.',
    role: 'belayer',
    only: 'BRACE',
    partner: climberPartner('STEP', 'MOVING_CAREFULLY'),
    dice: [1],
    setup: { position: 5, rope: 1, stamina: 4, clippedBolts: [2], lastClippedPosition: 2, round: 7 },
    after: 'Thanks to your Brace the fall cost 1 token, not 2.',
  },
  {
    title: 'Playing apart',
    coach:
      'Online, you don’t need to play at the same time. Lock in your card and leave — your partner can answer minutes or hours later, and the round resolves the moment both cards are in. Your card stays secret until then; your signal does not. Once per climb, the Teamwork token can rescue a move that is 1 rope short, or save a roll that missed by 1.',
  },
];

export function TutorialScreen() {
  const { updateProfile } = useSettings();
  const [i, setI] = useState(0);
  const [state, setState] = useState<GameState>(() => createInitialState(route));
  const [reveal, setReveal] = useState<TurnResult | null>(null);
  const lesson = LESSONS[i]!;
  const shown = useMemo(() => (lesson.setup ? { ...state, ...lesson.setup } : state), [state, lesson]);

  const next = () => {
    if (i + 1 >= LESSONS.length) {
      updateProfile({ tutorialDone: true });
      navigate({ name: 'setup', mode: 'solo' });
      return;
    }
    setI(i + 1);
  };

  const onSubmit = (sub: Submission) => {
    const input = sub.role === 'climber' ? { climber: sub, belayer: lesson.partner as BelayerSubmission } : { climber: lesson.partner as ClimberSubmission, belayer: sub };
    const { state: after, result } = resolveRound(shown, route, input, scriptedDice(lesson.dice ?? []));
    setState(after);
    setReveal(result);
  };

  return (
    <GameScreen>
      <CompactHeader
        title="Tutorial"
        subtitle={`Lesson ${i + 1} of ${LESSONS.length}`}
        onBack={() => navigate({ name: 'home' })}
        right={
          <Button size="sm" variant="ghost" onClick={() => { updateProfile({ tutorialDone: true }); navigate({ name: 'rules' }); }}>
            Skip
          </Button>
        }
      />
      <div className="h-1.5 shrink-0 overflow-hidden rounded-full bg-white/10" aria-hidden>
        <motion.div className="h-full bg-rope" animate={{ width: `${((i + 1) / LESSONS.length) * 100}%` }} />
      </div>
      <div className="flex min-h-0 flex-1 flex-col gap-2 lg:flex-row lg:gap-4">
        <div className="relative min-h-[8rem] flex-1 overflow-hidden rounded-3xl border-[3px] border-cream/90 short:min-h-[5rem] tiny:min-h-[3rem]">
          <ClimbingWall className="absolute inset-0 block h-full w-full" fit="follow" route={route} position={shown.position} clippedBolts={shown.clippedBolts} rope={shown.rope} showReach={!!lesson.role} perspective={lesson.role ?? 'neutral'} />
          {lesson.partner && (
            <div className="absolute left-2 top-2 max-w-[88%]">
              <PartnerSignal role={lesson.partner.role} decl={{ signal: lesson.partner.signal, teamworkPolicy: 'NEVER', committed: true }} name={lesson.partner.role === 'climber' ? 'Juniper' : 'Rowan'} />
            </div>
          )}
        </div>
        <div className="flex shrink-0 flex-col gap-1.5 lg:w-[26rem] lg:justify-end">
          <AnimatePresence mode="wait">
            <motion.div key={i} initial={{ opacity: 0, x: 12 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -12 }}>
              <Panel className="!p-3 short:!py-2">
                <h2 className="font-display text-lg font-bold leading-tight tiny:text-base" data-testid="lesson-title">
                  {lesson.title}
                </h2>
                <p className="mt-0.5 text-sm leading-snug short:text-[0.8rem] tiny:text-[0.74rem] tiny:leading-tight">{lesson.coach}</p>
                {!lesson.role && (
                  <Button className="mt-2 w-full" onClick={next} data-testid="lesson-next">
                    {i + 1 >= LESSONS.length ? 'Start climbing' : 'Next'}
                  </Button>
                )}
              </Panel>
            </motion.div>
          </AnimatePresence>
          {lesson.role && (
            <>
              <Hud state={shown} route={route} emphasis={lesson.role} dense />
              <ActionPanel key={i} role={lesson.role} state={shown} route={route} partner={null} only={lesson.only} hideExtras onSubmit={onSubmit} />
            </>
          )}
        </div>
      </div>
      <AnimatePresence>
        {reveal && (
          <Resolution
            key={`${i}-${reveal.round}`}
            result={reveal}
            route={route}
            clippedAfter={state.clippedBolts}
            names={{ climber: lesson.role === 'climber' ? 'You' : 'Juniper', belayer: lesson.role === 'belayer' ? 'You' : 'Rowan' }}
            onDone={() => {
              setReveal(null);
              next();
            }}
          />
        )}
      </AnimatePresence>
      {reveal && lesson.after && (
        <div className="pointer-events-none fixed inset-x-0 top-2 z-50 mx-auto max-w-md px-3">
          <div className="rounded-2xl bg-rope px-4 py-2 text-center text-sm font-black text-pine-950 shadow-[var(--shadow-lift)]">{lesson.after}</div>
        </div>
      )}
    </GameScreen>
  );
}
