import { BLOCK_REASON_TEXT } from './legality.ts';
import { BELAYER_ACTION_INFO, CLIMBER_ACTION_INFO } from './labels.ts';
import type { TurnResult } from './types.ts';

export interface TurnExplanation {
  headline: string;
  lines: string[];
  tips: string[];
}

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`;

/** Human-readable explanation of a resolved round, shared by every client and the server log. */
export function explainTurn(r: TurnResult): TurnExplanation {
  const c = CLIMBER_ACTION_INFO[r.climber.action].name;
  const b = BELAYER_ACTION_INFO[r.belayer.action].name;
  const lines: string[] = [`Climber played ${c}. Belayer played ${b}.`];
  const tips: string[] = [];

  if (r.ropeAfterBelay !== r.ropeBefore) {
    lines.push(`Rope went from ${r.ropeBefore} to ${r.ropeAfterBelay}.`);
  }
  if (r.teamwork === 'RESCUE') lines.push('Teamwork! The shared token added 1 rope so the move could go ahead.');

  let headline: string;
  switch (r.outcome) {
    case 'blocked': {
      headline = 'Move blocked';
      lines.push(`${BLOCK_REASON_TEXT[r.blockedReason ?? 'not_enough_rope']} The climber lost 1 stamina hesitating.`);
      if (r.blockedReason === 'not_enough_rope') {
        tips.push(
          r.climber.action === 'STEP'
            ? 'Step needs 1 rope. The belayer can Feed in the same round to make it possible.'
            : `${c} needs 2 rope. Feeding ahead of time, or a Teamwork rescue, keeps the climber moving.`,
        );
      } else if (r.blockedReason === 'not_enough_stamina') {
        tips.push('Out of stamina? Rest — it is always legal, and rest holds restore 3.');
      } else {
        tips.push('Use signals to agree on a plan before committing.');
      }
      break;
    }
    case 'rested':
      headline = r.restedOnRestHold ? 'A good rest' : 'A quick shake-out';
      lines.push(`Stamina recovered to ${r.staminaAfter}${r.restedOnRestHold ? ' on a rest hold' : ''}.`);
      if (r.belayer.action === 'FEED') tips.push('Feeding while the climber rests banks rope for a big move next round.');
      break;
    case 'clipped':
      headline = 'Clipped!';
      lines.push(`The bolt at position ${r.clipped} is clipped. Falls now stop here.`);
      break;
    case 'moved':
    case 'summit':
    case 'fell': {
      const roll = r.roll!;
      const bonus: string[] = [];
      if (roll.encourageBonus) bonus.push(`+${roll.encourageBonus} Encourage`);
      if (roll.teamworkBonus) bonus.push(`+${roll.teamworkBonus} Teamwork`);
      lines.push(
        `Rolled ${roll.die}${bonus.length ? ` ${bonus.join(' ')} = ${roll.adjusted}` : ''} against a target of ${roll.target}.`,
      );
      if (r.outcome === 'fell') {
        const fall = r.fall!;
        headline = 'Fall!';
        const why: string[] = [];
        if (fall.causes.includes('rope_slack')) why.push('there was a lot of rope out (3)');
        if (fall.causes.includes('runout')) {
          why.push(`the climber was ${fall.from - fall.lastClipped} positions above ${fall.lastClipped ? 'the last clip' : 'the ground'}`);
        }
        if (why.length) lines.push(`It was a big fall because ${why.join(' and ')}.`);
        if (fall.bracePrevented) lines.push('The belayer’s Brace absorbed the extra impact.');
        lines.push(`Lost ${plural(fall.totalLoss, 'Recovery token')}. The climber is back at position ${fall.returnTo}.`);
        if (fall.extraLoss && !fall.bracePrevented) tips.push('Bracing when a fall would be big saves a Recovery token.');
        if (fall.causes.includes('runout')) tips.push('Clipping bolts keeps falls short — they stop at the last clip.');
        if (fall.causes.includes('rope_slack')) tips.push('With 3 rope out, falls are bigger. Taking In or moving keeps slack down.');
        if (!roll.encourageBonus) tips.push('Encourage adds +1 to the roll on hard moves.');
        if (r.climber.action === 'REACH') tips.push('Reach is 1 harder than Step. Step is safer on tough holds.');
      } else if (r.outcome === 'summit') {
        headline = 'Summit!';
        lines.push(`Reached the anchor at position ${r.positionAfter}.`);
      } else {
        headline = r.climber.action === 'REACH' ? 'Big move sent!' : 'Moving up';
        lines.push(`Now at position ${r.positionAfter}.`);
      }
      if (r.teamwork === 'CONVERT') lines.push('Teamwork! The shared token turned a near-miss into a success.');
      break;
    }
  }

  if (r.statusAfter === 'lost') {
    lines.push(r.recoveryAfter <= 0 ? 'Out of Recovery tokens — the team has to lower off.' : 'Out of rounds — the light is fading.');
  }
  return { headline, lines, tips: tips.slice(0, 2) };
}
