import { motion, useReducedMotion } from 'motion/react';
import { summarize } from '../../engine/scoring.ts';
import type { GameState, RouteDefinition } from '../../engine/types.ts';
import { CarabinerRow } from '../ui/Carabiner.tsx';
import { art } from '../../art/art.ts';
import { Button, Panel } from '../ui/Primitives.tsx';

const REASON: Record<string, string> = {
  summit: 'You topped out together!',
  out_of_recovery: 'Out of Recovery tokens — time to lower off and try again.',
  out_of_rounds: 'The light faded before you reached the anchor.',
  forfeit: 'The climb was abandoned.',
};

export interface ResultsPanelProps {
  state: GameState;
  route: RouteDefinition;
  personalBest?: { bestCarabiners: number; fewestRounds: number | null } | null;
  onRematch?: () => void;
  onHome: () => void;
  onNextRoute?: (() => void) | null;
  rematchLabel?: string;
}

export function ResultsPanel({ state, route, personalBest, onRematch, onHome, onNextRoute, rematchLabel }: ResultsPanelProps) {
  const s = summarize(state);
  const won = s.outcome === 'won';
  const reduced = useReducedMotion();
  return (
    <div className="relative" data-testid="results" data-outcome={s.outcome}>
      {won && !reduced && <Confetti />}
      <Panel className="relative z-10 flex flex-col items-center gap-2 text-center short:!p-3">
        <div className="text-xs font-black uppercase tracking-[0.3em] text-ink-soft">
          {route.name} · {route.grade}
        </div>
        {(() => {
          const scene = art(won ? 'summit' : 'failed');
          if (scene) return <img src={scene.url} alt="" aria-hidden className="h-32 w-auto rounded-xl object-cover shadow-md short:h-20 tiny:hidden" draggable={false} />;
          const pic = art(won ? 'climber-summit' : 'climber-fall');
          return pic ? <img src={pic.url} alt="" aria-hidden className="h-28 w-auto object-contain short:h-20 tiny:hidden" draggable={false} /> : null;
        })()}
        <h2 className={`font-display text-4xl font-bold short:text-3xl ${won ? 'text-pine-700' : 'text-terracotta'}`} data-testid="results-headline">
          {won ? 'Summit!' : 'Failed ascent'}
        </h2>
        <p className="max-w-sm text-sm text-ink-soft">{REASON[state.result?.reason ?? 'forfeit']}</p>
        {won && <CarabinerRow count={s.carabiners} size={26} />}
        <dl className="grid w-full grid-cols-3 gap-1.5 text-left">
          <Stat label="Rounds used" value={`${s.roundsUsed} / ${state.config.maxRounds}`} />
          <Stat label="Falls" value={s.falls} />
          <Stat label="Recovery left" value={`${s.recoveryRemaining} / ${state.config.recoveryTokens}`} />
          <Stat label="Bolts clipped" value={`${s.boltsClipped} / ${route.bolts.length}`} />
          <Stat label="Teamwork" value={s.teamworkUse === 'RESCUE' ? 'Rescued a move' : s.teamworkUse === 'CONVERT' ? 'Saved a roll' : 'Unused'} />
          <Stat label="Carabiners" value={`${s.carabiners} / 3`} />
        </dl>
        {personalBest && (
          <p className="text-xs font-bold text-ink-soft" data-testid="personal-best">
            Personal best on this route: {personalBest.bestCarabiners} carabiner{personalBest.bestCarabiners === 1 ? '' : 's'}
            {personalBest.fewestRounds !== null ? ` · fastest ${personalBest.fewestRounds} rounds` : ''}
          </p>
        )}
        <div className="text-left text-[0.66rem] leading-snug text-ink-soft">
          1 carabiner: complete · 2: finish with 2+ Recovery tokens · 3: finish within {state.config.threeCarabinerRounds} rounds without losing a token
        </div>
        <div className="flex w-full flex-wrap gap-2 [&>*]:min-w-[40%] [&>*]:flex-1">
          {onRematch && (
            <Button className="flex-1" onClick={onRematch} data-testid="rematch">
              {rematchLabel ?? 'Climb it again'}
            </Button>
          )}
          {onNextRoute && (
            <Button variant="rope" className="flex-1" onClick={onNextRoute}>
              Next route
            </Button>
          )}
          <Button variant="secondary" className="flex-1" onClick={onHome}>
            Home
          </Button>
        </div>
      </Panel>
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string | number }) {
  return (
    <div className="min-w-0 rounded-xl bg-sand/70 px-2 py-1.5">
      <dt className="truncate text-[0.58rem] font-black uppercase tracking-wider text-ink-soft">{label}</dt>
      <dd className="text-sm font-extrabold leading-tight">{value}</dd>
    </div>
  );
}

function Confetti() {
  const pieces = Array.from({ length: 28 }, (_, i) => i);
  const colors = ['#e9b44c', '#e07a3f', '#3f9c94', '#fbf5ea', '#c8643b'];
  return (
    <div className="pointer-events-none absolute inset-0 z-20 overflow-visible" aria-hidden>
      {pieces.map((i) => (
        <motion.span
          key={i}
          className="absolute top-0 block h-2.5 w-1.5 rounded-sm"
          style={{ left: `${(i * 37) % 100}%`, background: colors[i % colors.length] }}
          initial={{ y: -20, opacity: 1, rotate: 0 }}
          animate={{ y: 420 + (i % 5) * 40, opacity: 0, rotate: 360 * (i % 2 ? 1 : -1) }}
          transition={{ duration: 2.2 + (i % 4) * 0.3, delay: (i % 7) * 0.08, ease: 'easeOut' }}
        />
      ))}
    </div>
  );
}
