import { useEffect, useState } from 'react';

/**
 * Minimal hash router. Hash routes work on any static host, inside an installed PWA and inside
 * a Capacitor web view without server rewrites. Invite links look like `#/join/ABC234`.
 */
export type Route =
  | { name: 'home' }
  | { name: 'setup'; mode: 'solo' | 'pass_and_play' | 'online' }
  | { name: 'local'; id: string }
  | { name: 'online' }
  | { name: 'join'; code: string }
  | { name: 'lobby'; gameId: string }
  | { name: 'onlineGame'; gameId: string }
  | { name: 'tutorial' }
  | { name: 'rules' }
  | { name: 'routes' }
  | { name: 'settings' }
  | { name: 'continue' }
  | { name: 'profile' }
  | { name: 'editor' };

export function parseHash(hash: string): Route {
  const parts = hash.replace(/^#\/?/, '').split('/').filter(Boolean).map(decodeURIComponent);
  const [a, b] = parts;
  switch (a) {
    case undefined:
      return { name: 'home' };
    case 'setup':
      return { name: 'setup', mode: b === 'pass_and_play' || b === 'online' ? b : 'solo' };
    case 'local':
      return b ? { name: 'local', id: b } : { name: 'home' };
    case 'online':
      return { name: 'online' };
    case 'join':
      return b ? { name: 'join', code: b } : { name: 'online' };
    case 'lobby':
      return b ? { name: 'lobby', gameId: b } : { name: 'online' };
    case 'game':
      return b ? { name: 'onlineGame', gameId: b } : { name: 'online' };
    case 'tutorial':
    case 'rules':
    case 'routes':
    case 'settings':
    case 'continue':
    case 'profile':
    case 'editor':
      return { name: a };
    default:
      return { name: 'home' };
  }
}

export function href(route: Route): string {
  switch (route.name) {
    case 'home':
      return '#/';
    case 'setup':
      return `#/setup/${route.mode}`;
    case 'local':
      return `#/local/${encodeURIComponent(route.id)}`;
    case 'join':
      return `#/join/${encodeURIComponent(route.code)}`;
    case 'lobby':
      return `#/lobby/${encodeURIComponent(route.gameId)}`;
    case 'onlineGame':
      return `#/game/${encodeURIComponent(route.gameId)}`;
    default:
      return `#/${route.name}`;
  }
}

export function navigate(route: Route, replace = false) {
  const target = href(route);
  if (replace) window.location.replace(target);
  else window.location.hash = target;
}

export function useRoute(): Route {
  const [route, setRoute] = useState<Route>(() => parseHash(window.location.hash));
  useEffect(() => {
    const onChange = () => {
      setRoute(parseHash(window.location.hash));
      window.scrollTo(0, 0);
    };
    window.addEventListener('hashchange', onChange);
    return () => window.removeEventListener('hashchange', onChange);
  }, []);
  return route;
}
