import { AnimatePresence, motion } from 'motion/react';
import { useEffect, useRef, useState } from 'react';
import { BELAYER_ACTION_INFO, BELAYER_SIGNAL_TEXT, CLIMBER_ACTION_INFO, CLIMBER_SIGNAL_TEXT } from '../../engine/labels.ts';
import { explainTurn } from '../../engine/narrative.ts';
import type { RouteDefinition, TurnResult } from '../../engine/types.ts';
import { sfx } from '../../audio/sound.ts';
import { useSettings } from '../../app/settings.tsx';
import { ClimbingWall } from '../climbing/ClimbingWall.tsx';
import { Button } from '../ui/Primitives.tsx';
import { CardArt } from './CardArt.tsx';
import { RollingDie } from './Dice.tsx';

type Stage = 'cards' | 'rope' | 'roll' | 'outcome';

export interface ResolutionProps {
  result: TurnResult;
  route: RouteDefinition;
  clippedAfter: readonly number[];
  names: { climber: string; belayer: string };
  onDone(): void;
}

/**
 * The reveal. Both committed cards flip together, then rope, dice and the outcome play in order.
 * Everything shown comes from the already-resolved TurnResult: the view never decides anything.
 */
export function Resolution({ result, route, clippedAfter, names, onDone }: ResolutionProps) {
  const { settings } = useSettings();
  const [stage, setStage] = useState<Stage>('cards');
  const [flipped, setFlipped] = useState(false);
  const skipped = useRef(false);
  const explanation = explainTurn(result);
  const clippedBefore = result.clipped === null ? clippedAfter : clippedAfter.filter((b) => b !== result.clipped);

  useEffect(() => {
    const t1 = window.setTimeout(() => {
      setFlipped(true);
      sfx('reveal');
    }, 350);
    const t2 = window.setTimeout(() => {
      if (skipped.current) return;
      setStage('rope');
      if (result.ropeAfterBelay !== result.ropeBefore || result.teamwork === 'RESCUE') sfx('rope');
    }, 1500);
    const t3 = window.setTimeout(() => {
      if (skipped.current) return;
      if (result.roll) {
        setStage('roll');
        sfx('dice');
      } else {
        setStage('outcome');
        playOutcome(result);
      }
    }, 2400);
    return () => [t1, t2, t3].forEach((t) => window.clearTimeout(t));
  }, [result]);

  useEffect(() => {
    if (stage === 'outcome' && settings.autoContinue && result.statusAfter === 'in_progress') {
      const t = window.setTimeout(onDone, 3500);
      return () => window.clearTimeout(t);
    }
    return undefined;
  }, [stage, settings.autoContinue, onDone, result.statusAfter]);

  const showAfter = stage === 'outcome';
  const rope = stage === 'cards' ? result.ropeBefore : showAfter ? result.ropeAfter : result.ropeAfterBelay + (result.teamwork === 'RESCUE' ? 1 : 0);
  const c = CLIMBER_ACTION_INFO[result.climber.action];
  const b = BELAYER_ACTION_INFO[result.belayer.action];

  return (
    <motion.div
      className="fixed inset-0 z-40 overflow-hidden bg-pine-950/95 backdrop-blur-sm"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      role="dialog"
      aria-modal="true"
      aria-label={`Round ${result.round} resolution`}
      data-testid="resolution"
    >
      <div
        className="mx-auto flex h-full w-full max-w-4xl flex-col gap-2"
        style={{
          paddingTop: 'max(var(--safe-top), 0.5rem)',
          paddingBottom: 'max(var(--safe-bottom), 0.5rem)',
          paddingLeft: 'max(var(--safe-left), 0.75rem)',
          paddingRight: 'max(var(--safe-right), 0.75rem)',
        }}
      >
        <div className="flex shrink-0 items-center justify-between gap-2">
          <h2 className="font-display text-xl font-bold text-cream">Round {result.round} reveal</h2>
          {stage !== 'outcome' && (
            <button
              type="button"
              className="focus-ring min-h-10 rounded-full px-3 text-sm font-bold text-sand/80 underline"
              onClick={() => {
                skipped.current = true;
                setFlipped(true);
                setStage('outcome');
                playOutcome(result);
              }}
            >
              Skip animation
            </button>
          )}
        </div>

        <div className="flex min-h-0 flex-1 flex-col gap-2 lg:flex-row">
          <div className="relative min-h-[8rem] flex-1 overflow-hidden rounded-3xl border-[3px] border-cream/80">
            <ClimbingWall
              className="absolute inset-0 block h-full w-full"
              fit="follow"
              route={route}
              position={showAfter ? result.positionAfter : result.positionBefore}
              clippedBolts={showAfter ? clippedAfter : clippedBefore}
              rope={rope}
              fallFrom={showAfter && result.fall ? result.fall.from : null}
              summit={showAfter && result.outcome === 'summit'}
              climberPose={result.climber.action === 'REACH' ? 'reach' : result.climber.action === 'CLIP' ? 'clip' : result.climber.action === 'REST' ? 'rest' : 'climb'}
              belayerPose={result.belayer.action === 'FEED' ? 'feed' : result.belayer.action === 'BRACE' ? 'brace' : result.belayer.action === 'ENCOURAGE' ? 'cheer' : 'belay'}
            />
            <div className="absolute inset-x-2 top-2 grid grid-cols-2 gap-2">
              {(['climber', 'belayer'] as const).map((role) => {
                const sub = role === 'climber' ? result.climber : result.belayer;
                const info = role === 'climber' ? c : b;
                const signal = sub.signal
                  ? role === 'climber'
                    ? CLIMBER_SIGNAL_TEXT[sub.signal as keyof typeof CLIMBER_SIGNAL_TEXT]
                    : BELAYER_SIGNAL_TEXT[sub.signal as keyof typeof BELAYER_SIGNAL_TEXT]
                  : null;
                return (
                  <motion.div
                    key={role}
                    animate={{ rotateY: flipped ? 0 : 180 }}
                    transition={{ duration: 0.5, ease: 'easeInOut' }}
                    style={{ transformStyle: 'preserve-3d' }}
                    className="min-w-0"
                  >
                    {flipped ? (
                      <div className="paper overflow-hidden rounded-xl shadow-[var(--shadow-card)]" data-revealed-action={sub.action} role="img" aria-label={`${names[role]} played ${info.name}`}>
                        <div className={`${role === 'climber' ? 'bg-ember-deep' : 'bg-turquoise-deep'} flex items-center gap-1.5 px-2 py-1`}>
                          <span className="font-display text-base font-bold leading-none text-cream">{info.name}</span>
                        </div>
                        <div className="flex items-center gap-1.5 px-1.5 py-1">
                          <div className="h-8 w-10 shrink-0 rounded bg-sand/70 p-0.5">
                            <CardArt action={sub.action} />
                          </div>
                          <div className="min-w-0 text-[0.62rem] leading-tight">
                            <div className="truncate font-black uppercase text-ink-soft">
                              {names[role]} · {role}
                            </div>
                            {signal && <div className="truncate italic text-ink-soft">“{signal}”</div>}
                          </div>
                        </div>
                      </div>
                    ) : (
                      <div className="grid h-[4.3rem] place-items-center rounded-xl border-2 border-cream bg-pine-700 text-[0.7rem] font-black uppercase tracking-wider text-cream/80" aria-label="Hidden card">
                        {role}
                      </div>
                    )}
                  </motion.div>
                );
              })}
            </div>
          </div>

          <div className="flex shrink-0 flex-col justify-end lg:w-[24rem]">
            <AnimatePresence mode="wait">
              {(stage === 'cards' || stage === 'rope') && (
                <motion.p key="rope" initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="grid min-h-[5.5rem] place-items-center text-center text-lg font-bold text-cream">
                  {stage === 'cards'
                    ? 'Revealing both cards…'
                    : result.ropeAfterBelay !== result.ropeBefore
                      ? `Rope ${result.ropeBefore} → ${result.ropeAfterBelay}`
                      : `Rope stays at ${result.ropeBefore}`}
                  {stage === 'rope' && result.teamwork === 'RESCUE' && <span className="block text-sm text-rope">Teamwork token: +1 rope to rescue the move!</span>}
                </motion.p>
              )}
              {stage === 'roll' && result.roll && (
                <motion.div key="roll" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex min-h-[5.5rem] items-center justify-center gap-4">
                  <RollingDie
                    value={result.roll.die}
                    onSettled={() =>
                      window.setTimeout(() => {
                        if (skipped.current) return;
                        setStage('outcome');
                        playOutcome(result);
                      }, 650)
                    }
                  />
                  <p className="text-lg font-bold text-cream">
                    Need {result.roll.target}+
                    {result.roll.encourageBonus ? <span className="block text-sm">+1 Encourage</span> : null}
                  </p>
                </motion.div>
              )}
              {stage === 'outcome' && (
                <motion.div
                  key="outcome"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="paper max-h-[52dvh] overflow-y-auto rounded-2xl p-3 shadow-[var(--shadow-lift)]"
                  data-testid="outcome"
                >
                  <div className="flex items-baseline justify-between gap-2">
                    <h3
                      className={`font-display text-2xl font-bold leading-tight ${result.outcome === 'fell' || result.outcome === 'blocked' ? 'text-terracotta' : 'text-pine-700'}`}
                      data-testid="outcome-headline"
                    >
                      {explanation.headline}
                    </h3>
                    {result.roll && (
                      <span className="shrink-0 text-xs font-bold text-ink-soft">
                        Rolled {result.roll.die}
                        {result.roll.encourageBonus ? ' +1' : ''}
                        {result.roll.teamworkBonus ? ' +1 TW' : ''} · need {result.roll.target}
                      </span>
                    )}
                  </div>
                  <ul className="mt-1 space-y-0.5 text-sm leading-snug">
                    {explanation.lines
                      .slice(1)
                      .filter((l) => !l.startsWith('Rolled '))
                      .map((l, i) => (
                        <li key={i}>{l}</li>
                      ))}
                  </ul>
                  {explanation.tips[0] && (
                    <p className="mt-1.5 rounded-lg bg-sand/70 px-2 py-1 text-xs">
                      <b className="uppercase tracking-wide text-pine-700">Next time:</b> {explanation.tips[0]}
                    </p>
                  )}
                  <Button className="mt-2 w-full" size="lg" onClick={onDone} data-testid="continue">
                    {result.statusAfter === 'in_progress' ? 'Continue climbing' : 'See results'}
                  </Button>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </div>
      </div>
    </motion.div>
  );
}

function playOutcome(r: TurnResult) {
  switch (r.outcome) {
    case 'fell':
      sfx('fall');
      break;
    case 'summit':
      sfx('summit');
      break;
    case 'clipped':
      sfx('clip');
      break;
    case 'rested':
      sfx('rest');
      break;
    case 'blocked':
      sfx('blocked');
      break;
    default:
      sfx('success');
  }
}
