import { MotionConfig } from 'motion/react';
import { useEffect } from 'react';
import { configureAudio } from '../audio/sound.ts';
import { ContinueScreen } from '../screens/ContinueScreen.tsx';
import { HomeScreen } from '../screens/HomeScreen.tsx';
import { LobbyScreen } from '../screens/LobbyScreen.tsx';
import { LocalGameScreen } from '../screens/LocalGameScreen.tsx';
import { OnlineGameScreen } from '../screens/OnlineGameScreen.tsx';
import { OnlineScreen } from '../screens/OnlineScreen.tsx';
import { ProfileScreen } from '../screens/ProfileScreen.tsx';
import { RouteEditorScreen } from '../screens/RouteEditorScreen.tsx';
import { RoutesScreen } from '../screens/RoutesScreen.tsx';
import { RulesScreen } from '../screens/RulesScreen.tsx';
import { SettingsScreen } from '../screens/SettingsScreen.tsx';
import { SetupScreen } from '../screens/SetupScreen.tsx';
import { TutorialScreen } from '../screens/TutorialScreen.tsx';
import { useRoute } from './router.tsx';
import { SettingsProvider, useSettings } from './settings.tsx';
import { NetworkBanner } from '../components/ui/NetworkBanner.tsx';

function Routes() {
  const route = useRoute();
  const { settings, ready } = useSettings();
  useEffect(() => configureAudio(settings), [settings]);
  if (!ready) return <div className="forest-bg grid min-h-full place-items-center text-cream">Loading…</div>;

  let screen;
  switch (route.name) {
    case 'home':
      screen = <HomeScreen />;
      break;
    case 'setup':
      screen = <SetupScreen mode={route.mode} />;
      break;
    case 'local':
      screen = <LocalGameScreen key={route.id} id={route.id} />;
      break;
    case 'online':
      screen = <OnlineScreen />;
      break;
    case 'join':
      screen = <OnlineScreen joinCode={route.code} />;
      break;
    case 'lobby':
      screen = <LobbyScreen key={route.gameId} gameId={route.gameId} />;
      break;
    case 'onlineGame':
      screen = <OnlineGameScreen key={route.gameId} gameId={route.gameId} />;
      break;
    case 'tutorial':
      screen = <TutorialScreen />;
      break;
    case 'rules':
      screen = <RulesScreen />;
      break;
    case 'routes':
      screen = <RoutesScreen />;
      break;
    case 'settings':
      screen = <SettingsScreen />;
      break;
    case 'continue':
      screen = <ContinueScreen />;
      break;
    case 'profile':
      screen = <ProfileScreen />;
      break;
    case 'editor':
      screen = <RouteEditorScreen />;
      break;
  }
  return (
    <MotionConfig reducedMotion={settings.reducedMotion ? 'always' : 'user'}>
      <NetworkBanner />
      {screen}
    </MotionConfig>
  );
}

export function App() {
  return (
    <SettingsProvider>
      <Routes />
    </SettingsProvider>
  );
}
