import { motion } from 'motion/react';
import type { ReactNode } from 'react';
import { BELAYER_SIGNAL_TEXT, CLIMBER_SIGNAL_TEXT, TEAMWORK_POLICY_TEXT } from '../../engine/labels.ts';
import { phaseOf, type TurnPhase } from '../../engine/match.ts';
import { explainTurn } from '../../engine/narrative.ts';
import type {
  BelayerSignal,
  ClimberSignal,
  GameState,
  PublicDeclaration,
  Role,
  RouteDefinition,
  Submission,
  TeamworkPolicy,
} from '../../engine/types.ts';
import { ClimbingWall } from '../climbing/ClimbingWall.tsx';
import { IconChat, IconCheck, IconClock, IconLock } from '../ui/Icons.tsx';
import { Panel, Pill } from '../ui/Primitives.tsx';
import { ActionPanel } from './ActionPanel.tsx';
import { Hud } from './Hud.tsx';

export interface GameTableProps {
  route: RouteDefinition;
  state: GameState;
  role: Role;
  names: Record<Role, string>;
  myCommitted: boolean;
  partnerCommitted: boolean;
  partner: PublicDeclaration | null;
  mine: PublicDeclaration | null;
  busy?: boolean;
  onSubmit(sub: Submission): void;
  onDeclare?(signal: ClimberSignal | BelayerSignal | null, policy: TeamworkPolicy): void;
  /** Extra content under the waiting panel (leave game, notifications…). */
  waitingExtras?: ReactNode;
  banner?: ReactNode;
  header?: ReactNode;
  submitLabel?: string;
}

export const PHASE_TEXT: Record<TurnPhase, string> = {
  waiting_for_both: 'Waiting for both partners',
  waiting_for_climber: 'Waiting for climber',
  waiting_for_belayer: 'Waiting for belayer',
  ready_to_resolve: 'Ready to resolve',
  route_completed: 'Route completed',
  route_failed: 'Route failed',
};

export function signalText(role: Role, signal: string | null): string | null {
  if (!signal) return null;
  return role === 'climber' ? CLIMBER_SIGNAL_TEXT[signal as ClimberSignal] : BELAYER_SIGNAL_TEXT[signal as BelayerSignal];
}

export function PartnerSignal({ role, decl, name }: { role: Role; decl: PublicDeclaration | null; name: string }) {
  const text = signalText(role, decl?.signal ?? null);
  const shortName = name.replace(/ \(AI\)$/, '');
  return (
    <div className="paper max-w-full rounded-xl px-2 py-1 text-xs shadow-[var(--shadow-card)]" aria-live="polite" data-testid="partner-signal" title={`${name} · ${role}`}>
      <div className="flex min-w-0 items-center gap-1.5">
        <span className={`grid h-4 w-4 shrink-0 place-items-center rounded-full ${role === 'climber' ? 'bg-ember-deep' : 'bg-turquoise-deep'} text-cream`} aria-hidden>
          <IconChat size={9} />
        </span>
        <span className="truncate">
          <b>{shortName}:</b> {text ? `“${text}”` : decl?.committed ? 'no signal' : 'no signal yet'}
        </span>
        {decl?.committed && (
          <span className="flex shrink-0 items-center gap-0.5 text-[0.62rem] font-black text-success">
            <IconLock size={9} /> locked in
          </span>
        )}
      </div>
      {decl && decl.teamworkPolicy !== 'NEVER' && <div className="truncate pl-5 text-[0.62rem] text-ink-soft">Teamwork: {TEAMWORK_POLICY_TEXT[decl.teamworkPolicy].name}</div>}
    </div>
  );
}

export function TurnStatus({ phase }: { phase: TurnPhase }) {
  const tone =
    phase === 'route_completed'
      ? 'bg-success text-cream'
      : phase === 'route_failed'
        ? 'bg-danger text-cream'
        : phase === 'ready_to_resolve'
          ? 'bg-rope text-pine-950'
          : 'bg-white/15 text-cream';
  return (
    <Pill className={tone}>
      <span data-testid="turn-status">{PHASE_TEXT[phase]}</span>
    </Pill>
  );
}

export function GameTable(props: GameTableProps) {
  const { route, state, role, names, myCommitted, partnerCommitted, partner, mine } = props;
  const partnerRole: Role = role === 'climber' ? 'belayer' : 'climber';
  const phase = phaseOf(state.status, role === 'climber' ? myCommitted : partnerCommitted, role === 'belayer' ? myCommitted : partnerCommitted);
  const last = state.history[state.history.length - 1] ?? null;

  return (
    <div className="flex min-h-0 flex-1 flex-col gap-2 lg:flex-row lg:gap-4" data-testid="game-table" data-role={role} data-round={state.round}>
      {/* The wall takes whatever height is left, so the page never needs to scroll. */}
      <div className="relative min-h-[9rem] flex-1 overflow-hidden rounded-3xl border-[3px] border-cream/90 shadow-[var(--shadow-lift)] lg:min-h-0">
        <ClimbingWall
          className="absolute inset-0 block h-full w-full"
          fit="follow"
          route={route}
          position={state.position}
          clippedBolts={state.clippedBolts}
          rope={state.rope}
          showReach
          perspective={role}
        />
        <div className="absolute inset-x-2 top-2 flex flex-col items-start gap-1">
          <TurnStatus phase={phase} />
          <div className="max-w-[88%]">
            <PartnerSignal role={partnerRole} decl={partner} name={names[partnerRole]} />
          </div>
        </div>
        <div className="absolute right-2 top-2 rounded-full bg-pine-950/70 px-2 py-1 text-[0.62rem] font-black uppercase tracking-wider text-rope">
          You: {role}
        </div>
        {props.banner && <div className="absolute inset-x-2 bottom-2 flex flex-col gap-1.5">{props.banner}</div>}
      </div>

      <div className="flex shrink-0 flex-col gap-1.5 lg:w-[26rem] lg:justify-end">
        {props.header}
        <Hud state={state} route={route} emphasis={role} />
        {state.status !== 'in_progress' ? null : myCommitted ? (
          <WaitingPanel role={role} mine={mine} partnerName={names[partnerRole]} partnerCommitted={partnerCommitted} lastHeadline={last ? explainTurn(last).headline : null}>
            {props.waitingExtras}
          </WaitingPanel>
        ) : (
          <ActionPanel
            key={`${state.round}-${role}`}
            role={role}
            state={state}
            route={route}
            partner={partner}
            busy={props.busy ?? false}
            onSubmit={props.onSubmit}
            {...(props.onDeclare ? { onDeclare: props.onDeclare } : {})}
            initialDeclaration={mine}
            {...(props.submitLabel ? { submitLabel: props.submitLabel } : {})}
          />
        )}
      </div>
    </div>
  );
}

export function WaitingPanel({
  role,
  mine,
  partnerName,
  partnerCommitted,
  lastHeadline,
  children,
}: {
  role: Role;
  mine: PublicDeclaration | null;
  partnerName: string;
  partnerCommitted: boolean;
  lastHeadline: string | null;
  children?: ReactNode;
}) {
  const text = signalText(role, mine?.signal ?? null);
  return (
    <Panel className="flex flex-col gap-2 !p-3" as="div">
      <div className="flex items-center gap-3" data-testid="waiting-panel">
        <motion.div
          className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-turquoise-deep text-cream"
          animate={{ rotate: [0, 8, -8, 0] }}
          transition={{ repeat: Infinity, duration: 2.4 }}
        >
          <IconCheck size={20} />
        </motion.div>
        <div className="min-w-0">
          <div className="font-display text-lg font-bold leading-tight">Your move is locked in</div>
          <div className="text-xs text-ink-soft">
            Hidden until {partnerName} commits too.{text ? ` You signalled “${text}”.` : ''}
          </div>
        </div>
      </div>
      <div className="flex items-center gap-2 rounded-xl bg-sand/70 px-2.5 py-1.5 text-xs font-bold">
        <IconClock size={16} />
        {partnerCommitted ? 'Both cards are in. Resolving…' : `Waiting for ${partnerName}. You can leave and come back later.`}
      </div>
      {lastHeadline && <div className="text-xs text-ink-soft">Last round: {lastHeadline}</div>}
      {children}
    </Panel>
  );
}
