import { useCallback, useEffect, useRef, useState } from 'react';
import type { RealtimeChannel } from '@supabase/supabase-js';
import type { BelayerSignal, ClimberSignal, Submission, TeamworkPolicy } from '../engine/types.ts';
import { supabase } from './client.ts';
import { ActionError, declareOnline, heartbeat, loadGameView, submitTurn, type OnlineGameView } from './api.ts';

export type Connection = 'connecting' | 'live' | 'polling' | 'offline';

/** A card composed while offline. Kept visibly pending until the server accepts it. */
export interface PendingSubmission {
  gameId: string;
  round: number;
  stateVersion: number;
  submission: Submission;
  createdAt: number;
}

const pendingKey = (gameId: string) => `ob:pending:${gameId}`;
const seenKey = (gameId: string) => `ob:seen:${gameId}`;

function readPending(gameId: string): PendingSubmission | null {
  try {
    const raw = localStorage.getItem(pendingKey(gameId));
    return raw ? (JSON.parse(raw) as PendingSubmission) : null;
  } catch {
    return null;
  }
}
function writePending(gameId: string, p: PendingSubmission | null) {
  try {
    if (p) localStorage.setItem(pendingKey(gameId), JSON.stringify(p));
    else localStorage.removeItem(pendingKey(gameId));
  } catch {
    /* storage unavailable: the pending card lives in memory only */
  }
}

export function readSeenRounds(gameId: string): number {
  try {
    return Number(localStorage.getItem(seenKey(gameId)) ?? '0') || 0;
  } catch {
    return 0;
  }
}
export function writeSeenRounds(gameId: string, n: number) {
  try {
    localStorage.setItem(seenKey(gameId), String(n));
  } catch {
    /* ignore */
  }
}

const POLL_MS = 15_000;
const HEARTBEAT_MS = 60_000;

/**
 * Keeps an online game in sync. The server is the only source of truth: this hook never edits
 * game state locally. Updates arrive through Supabase Realtime, with polling and focus/online
 * refreshes as a fallback, so a closed tab, refresh or device switch always reloads the
 * authoritative state.
 */
export function useOnlineGame(gameId: string, opts: { onPartnerMove?: (v: OnlineGameView) => void } = {}) {
  const [view, setView] = useState<OnlineGameView | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [connection, setConnection] = useState<Connection>('connecting');
  const [busy, setBusy] = useState(false);
  const [pending, setPending] = useState<PendingSubmission | null>(() => readPending(gameId));
  const [notice, setNotice] = useState<string | null>(null);
  const loading = useRef(false);
  const again = useRef(false);
  const viewRef = useRef<OnlineGameView | null>(null);
  const onPartnerMove = useRef(opts.onPartnerMove);
  onPartnerMove.current = opts.onPartnerMove;

  const refresh = useCallback(async () => {
    if (loading.current) {
      again.current = true;
      return;
    }
    loading.current = true;
    try {
      do {
        again.current = false;
        const v = await loadGameView(gameId);
        const prev = viewRef.current;
        if (!prev || v.version !== prev.version || v.status !== prev.status || v.events.length !== prev.events.length) {
          viewRef.current = v;
          setView(v);
          if (prev && onPartnerMove.current) onPartnerMove.current(v);
        }
        setError(null);
      } while (again.current);
    } catch (e) {
      if (!navigator.onLine) setConnection('offline');
      else setError(e instanceof Error ? e.message : String(e));
    } finally {
      loading.current = false;
    }
  }, [gameId]);

  // Initial load, Realtime subscription, polling and lifecycle refreshes.
  useEffect(() => {
    let channel: RealtimeChannel | null = null;
    let debounce: ReturnType<typeof setTimeout> | undefined;
    const kick = () => {
      clearTimeout(debounce);
      debounce = setTimeout(() => void refresh(), 120);
    };
    void refresh();
    let disposed = false;
    void supabase().then((sb) => {
      if (disposed) return;
      channel = sb
        .channel(`game:${gameId}`)
        .on('postgres_changes', { event: '*', schema: 'public', table: 'game_public_state', filter: `game_id=eq.${gameId}` }, kick)
        .on('postgres_changes', { event: '*', schema: 'public', table: 'game_events', filter: `game_id=eq.${gameId}` }, kick)
        .on('postgres_changes', { event: '*', schema: 'public', table: 'game_participants', filter: `game_id=eq.${gameId}` }, kick)
        .on('postgres_changes', { event: '*', schema: 'public', table: 'games', filter: `id=eq.${gameId}` }, kick)
        .subscribe((status) => {
          if (status === 'SUBSCRIBED') {
            setConnection(navigator.onLine ? 'live' : 'offline');
            kick();
          } else if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT' || status === 'CLOSED') {
            setConnection(navigator.onLine ? 'polling' : 'offline');
          }
        });
    }, () => setConnection('polling'));
    const poll = setInterval(() => {
      if (document.visibilityState === 'visible') void refresh();
    }, POLL_MS);
    const beat = setInterval(() => {
      if (document.visibilityState === 'visible' && navigator.onLine) void heartbeat(gameId).catch(() => undefined);
    }, HEARTBEAT_MS);
    void heartbeat(gameId).catch(() => undefined);
    const onVisible = () => document.visibilityState === 'visible' && void refresh();
    const onOnline = () => {
      setConnection('polling');
      void refresh();
    };
    const onOffline = () => setConnection('offline');
    document.addEventListener('visibilitychange', onVisible);
    window.addEventListener('focus', onVisible);
    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);
    if (!navigator.onLine) setConnection('offline');
    return () => {
      clearTimeout(debounce);
      clearInterval(poll);
      clearInterval(beat);
      document.removeEventListener('visibilitychange', onVisible);
      window.removeEventListener('focus', onVisible);
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
      disposed = true;
      if (channel) {
        const ch = channel;
        void supabase().then((sb) => sb.removeChannel(ch));
      }
    };
  }, [gameId, refresh]);

  /** Send a pending card. Version-checked by the server; stale cards are discarded, never forced. */
  const flush = useCallback(
    async (p: PendingSubmission) => {
      setBusy(true);
      try {
        await submitTurn(p.gameId, p.round, p.stateVersion, p.submission);
        writePending(gameId, null);
        setPending(null);
        await refresh();
      } catch (e) {
        if (e instanceof ActionError && e.code === 'network') {
          setNotice('Not sent yet — your card will be sent when you reconnect.');
        } else {
          writePending(gameId, null);
          setPending(null);
          setNotice(
            e instanceof ActionError && (e.code === 'stale' || e.code === 'not_in_progress')
              ? 'The climb moved on while you were away, so your offline card was not played. Choose again.'
              : e instanceof Error
                ? e.message
                : String(e),
          );
          await refresh();
        }
      } finally {
        setBusy(false);
      }
    },
    [gameId, refresh],
  );

  // Retry a pending card when connectivity returns.
  useEffect(() => {
    if (!pending || connection === 'offline' || busy) return;
    void flush(pending);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [connection, pending?.createdAt]);

  const submit = useCallback(
    async (submission: Submission) => {
      const v = viewRef.current;
      if (!v?.state) return;
      const p: PendingSubmission = { gameId, round: v.state.round, stateVersion: v.stateVersion, submission, createdAt: Date.now() };
      setNotice(null);
      writePending(gameId, p);
      setPending(p);
      if (!navigator.onLine) {
        setConnection('offline');
        setNotice('You are offline. Your card is saved on this device and has NOT been sent yet.');
        return;
      }
      await flush(p);
    },
    [gameId, flush],
  );

  const declare = useCallback(
    (signal: ClimberSignal | BelayerSignal | null, policy: TeamworkPolicy) => {
      const v = viewRef.current;
      if (!v?.state || !navigator.onLine) return;
      void declareOnline(gameId, v.state.round, v.stateVersion, signal, policy).catch(() => undefined);
    },
    [gameId],
  );

  return { view, error, connection, busy, pending, notice, setNotice, refresh, submit, declare };
}
