import { useEffect, useState, type ReactNode } from 'react';
import { navigate } from '../app/router.tsx';
import { useSettings } from '../app/settings.tsx';
import { ClimbingWall } from '../components/climbing/ClimbingWall.tsx';
import { CarabinerRow } from '../components/ui/Carabiner.tsx';
import { Button, CompactHeader, GameScreen } from '../components/ui/Primitives.tsx';
import { ROUTES } from '../data/routes/index.ts';
import type { AiDifficulty } from '../engine/ai/agent.ts';
import type { Role } from '../engine/types.ts';
import { createLocalMatch } from '../offline/localGame.ts';
import { personalBests, saveMatch, type PersonalBest } from '../offline/repository.ts';
import { preloadAi } from '../offline/aiClient.ts';

const DIFFICULTIES: { id: AiDifficulty; name: string; detail: string }[] = [
  { id: 'beginner', name: 'Beginner', detail: 'Helpful and predictable. Follows your signals and forgives rope mistakes.' },
  { id: 'intermediate', name: 'Intermediate', detail: 'A realistic partner — usually right, sometimes not.' },
  { id: 'expert', name: 'Expert', detail: 'Plans every move. Reads your signals closely.' },
];

export function SetupScreen({ mode: initialMode }: { mode: 'solo' | 'pass_and_play' | 'online' }) {
  const { profile } = useSettings();
  const [mode, setMode] = useState<'solo' | 'pass_and_play'>(initialMode === 'pass_and_play' ? 'pass_and_play' : 'solo');
  const [routeId, setRouteId] = useState(ROUTES[0]!.id);
  const [role, setRole] = useState<Role>('climber');
  const [difficulty, setDifficulty] = useState<AiDifficulty>('beginner');
  const [names, setNames] = useState({ climber: '', belayer: '' });
  const [pbs, setPbs] = useState<Record<string, PersonalBest>>({});
  const [starting, setStarting] = useState(false);

  useEffect(() => {
    void personalBests().then(setPbs);
    preloadAi();
  }, []);

  const start = async () => {
    setStarting(true);
    const nick = profile.nickname || 'You';
    const record = createLocalMatch({
      mode,
      routeId,
      humanRole: role,
      difficulty,
      names: mode === 'solo' ? { [role]: nick } : { climber: names.climber || 'Climber', belayer: names.belayer || 'Belayer' },
    });
    await saveMatch(record);
    navigate({ name: 'local', id: record.id });
  };

  const selectedRoute = ROUTES.find((r) => r.id === routeId)!;
  const selectedAi = DIFFICULTIES.find((d) => d.id === difficulty)!;

  return (
    <GameScreen>
      <CompactHeader title="Play Offline" subtitle="No connection needed" onBack={() => navigate({ name: 'home' })} />
      <div className="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto pt-1 tiny:gap-2 lg:mx-auto lg:w-full lg:max-w-2xl lg:justify-center">
        <Section label="Mode">
          <Segmented
            options={[
              { id: 'solo', label: 'Solo with AI', testId: 'mode-solo' },
              { id: 'pass_and_play', label: 'Pass & Play', testId: 'mode-pass' },
            ]}
            value={mode}
            onChange={(v) => setMode(v as 'solo' | 'pass_and_play')}
            ariaLabel="Mode"
          />
        </Section>

        {mode === 'solo' ? (
          <>
            <Section label="You play">
              <Segmented
                options={[
                  { id: 'climber', label: 'Climber', testId: 'role-climber' },
                  { id: 'belayer', label: 'Belayer', testId: 'role-belayer' },
                ]}
                value={role}
                onChange={(v) => setRole(v as Role)}
                ariaLabel="Your role"
              />
              <p className="mt-1 text-xs text-sand/80 tiny:hidden">{role === 'climber' ? 'Choose the moves and manage stamina.' : 'Manage the rope and keep your climber safe.'}</p>
            </Section>
            <Section label="AI partner">
              <Segmented options={DIFFICULTIES.map((d) => ({ id: d.id, label: d.name, testId: `ai-${d.id}` }))} value={difficulty} onChange={(v) => setDifficulty(v as AiDifficulty)} ariaLabel="AI difficulty" />
              <p className="mt-1 text-xs text-sand/80 tiny:line-clamp-1">{selectedAi.detail}</p>
            </Section>
          </>
        ) : (
          <Section label="Players">
            <div className="grid grid-cols-2 gap-2">
              {(['climber', 'belayer'] as const).map((r) => (
                <label key={r} className="block">
                  <span className="sr-only">{r} name</span>
                  <input
                    className="focus-ring block min-h-11 w-full rounded-xl border border-black/15 bg-cream px-3 text-base text-ink"
                    maxLength={20}
                    placeholder={r === 'climber' ? 'Climber' : 'Belayer'}
                    value={names[r]}
                    onChange={(e) => setNames({ ...names, [r]: e.target.value })}
                  />
                </label>
              ))}
            </div>
            <p className="mt-1 text-xs text-sand/80">Pass the device between turns. Each card stays hidden until the reveal.</p>
          </Section>
        )}

        <Section label="Route">
          <div className="grid grid-cols-3 gap-2" role="radiogroup" aria-label="Route">
            {ROUTES.map((r) => (
              <button
                key={r.id}
                type="button"
                role="radio"
                aria-checked={routeId === r.id}
                onClick={() => setRouteId(r.id)}
                data-testid={`route-${r.id}`}
                className={`focus-ring paper flex min-w-0 flex-col overflow-hidden rounded-xl text-left text-ink ${routeId === r.id ? 'ring-[3px] ring-rope' : 'ring-1 ring-black/10'}`}
              >
                <div className="relative h-20 overflow-hidden short:h-14 tiny:h-10">
                  <ClimbingWall className="absolute inset-0 h-full w-full" fit="follow" route={r} position={4} clippedBolts={[]} rope={1} />
                </div>
                <div className="px-1.5 py-1">
                  <div className="font-display truncate text-sm font-bold leading-tight">{r.name}</div>
                  <div className="flex items-center justify-between gap-1 text-[0.66rem] font-bold text-ink-soft">
                    <span>{r.grade}</span>
                    <CarabinerRow count={pbs[r.id]?.bestCarabiners ?? 0} size={8} />
                  </div>
                </div>
              </button>
            ))}
          </div>
          <p className="mt-1 line-clamp-2 text-xs text-sand/80 tiny:line-clamp-1">
            <b className="text-cream">{selectedRoute.terrain}.</b> {selectedRoute.description}
          </p>
        </Section>
      </div>
      <Button size="lg" className="w-full shrink-0 lg:mx-auto lg:max-w-2xl" onClick={start} disabled={starting} data-testid="start-game">
        Start climbing
      </Button>
    </GameScreen>
  );
}

function Section({ label, children }: { label: string; children: ReactNode }) {
  return (
    <section>
      <h2 className="mb-1 text-[0.66rem] font-black uppercase tracking-[0.18em] text-sand/75">{label}</h2>
      {children}
    </section>
  );
}

function Segmented({ options, value, onChange, ariaLabel }: { options: { id: string; label: string; testId: string }[]; value: string; onChange: (v: string) => void; ariaLabel: string }) {
  return (
    <div className="grid gap-1 rounded-2xl bg-pine-950/50 p-1" style={{ gridTemplateColumns: `repeat(${options.length}, minmax(0, 1fr))` }} role="radiogroup" aria-label={ariaLabel}>
      {options.map((o) => (
        <button
          key={o.id}
          type="button"
          role="radio"
          aria-checked={value === o.id}
          onClick={() => onChange(o.id)}
          data-testid={o.testId}
          className={`focus-ring min-h-11 truncate rounded-xl px-2 text-sm font-extrabold transition ${value === o.id ? 'bg-cream text-pine-900 shadow' : 'text-cream/85'}`}
        >
          {o.label}
        </button>
      ))}
    </div>
  );
}

export function Choice({ selected, onClick, title, detail, testId }: { selected: boolean; onClick: () => void; title: string; detail: string; testId?: string }) {
  return (
    <button
      type="button"
      role="radio"
      aria-checked={selected}
      onClick={onClick}
      data-testid={testId}
      className={`focus-ring min-h-14 rounded-2xl border-2 px-3 py-2 text-left transition ${selected ? 'border-ember bg-ember/10' : 'border-transparent bg-sand/60 hover:bg-sand'}`}
    >
      <span className="block font-extrabold">{title}</span>
      <span className="block text-sm text-ink-soft">{detail}</span>
    </button>
  );
}
