/**
 * Procedural audio. Every effect and the ambient bed are synthesised with the Web Audio API, so
 * the game ships no audio files and can never be blocked by a missing asset. If audio is
 * unavailable or not yet unlocked by a user gesture, every call is a silent no-op.
 */

export type Sfx = 'tap' | 'card' | 'commit' | 'dice' | 'success' | 'fall' | 'clip' | 'rest' | 'rope' | 'summit' | 'reveal' | 'blocked';

interface AudioPrefs {
  sound: boolean;
  music: boolean;
  volume: number;
}

let ctx: AudioContext | null = null;
let master: GainNode | null = null;
let prefs: AudioPrefs = { sound: true, music: false, volume: 0.7 };
let ambience: { stop(): void } | null = null;

function context(): AudioContext | null {
  if (typeof window === 'undefined') return null;
  if (!ctx) {
    const AC = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!AC) return null;
    try {
      ctx = new AC();
      master = ctx.createGain();
      master.gain.value = prefs.volume;
      master.connect(ctx.destination);
    } catch {
      ctx = null;
      return null;
    }
  }
  if (ctx.state === 'suspended') void ctx.resume().catch(() => undefined);
  return ctx;
}

export function configureAudio(next: AudioPrefs) {
  prefs = next;
  if (master) master.gain.value = next.volume;
  if (next.music && next.sound) startAmbience();
  else stopAmbience();
}

/** Call from a user gesture to unlock audio on iOS/Safari. */
export function unlockAudio() {
  if (prefs.sound) context();
  if (prefs.music && prefs.sound) startAmbience();
}

function tone(freq: number, dur: number, opts: { type?: OscillatorType; gain?: number; delay?: number; slideTo?: number } = {}) {
  const c = context();
  if (!c || !master) return;
  const t = c.currentTime + (opts.delay ?? 0);
  const osc = c.createOscillator();
  const g = c.createGain();
  osc.type = opts.type ?? 'sine';
  osc.frequency.setValueAtTime(freq, t);
  if (opts.slideTo) osc.frequency.exponentialRampToValueAtTime(opts.slideTo, t + dur);
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(opts.gain ?? 0.2, t + 0.01);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  osc.connect(g).connect(master);
  osc.start(t);
  osc.stop(t + dur + 0.05);
}

function noise(dur: number, opts: { gain?: number; delay?: number; filter?: number; q?: number; type?: BiquadFilterType } = {}) {
  const c = context();
  if (!c || !master) return;
  const t = c.currentTime + (opts.delay ?? 0);
  const buffer = c.createBuffer(1, Math.max(1, Math.floor(c.sampleRate * dur)), c.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  const src = c.createBufferSource();
  src.buffer = buffer;
  const f = c.createBiquadFilter();
  f.type = opts.type ?? 'bandpass';
  f.frequency.value = opts.filter ?? 1200;
  f.Q.value = opts.q ?? 1;
  const g = c.createGain();
  g.gain.setValueAtTime(opts.gain ?? 0.2, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  src.connect(f).connect(g).connect(master);
  src.start(t);
}

export function sfx(name: Sfx) {
  if (!prefs.sound) return;
  try {
    switch (name) {
      case 'tap':
        tone(660, 0.05, { type: 'triangle', gain: 0.06 });
        break;
      case 'card':
        noise(0.08, { filter: 2400, gain: 0.12, q: 0.8 });
        break;
      case 'commit':
        tone(392, 0.12, { type: 'triangle', gain: 0.12 });
        tone(587, 0.16, { type: 'triangle', gain: 0.12, delay: 0.08 });
        break;
      case 'reveal':
        noise(0.18, { filter: 1800, gain: 0.1, type: 'highpass' });
        break;
      case 'dice':
        for (let i = 0; i < 6; i++) noise(0.04, { filter: 3000 + i * 300, gain: 0.16, delay: i * 0.07, q: 4 });
        break;
      case 'success':
        tone(523, 0.14, { type: 'triangle', gain: 0.14 });
        tone(659, 0.14, { type: 'triangle', gain: 0.14, delay: 0.1 });
        tone(784, 0.24, { type: 'triangle', gain: 0.14, delay: 0.2 });
        break;
      case 'fall':
        tone(300, 0.35, { type: 'sawtooth', gain: 0.06, slideTo: 80 });
        noise(0.25, { filter: 140, gain: 0.5, delay: 0.32, type: 'lowpass' });
        break;
      case 'clip':
        tone(2400, 0.06, { type: 'square', gain: 0.05 });
        tone(3100, 0.09, { type: 'triangle', gain: 0.07, delay: 0.05 });
        break;
      case 'rest':
        tone(440, 0.4, { gain: 0.06, slideTo: 330 });
        break;
      case 'rope':
        noise(0.22, { filter: 700, gain: 0.12, q: 0.6 });
        break;
      case 'blocked':
        tone(220, 0.2, { type: 'square', gain: 0.05 });
        break;
      case 'summit':
        [523, 659, 784, 1047].forEach((f, i) => tone(f, 0.35, { type: 'triangle', gain: 0.14, delay: i * 0.12 }));
        tone(1319, 0.8, { type: 'sine', gain: 0.1, delay: 0.5 });
        break;
    }
  } catch {
    // Audio is decorative; ignore failures.
  }
}

/** Mountain wind and a slow pentatonic pad. */
function startAmbience() {
  const c = context();
  if (!c || !master || ambience) return;
  const out = c.createGain();
  out.gain.value = 0.0001;
  out.gain.exponentialRampToValueAtTime(0.5, c.currentTime + 2);
  out.connect(master);

  const buffer = c.createBuffer(1, c.sampleRate * 4, c.sampleRate);
  const data = buffer.getChannelData(0);
  let last = 0;
  for (let i = 0; i < data.length; i++) {
    last = last * 0.985 + (Math.random() * 2 - 1) * 0.015;
    data[i] = last * 6;
  }
  const wind = c.createBufferSource();
  wind.buffer = buffer;
  wind.loop = true;
  const wf = c.createBiquadFilter();
  wf.type = 'lowpass';
  wf.frequency.value = 500;
  const wg = c.createGain();
  wg.gain.value = 0.12;
  wind.connect(wf).connect(wg).connect(out);
  wind.start();

  const notes = [196, 220, 262, 294, 330, 392];
  let stopped = false;
  const timer = window.setInterval(() => {
    if (stopped || !ctx) return;
    const f = notes[Math.floor(Math.random() * notes.length)]!;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = f;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.035, t + 1.5);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 5);
    osc.connect(g).connect(out);
    osc.start(t);
    osc.stop(t + 5.2);
  }, 2600);

  ambience = {
    stop() {
      stopped = true;
      window.clearInterval(timer);
      try {
        out.gain.exponentialRampToValueAtTime(0.0001, c.currentTime + 0.8);
        wind.stop(c.currentTime + 0.9);
      } catch {
        /* already stopped */
      }
    },
  };
}

function stopAmbience() {
  ambience?.stop();
  ambience = null;
}
