import { motion, useReducedMotion } from 'motion/react';
import { useEffect, useState } from 'react';

const PIPS: Record<number, [number, number][]> = {
  1: [[50, 50]],
  2: [[28, 28], [72, 72]],
  3: [[28, 28], [50, 50], [72, 72]],
  4: [[28, 28], [72, 28], [28, 72], [72, 72]],
  5: [[28, 28], [72, 28], [50, 50], [28, 72], [72, 72]],
  6: [[28, 26], [72, 26], [28, 50], [72, 50], [28, 74], [72, 74]],
};

export function DieFace({ value, size = 72 }: { value: number; size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" role="img" aria-label={`Die showing ${value}`}>
      <rect x="4" y="4" width="92" height="92" rx="20" fill="#fbf5ea" stroke="#1d2422" strokeWidth="5" />
      {PIPS[value]?.map(([x, y], i) => <circle key={i} cx={x} cy={y} r="8.5" fill="#1d2422" />)}
    </svg>
  );
}

/** Tumbling die that settles on `value`. Rolls are decided by the engine, never by this view. */
export function RollingDie({ value, onSettled }: { value: number; onSettled?: () => void }) {
  const reduced = useReducedMotion();
  const [shown, setShown] = useState(reduced ? value : 1);
  const [settled, setSettled] = useState(!!reduced);

  useEffect(() => {
    if (reduced) {
      onSettled?.();
      return;
    }
    let i = 0;
    const id = window.setInterval(() => {
      i++;
      setShown(1 + ((value + i * 5) % 6));
      if (i >= 9) {
        window.clearInterval(id);
        setShown(value);
        setSettled(true);
        onSettled?.();
      }
    }, 85);
    return () => window.clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value, reduced]);

  return (
    <motion.div
      animate={settled ? { rotate: 0, y: 0, scale: [1.15, 1] } : { rotate: [0, 90, 180, 270, 360], y: [0, -18, 0, -10, 0] }}
      transition={settled ? { duration: 0.25 } : { duration: 0.8, ease: 'easeOut' }}
      data-testid="die"
      data-value={settled ? value : undefined}
    >
      <DieFace value={shown} />
    </motion.div>
  );
}
