import { motion } from 'motion/react';
import type { BelayerAction, ClimberAction } from '../../engine/types.ts';
import { CardArt } from './CardArt.tsx';

export interface ActionCardProps {
  action: ClimberAction | BelayerAction;
  name: string;
  short: string;
  rules: string;
  costs?: { stamina?: number; rope?: number };
  selected?: boolean;
  disabledReason?: string | null;
  warning?: string | null;
  onSelect?: () => void;
  size?: 'hand' | 'reveal';
  faceDown?: boolean;
  role: 'climber' | 'belayer';
}

/** A premium tabletop-style action card. Selected cards lift; unavailable cards explain why. */
export function ActionCard({
  action,
  name,
  short,
  rules,
  costs,
  selected = false,
  disabledReason = null,
  warning = null,
  onSelect,
  size = 'hand',
  faceDown = false,
  role,
}: ActionCardProps) {
  const disabled = !!disabledReason;
  const band = role === 'climber' ? 'bg-ember-deep' : 'bg-turquoise-deep';
  const reveal = size === 'reveal';

  if (faceDown) {
    return (
      <div
        className={`relative grid place-items-center overflow-hidden rounded-2xl border-4 border-cream bg-pine-700 shadow-[var(--shadow-card)] ${reveal ? 'h-52 w-36' : 'h-40 w-28'}`}
        aria-label="Hidden card"
      >
        <svg viewBox="0 0 60 80" className="h-3/4 w-3/4 opacity-80" aria-hidden>
          <path d="M8 70 L26 30 L34 44 L42 26 L54 70 Z" fill="#36685a" />
          <path d="M6 74 C20 64 30 76 40 68 S52 62 56 70" stroke="#e9b44c" strokeWidth="3" fill="none" />
          <circle cx="30" cy="18" r="8" fill="#f6b76b" />
        </svg>
      </div>
    );
  }

  if (!onSelect) {
    return (
      <div
        className={`paper relative flex flex-col overflow-hidden rounded-2xl text-left shadow-[var(--shadow-card)] ring-1 ring-black/10 ${reveal ? 'h-52 w-36 shrink-0' : 'min-h-[10.5rem] w-full'}`}
        data-revealed-action={action}
        role="img"
        aria-label={`${name}: ${rules}`}
      >
        <div className={`${band} px-2.5 py-1.5`}>
          <span className="font-display text-[1.05rem] font-bold leading-none text-cream">{name}</span>
        </div>
        <div className="mx-2 mt-1.5 h-14 rounded-lg bg-sand/70 p-1">
          <CardArt action={action} />
        </div>
        <div className="px-2.5 pt-1 text-[0.8rem] font-black uppercase tracking-wide text-ink">{short}</div>
        <p className="line-clamp-3 px-2.5 text-[0.72rem] leading-snug text-ink-soft">{rules}</p>
      </div>
    );
  }

  return (
    <motion.button
      type="button"
      layout
      onClick={disabled ? undefined : onSelect}
      aria-pressed={selected}
      aria-disabled={disabled}
      aria-label={`${name}: ${rules}${disabledReason ? ` Unavailable: ${disabledReason}` : ''}${warning ? ` Warning: ${warning}` : ''}`}
      animate={{ y: selected ? -14 : 0, rotate: selected ? -1.5 : 0, scale: selected ? 1.03 : 1 }}
      whileTap={disabled ? {} : { scale: 0.97 }}
      transition={{ type: 'spring', stiffness: 380, damping: 24 }}
      className={`focus-ring paper relative flex flex-col overflow-hidden rounded-2xl text-left shadow-[var(--shadow-card)] ${
        reveal ? 'h-52 w-36 shrink-0' : 'min-h-[10.5rem] w-full'
      } ${selected ? 'ring-4 ring-rope' : 'ring-1 ring-black/10'} ${disabled ? 'opacity-60 grayscale-[0.6]' : ''}`}
      data-action={action}
      data-selected={selected}
    >
      <div className={`${band} flex items-center justify-between px-2.5 py-1.5`}>
        <span className="font-display text-[1.05rem] font-bold leading-none text-cream">{name}</span>
        {selected && (
          <span className="rounded-full bg-cream px-1.5 text-[10px] font-black text-ink" aria-hidden>
            ✓
          </span>
        )}
      </div>
      <div className="mx-2 mt-1.5 h-12 rounded-lg bg-sand/70 p-1 sm:h-14">
        <CardArt action={action} />
      </div>
      <div className="px-2.5 pt-1 text-[0.8rem] font-black uppercase tracking-wide text-ink">{short}</div>
      <p className={`px-2.5 text-[0.72rem] leading-snug text-ink-soft ${reveal ? 'line-clamp-3' : 'line-clamp-2'}`}>{rules}</p>
      {costs && (costs.stamina || costs.rope) ? (
        <div className="mt-auto flex gap-1 px-2 pb-1.5 pt-1">
          {!!costs.stamina && (
            <span className="rounded-md bg-ember/15 px-1.5 py-0.5 text-[0.65rem] font-black text-terracotta">⚡{costs.stamina}</span>
          )}
          {!!costs.rope && <span className="rounded-md bg-rope/25 px-1.5 py-0.5 text-[0.65rem] font-black text-rope-dark">rope {costs.rope}</span>}
        </div>
      ) : (
        <div className="mt-auto pb-1.5" />
      )}
      {disabled && <div className="mx-1 mb-1 rounded-lg bg-ink/85 px-2 py-1 text-[0.68rem] font-bold leading-tight text-cream">{disabledReason}</div>}
      {!disabled && warning && <div className="mx-1 mb-1 rounded-lg bg-[var(--warn)] px-2 py-1 text-[0.68rem] font-black leading-tight text-ink">⚠ {warning}</div>}
    </motion.button>
  );
}

export interface HandCardProps {
  action: ClimberAction | BelayerAction;
  role: 'climber' | 'belayer';
  name: string;
  short: string;
  costs?: { stamina?: number; rope?: number } | undefined;
  selected: boolean;
  unavailable: boolean;
  warned: boolean;
  onPress: () => void;
  label: string;
}

/**
 * Compact card for the in-game hand: four fit in one row on a phone. Rules text and warnings are
 * shown in the line under the hand for whichever card was tapped.
 */
export function HandCard({ action, role, name, short, costs, selected, unavailable, warned, onPress, label }: HandCardProps) {
  const band = role === 'climber' ? 'bg-ember-deep' : 'bg-turquoise-deep';
  return (
    <motion.button
      type="button"
      onClick={onPress}
      aria-pressed={selected}
      aria-disabled={unavailable}
      aria-label={label}
      animate={{ y: selected ? -6 : 0, scale: selected ? 1.03 : 1 }}
      whileTap={{ scale: 0.96 }}
      transition={{ type: 'spring', stiffness: 420, damping: 26 }}
      className={`focus-ring paper relative flex h-[7.4rem] min-w-0 flex-col overflow-hidden rounded-xl text-left shadow-[var(--shadow-card)] short:h-[6.6rem] ${
        selected ? 'ring-[3px] ring-rope' : 'ring-1 ring-black/10'
      } ${unavailable ? 'opacity-50 grayscale' : ''}`}
      data-action={action}
      data-selected={selected}
    >
      <div className={`${band} flex items-center justify-between px-1.5 py-1`}>
        <span className="font-display truncate text-[clamp(0.74rem,3.3vw,0.92rem)] font-bold leading-none text-cream">{name}</span>
        {warned && !unavailable && (
          <span className="grid h-4 w-4 shrink-0 place-items-center rounded-full bg-[var(--warn)] text-[0.65rem] font-black text-ink" aria-hidden>
            !
          </span>
        )}
      </div>
      <div className="mx-1 mt-1 h-11 overflow-hidden rounded-md bg-sand/70 short:h-9">
        <CardArt action={action} />
      </div>
      <div className="px-1.5 pt-1 text-[0.66rem] font-black uppercase leading-tight text-ink">{short}</div>
      {costs && (costs.stamina || costs.rope) ? (
        <div className="mt-auto flex gap-0.5 px-1 pb-1">
          {!!costs.stamina && <span className="rounded bg-ember/15 px-1 text-[0.6rem] font-black text-terracotta">⚡{costs.stamina}</span>}
          {!!costs.rope && <span className="rounded bg-rope/25 px-1 text-[0.6rem] font-black text-rope-dark">rope {costs.rope}</span>}
        </div>
      ) : null}
    </motion.button>
  );
}
