import Dexie, { type Table } from 'dexie';
import type { AiDifficulty } from '../engine/ai/agent.ts';
import type { MatchCore } from '../engine/match.ts';
import type { Role, TurnResult } from '../engine/types.ts';

export type LocalMode = 'solo' | 'pass_and_play';

export interface LocalPlayer {
  kind: 'human' | 'ai';
  name: string;
  difficulty?: AiDifficulty;
}

export interface LocalMatchRecord {
  id: string;
  mode: LocalMode;
  routeId: string;
  createdAt: number;
  updatedAt: number;
  players: Record<Role, LocalPlayer>;
  core: MatchCore;
  /** Most recent resolution, kept until both players have seen the reveal. */
  lastResult: TurnResult | null;
  revealSeen: boolean;
  /** Pass-and-play: whose private turn is next on this device, or null between rounds. */
  activeRole: Role | null;
  /** Pass-and-play: true while the "pass the device" screen covers everything. */
  handoff: boolean;
  /** Personal-best bookkeeping is applied once per finished game. */
  recorded: boolean;
}

export interface RouteResultRecord {
  id?: number;
  routeId: string;
  mode: string;
  won: boolean;
  carabiners: number;
  rounds: number;
  falls: number;
  recoveryRemaining: number;
  finishedAt: number;
}

export interface KeyValue {
  key: string;
  value: unknown;
}

export class OnBelayDB extends Dexie {
  matches!: Table<LocalMatchRecord, string>;
  results!: Table<RouteResultRecord, number>;
  kv!: Table<KeyValue, string>;

  constructor(name = 'on-belay') {
    super(name);
    this.version(1).stores({
      matches: 'id, updatedAt, mode',
      results: '++id, routeId, finishedAt',
      kv: 'key',
    });
  }
}

export const db = new OnBelayDB();

export async function kvGet<T>(key: string, fallback: T): Promise<T> {
  try {
    const row = await db.kv.get(key);
    return row ? (row.value as T) : fallback;
  } catch {
    return fallback;
  }
}

export async function kvSet(key: string, value: unknown): Promise<void> {
  try {
    await db.kv.put({ key, value });
  } catch {
    // Storage unavailable: settings last for this session only.
  }
}
