import type { SupabaseClient } from '@supabase/supabase-js';

/**
 * Supabase client. Only the public anon key is ever shipped to the browser; all state-changing
 * game actions go through the `game-action` Edge Function, which holds the database credentials.
 * supabase-js is loaded on demand so offline-only players never download it.
 */
const url = import.meta.env.VITE_SUPABASE_URL as string | undefined;
const anonKey = import.meta.env.VITE_SUPABASE_ANON_KEY as string | undefined;

export const onlineConfigured = !!(url && anonKey);

let client: Promise<SupabaseClient> | null = null;

export function supabase(): Promise<SupabaseClient> {
  if (!onlineConfigured) return Promise.reject(new Error('Online play is not configured (VITE_SUPABASE_URL / VITE_SUPABASE_ANON_KEY).'));
  client ??= import('@supabase/supabase-js').then(({ createClient }) =>
    createClient(url!, anonKey!, {
      auth: { persistSession: true, autoRefreshToken: true, storageKey: 'on-belay-auth' },
      realtime: { params: { eventsPerSecond: 5 } },
    }),
  );
  return client;
}

export const functionsUrl = () => `${url}/functions/v1`;
export const anonApiKey = () => anonKey ?? '';

// Public connection info (the anon key is public by design). Exposed for diagnostics and the
// end-to-end tests that verify Row Level Security from inside a real browser.
if (onlineConfigured && typeof window !== 'undefined') {
  (window as unknown as { __OB_ENV__?: { url: string; key: string } }).__OB_ENV__ = { url: url!, key: anonKey! };
}
