import { stepCore } from './core.ts';
import { computeCarabiners } from './scoring.ts';
import { cloneState } from './state.ts';
import {
  BELAYER_ACTIONS,
  BELAYER_SIGNALS,
  CLIMBER_ACTIONS,
  CLIMBER_SIGNALS,
  TEAMWORK_POLICIES,
  type DiceSource,
  type GameState,
  type RoundInput,
  type RouteDefinition,
  type TeamworkPolicy,
  type TurnResult,
} from './types.ts';

export class RulesError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'RulesError';
  }
}

/** Validate the shape of a round's input. Throws RulesError on anything malformed. */
export function validateRoundInput(input: RoundInput): void {
  const climber = input?.climber;
  const belayer = input?.belayer;
  if (climber?.role !== 'climber') throw new RulesError('climber submission missing or has the wrong role');
  if (belayer?.role !== 'belayer') throw new RulesError('belayer submission missing or has the wrong role');
  if (!CLIMBER_ACTIONS.includes(climber.action)) throw new RulesError(`unknown climber action ${String(climber.action)}`);
  if (!BELAYER_ACTIONS.includes(belayer.action)) throw new RulesError(`unknown belayer action ${String(belayer.action)}`);
  if (climber.signal !== null && !CLIMBER_SIGNALS.includes(climber.signal)) throw new RulesError('unknown climber signal');
  if (belayer.signal !== null && !BELAYER_SIGNALS.includes(belayer.signal)) throw new RulesError('unknown belayer signal');
  if (!TEAMWORK_POLICIES.includes(climber.teamworkPolicy)) throw new RulesError('unknown climber teamwork policy');
  if (!TEAMWORK_POLICIES.includes(belayer.teamworkPolicy)) throw new RulesError('unknown belayer teamwork policy');
}

/**
 * Teamwork is spent automatically when a triggered condition is authorised by at least one
 * partner's policy. Rescue is checked before the roll and Convert after it, so the documented
 * priority (rescue first, then convert, else preserve) falls out of the resolution order and
 * the token can never be spent twice.
 */
export function teamworkPermissions(climber: TeamworkPolicy, belayer: TeamworkPolicy) {
  return {
    rescue: climber === 'RESCUE_BLOCKED_MOVE' || belayer === 'RESCUE_BLOCKED_MOVE',
    convert: climber === 'CONVERT_FAILED_ROLL_IF_POSSIBLE' || belayer === 'CONVERT_FAILED_ROLL_IF_POSSIBLE',
  };
}

/**
 * Resolve one round. Pure: returns a new state and a full record of what happened; the input
 * state is not modified. Randomness comes only from `dice`, called at most once per round.
 */
export function resolveRound(
  state: GameState,
  route: RouteDefinition,
  input: RoundInput,
  dice: DiceSource,
): { state: GameState; result: TurnResult } {
  if (state.status !== 'in_progress') throw new RulesError('cannot resolve a round of a finished game');
  if (state.routeId !== route.id) throw new RulesError('route does not match game state');
  validateRoundInput(input);

  const { climber, belayer } = input;
  const { next: core, detail } = stepCore(
    state,
    route,
    state.config,
    climber.action,
    belayer.action,
    teamworkPermissions(climber.teamworkPolicy, belayer.teamworkPolicy),
    () => dice.rollD6(),
  );

  const next = cloneState(state);
  next.position = core.position;
  next.stamina = core.stamina;
  next.rope = core.rope;
  next.lastClippedPosition = core.lastClippedPosition;
  next.clippedBolts = [...core.clippedBolts];
  next.recoveryTokens = core.recoveryTokens;
  next.teamworkAvailable = core.teamworkAvailable;
  next.round = core.round;
  next.status = core.status;

  const st = next.stats;
  st.climberActionCounts[climber.action]++;
  st.belayerActionCounts[belayer.action]++;
  if (detail.outcome === 'blocked') st.blockedActions++;
  if (detail.outcome === 'rested') st.rests++;
  if (detail.outcome === 'clipped') st.clips++;
  if (detail.fall) {
    st.falls++;
    st.tokensLost += state.recoveryTokens - core.recoveryTokens;
  }
  if (detail.teamwork) {
    st.teamworkUse = detail.teamwork;
    st.teamworkUsedRound = state.round;
  }

  if (detail.endReason) {
    const won = detail.endReason === 'summit';
    next.result = { outcome: won ? 'won' : 'lost', reason: detail.endReason, roundsUsed: state.round, carabiners: 0 };
    if (won) next.result.carabiners = computeCarabiners(next);
  }

  const result: TurnResult = {
    round: state.round,
    climber: { ...climber },
    belayer: { ...belayer },
    ropeBefore: state.rope,
    ropeAfterBelay: detail.ropeAfterBelay,
    ropeAfter: core.rope,
    staminaBefore: state.stamina,
    staminaAfter: core.stamina,
    positionBefore: state.position,
    positionAfter: core.position,
    recoveryBefore: state.recoveryTokens,
    recoveryAfter: core.recoveryTokens,
    legal: detail.legal,
    blockedReason: detail.blockedReason,
    teamwork: detail.teamwork,
    roll: detail.roll,
    fall: detail.fall,
    clipped: detail.clipped,
    restedOnRestHold: detail.restedOnRestHold,
    outcome: detail.outcome,
    statusAfter: core.status,
  };
  next.history = [...next.history, result];
  return { state: next, result };
}

/** End a game early because a player forfeited. */
export function forfeit(state: GameState): GameState {
  if (state.status !== 'in_progress') return state;
  const next = cloneState(state);
  next.status = 'lost';
  next.result = { outcome: 'lost', reason: 'forfeit', roundsUsed: Math.max(0, state.round - 1), carabiners: 0 };
  return next;
}
