import { useEffect, useState } from 'react';
import { navigate } from '../app/router.tsx';
import { Button, Panel, Screen, ScreenHeader } from '../components/ui/Primitives.tsx';
import { getRoute } from '../data/routes/index.ts';
import type { LocalMatchRecord } from '../offline/db.ts';
import { deleteMatch, listMatches } from '../offline/repository.ts';
import { onlineConfigured } from '../multiplayer/client.ts';
import { listMyOnlineGames, type OnlineGameSummary } from '../multiplayer/api.ts';

export function ContinueScreen() {
  const [local, setLocal] = useState<LocalMatchRecord[] | null>(null);
  const [online, setOnline] = useState<OnlineGameSummary[] | null>(null);
  const [onlineError, setOnlineError] = useState<string | null>(null);

  const refresh = () => void listMatches().then(setLocal);
  useEffect(() => {
    refresh();
    if (onlineConfigured) {
      listMyOnlineGames()
        .then(setOnline)
        .catch((e: unknown) => setOnlineError(e instanceof Error ? e.message : String(e)));
    }
  }, []);

  const active = (local ?? []).filter((r) => r.core.state.status === 'in_progress');
  const finished = (local ?? []).filter((r) => r.core.state.status !== 'in_progress').slice(0, 10);

  return (
    <Screen>
      <ScreenHeader title="Continue" subtitle="Your climbs in progress" onBack={() => navigate({ name: 'home' })} />
      <div className="grid gap-4 lg:grid-cols-2">
        <section className="flex flex-col gap-2">
          <h2 className="font-display text-xl font-bold text-cream">Online games</h2>
          {!onlineConfigured && <Panel className="text-sm">Online play is not configured in this build.</Panel>}
          {onlineError && <Panel className="text-sm">Couldn't load online games: {onlineError}</Panel>}
          {online?.length === 0 && <Panel className="text-sm">No online games yet.</Panel>}
          {online?.map((g) => (
            <Panel key={g.id} className="flex items-center justify-between gap-3" as="article">
              <div className="min-w-0">
                <div className="font-display truncate text-lg font-bold">{getRoute(g.routeId).name}</div>
                <div className="text-sm text-ink-soft">
                  Room {g.roomCode} · {g.role ?? 'spectator'} · {g.statusText}
                </div>
              </div>
              <Button size="sm" onClick={() => navigate(g.status === 'lobby' ? { name: 'lobby', gameId: g.id } : { name: 'onlineGame', gameId: g.id })}>
                {g.yourTurn ? 'Your turn' : 'Open'}
              </Button>
            </Panel>
          ))}
        </section>
        <section className="flex flex-col gap-2">
          <h2 className="font-display text-xl font-bold text-cream">On this device</h2>
          {local && active.length === 0 && <Panel className="text-sm">No offline climbs in progress.</Panel>}
          {active.map((r) => (
            <Panel key={r.id} className="flex items-center justify-between gap-3" as="article">
              <div className="min-w-0">
                <div className="font-display truncate text-lg font-bold">{getRoute(r.routeId).name}</div>
                <div className="text-sm text-ink-soft">
                  {r.mode === 'solo' ? 'Solo vs AI' : 'Pass & Play'} · Round {r.core.state.round} · height {r.core.state.position}/8
                </div>
              </div>
              <div className="flex gap-2">
                <Button size="sm" variant="secondary" aria-label="Delete saved game" onClick={() => void deleteMatch(r.id).then(refresh)}>
                  Delete
                </Button>
                <Button size="sm" onClick={() => navigate({ name: 'local', id: r.id })} data-testid="resume-local">
                  Resume
                </Button>
              </div>
            </Panel>
          ))}
          {finished.length > 0 && <h3 className="mt-2 text-sm font-black uppercase tracking-wider text-sand/70">Recently finished</h3>}
          {finished.map((r) => (
            <button key={r.id} type="button" className="focus-ring rounded-xl bg-white/5 px-3 py-2 text-left text-sm text-sand" onClick={() => navigate({ name: 'local', id: r.id })}>
              {getRoute(r.routeId).name} — {r.core.state.status === 'won' ? `summit, ${r.core.state.result?.carabiners}★` : 'failed'}
            </button>
          ))}
        </section>
      </div>
    </Screen>
  );
}
