import { useMemo, useState, type ReactNode } from 'react';
import { navigate } from '../app/router.tsx';
import { ClimbingWall } from '../components/climbing/ClimbingWall.tsx';
import { Button, Panel, Screen, ScreenHeader } from '../components/ui/Primitives.tsx';
import { ROUTES } from '../data/routes/index.ts';
import { Planner } from '../engine/ai/planner.ts';
import { DEFAULT_CONFIG } from '../engine/config.ts';
import { validateRoute } from '../engine/routes.ts';
import { createInitialState } from '../engine/state.ts';
import type { RouteDefinition, Terrain } from '../engine/types.ts';

const TERRAINS: Terrain[] = ['Vertical', 'Overhang', 'Technical Face', 'Slab', 'Crack', 'Roof'];
const parseList = (s: string) =>
  s
    .split(/[\s,]+/)
    .filter(Boolean)
    .map(Number);

/**
 * Developer tool: design a route as data, validate it with the same validator the engine uses,
 * preview the generated wall and get the exact team-optimal completion estimate. Export the JSON
 * into src/data/routes to ship it (then run `npm run sync:engine` for the server).
 */
export function RouteEditorScreen() {
  const [route, setRoute] = useState<RouteDefinition>({ ...ROUTES[0]!, id: 'my-new-route', name: 'My New Route', order: ROUTES.length + 1 });
  const [difficultyText, setDifficultyText] = useState(route.difficulty.join(', '));
  const [restText, setRestText] = useState(route.restHolds.join(', '));
  const [boltText, setBoltText] = useState(route.bolts.join(', '));
  const [estimate, setEstimate] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  const candidate: RouteDefinition = useMemo(
    () => ({ ...route, difficulty: parseList(difficultyText), restHolds: parseList(restText), bolts: parseList(boltText), length: parseList(difficultyText).length }),
    [route, difficultyText, restText, boltText],
  );
  const issues = validateRoute(candidate);
  const set = (patch: Partial<RouteDefinition>) => {
    setRoute({ ...route, ...patch });
    setEstimate(null);
  };

  const runEstimate = () => {
    setEstimate('Calculating…');
    setTimeout(() => {
      const planner = new Planner(candidate, DEFAULT_CONFIG);
      const v = planner.value(createInitialState(candidate));
      setEstimate(`Best possible completion with perfect teamwork: ~${Math.round(Math.min(1, v) * 100)}% (exact expectimax over ${planner.cacheSize.toLocaleString()} states)`);
    }, 30);
  };

  const json = JSON.stringify(candidate, null, 2);

  return (
    <Screen>
      <ScreenHeader title="Route editor" subtitle="Developer tool" onBack={() => navigate({ name: 'routes' })} />
      <div className="grid gap-4 lg:grid-cols-[1fr_320px]">
        <Panel className="grid gap-3 sm:grid-cols-2">
          <Field label="Id">
            <input className="input" value={route.id} onChange={(e) => set({ id: e.target.value })} />
          </Field>
          <Field label="Name">
            <input className="input" value={route.name} onChange={(e) => set({ name: e.target.value })} />
          </Field>
          <Field label="Grade label">
            <input className="input" value={route.grade} onChange={(e) => set({ grade: e.target.value })} />
          </Field>
          <Field label="Terrain">
            <select className="input" value={route.terrain} onChange={(e) => set({ terrain: e.target.value as Terrain })}>
              {TERRAINS.map((t) => (
                <option key={t}>{t}</option>
              ))}
            </select>
          </Field>
          <Field label="Hold difficulty, position 1 → anchor (1–6 each)" wide>
            <input className="input font-mono" value={difficultyText} onChange={(e) => { setDifficultyText(e.target.value); setEstimate(null); }} />
          </Field>
          <Field label="Rest holds">
            <input className="input font-mono" value={restText} onChange={(e) => { setRestText(e.target.value); setEstimate(null); }} />
          </Field>
          <Field label="Bolts">
            <input className="input font-mono" value={boltText} onChange={(e) => { setBoltText(e.target.value); setEstimate(null); }} />
          </Field>
          <Field label="Description" wide>
            <textarea className="input min-h-20" value={route.description} onChange={(e) => set({ description: e.target.value })} />
          </Field>
          {(['skyTop', 'skyBottom', 'rock', 'rockShadow', 'accent'] as const).map((k) => (
            <Field key={k} label={k}>
              <input type="color" className="h-11 w-full rounded-lg" value={route.theme[k]} onChange={(e) => set({ theme: { ...route.theme, [k]: e.target.value } })} />
            </Field>
          ))}
          <div className="sm:col-span-2">
            {issues.length ? (
              <ul className="list-disc rounded-xl bg-danger/10 p-3 pl-7 text-sm font-bold text-danger" role="alert">
                {issues.map((i, n) => (
                  <li key={n}>
                    {i.field}: {i.message}
                  </li>
                ))}
              </ul>
            ) : (
              <p className="rounded-xl bg-success/10 p-3 text-sm font-bold text-success">Route is valid.</p>
            )}
          </div>
          <div className="flex flex-wrap gap-2 sm:col-span-2">
            <Button size="sm" disabled={issues.length > 0} onClick={runEstimate}>
              Estimate difficulty
            </Button>
            <Button
              size="sm"
              variant="secondary"
              disabled={issues.length > 0}
              onClick={async () => {
                await navigator.clipboard.writeText(json).catch(() => undefined);
                setCopied(true);
              }}
            >
              {copied ? 'Copied JSON' : 'Copy JSON'}
            </Button>
          </div>
          {estimate && <p className="text-sm font-bold sm:col-span-2">{estimate}</p>}
        </Panel>
        <div className="overflow-hidden rounded-3xl border-4 border-cream/90">
          {issues.length === 0 ? (
            <ClimbingWall className="block h-[70vh] w-full" route={candidate} position={0} clippedBolts={[]} rope={1} />
          ) : (
            <div className="grid h-[70vh] place-items-center p-6 text-center text-cream">Fix the issues to preview the wall.</div>
          )}
        </div>
      </div>
      <style>{`.input{display:block;width:100%;min-height:2.75rem;border-radius:.75rem;border:1px solid rgba(0,0,0,.15);background:#fff;padding:.5rem .75rem}`}</style>
    </Screen>
  );
}

function Field({ label, children, wide }: { label: string; children: ReactNode; wide?: boolean }) {
  return (
    <label className={`block ${wide ? 'sm:col-span-2' : ''}`}>
      <span className="text-xs font-black uppercase tracking-wider text-ink-soft">{label}</span>
      <div className="mt-1">{children}</div>
    </label>
  );
}
