import { z } from 'zod';
import type { GameState, PublicDeclaration, Role, Submission, TeamworkPolicy, ClimberSignal, BelayerSignal } from '../engine/types.ts';
import { anonApiKey, functionsUrl, supabase } from './client.ts';
import { currentAccessToken, ensureSession } from './auth.ts';

/**
 * Client side of the online protocol. Reads use Row Level Security-protected selects; every
 * write goes through the `game-action` Edge Function, which validates the caller, the round and
 * the expected state version inside one database transaction.
 */

export type OnlineStatus = 'lobby' | 'in_progress' | 'won' | 'lost' | 'abandoned';

export interface Participant {
  userId: string;
  nickname: string;
  avatar: string;
  role: Role | null;
  lastSeenAt: string;
}

export interface GameEvent {
  id: number;
  kind: string;
  payload: Record<string, unknown>;
  userId: string | null;
  createdAt: string;
}

export interface OnlineGameView {
  id: string;
  roomCode: string;
  routeId: string;
  status: OnlineStatus;
  createdBy: string;
  rematchGameId: string | null;
  participants: Participant[];
  state: GameState | null;
  version: number;
  stateVersion: number;
  committed: Record<Role, boolean>;
  declarations: Record<Role, PublicDeclaration | null>;
  events: GameEvent[];
  myUserId: string;
  myRole: Role | null;
  /** My own committed action for the current round (never the partner's). */
  myPending: Submission | null;
}

export interface OnlineGameSummary {
  id: string;
  roomCode: string;
  routeId: string;
  status: OnlineStatus;
  role: Role | null;
  statusText: string;
  yourTurn: boolean;
  updatedAt: string;
}

export class ActionError extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly status: number,
  ) {
    super(message);
  }
}

const actionResponse = z.object({ ok: z.boolean(), error: z.string().optional(), code: z.string().optional() }).passthrough();

async function callAction<T>(action: string, payload: Record<string, unknown>): Promise<T> {
  const token = await currentAccessToken();
  let res: Response;
  try {
    res = await fetch(`${functionsUrl()}/game-action`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}`, apikey: anonApiKey() },
      body: JSON.stringify({ action, ...payload }),
    });
  } catch {
    throw new ActionError('No connection to the game server.', 'network', 0);
  }
  const json = actionResponse.safeParse(await res.json().catch(() => ({})));
  if (!res.ok || !json.success || !json.data.ok) {
    const data = json.success ? json.data : { error: 'Unexpected server response', code: 'bad_response' };
    throw new ActionError(data.error ?? `Server error ${res.status}`, data.code ?? 'error', res.status);
  }
  return json.data as T;
}

export const createGame = (routeId: string, preferredRole: Role, nickname: string, avatar: string) =>
  callAction<{ ok: true; gameId: string; roomCode: string }>('create', { routeId, preferredRole, nickname, avatar });

export const joinGame = (roomCode: string, nickname: string, avatar: string) =>
  callAction<{ ok: true; gameId: string }>('join', { roomCode, nickname, avatar });

export const chooseRole = (gameId: string, role: Role) => callAction<{ ok: true }>('choose_role', { gameId, role });
export const startGame = (gameId: string) => callAction<{ ok: true }>('start', { gameId });

export const declareOnline = (
  gameId: string,
  round: number,
  stateVersion: number,
  signal: ClimberSignal | BelayerSignal | null,
  teamworkPolicy: TeamworkPolicy,
) => callAction<{ ok: true }>('declare', { gameId, round, stateVersion, signal, teamworkPolicy });

export const submitTurn = (gameId: string, round: number, stateVersion: number, submission: Submission) =>
  callAction<{ ok: true; resolved: boolean; duplicate?: boolean }>('submit', { gameId, round, stateVersion, submission });

export const forfeitGame = (gameId: string) => callAction<{ ok: true }>('forfeit', { gameId });
export const rematch = (gameId: string) => callAction<{ ok: true; gameId: string }>('rematch', { gameId });
export const sendChat = (gameId: string, text: string) => callAction<{ ok: true }>('chat', { gameId, text });
export const heartbeat = (gameId: string) => callAction<{ ok: true }>('heartbeat', { gameId });

interface GameRow {
  id: string;
  room_code: string;
  route_id: string;
  status: OnlineStatus;
  created_by: string;
  rematch_game_id: string | null;
  updated_at: string;
}

/** Load everything this user may see about a game. RLS guarantees the rest is unreachable. */
export async function loadGameView(gameId: string): Promise<OnlineGameView> {
  const { userId } = await ensureSession();
  const sb = await supabase();
  const [game, parts, pub, events, mine] = await Promise.all([
    sb.from('games').select('id, room_code, route_id, status, created_by, rematch_game_id, updated_at').eq('id', gameId).maybeSingle(),
    sb.from('game_participants').select('user_id, nickname, avatar, role, last_seen_at').eq('game_id', gameId),
    sb.from('game_public_state').select('*').eq('game_id', gameId).maybeSingle(),
    sb.from('game_events').select('id, kind, payload, user_id, created_at').eq('game_id', gameId).order('id', { ascending: false }).limit(50),
    sb.from('private_turn_actions').select('round, submission').eq('game_id', gameId).eq('user_id', userId),
  ]);
  for (const r of [game, parts, pub, events, mine]) if (r.error) throw new Error(r.error.message);
  if (!game.data) throw new ActionError('Game not found, or you are not a player in it.', 'not_found', 404);
  const g = game.data as GameRow;
  const participants: Participant[] = (parts.data ?? []).map((p) => ({
    userId: p.user_id as string,
    nickname: p.nickname as string,
    avatar: (p.avatar as string) ?? 'summit',
    role: (p.role as Role | null) ?? null,
    lastSeenAt: p.last_seen_at as string,
  }));
  const ps = pub.data as null | {
    state: GameState | null;
    version: number;
    state_version: number;
    climber_committed: boolean;
    belayer_committed: boolean;
    climber_declaration: PublicDeclaration | null;
    belayer_declaration: PublicDeclaration | null;
  };
  const myRole = participants.find((p) => p.userId === userId)?.role ?? null;
  const round = ps?.state?.round ?? 0;
  const pendingRow = (mine.data ?? []).find((r) => r.round === round);
  return {
    id: g.id,
    roomCode: g.room_code,
    routeId: g.route_id,
    status: g.status,
    createdBy: g.created_by,
    rematchGameId: g.rematch_game_id,
    participants,
    state: ps?.state ?? null,
    version: ps?.version ?? 0,
    stateVersion: ps?.state_version ?? 0,
    committed: { climber: !!ps?.climber_committed, belayer: !!ps?.belayer_committed },
    declarations: { climber: ps?.climber_declaration ?? null, belayer: ps?.belayer_declaration ?? null },
    events: ((events.data ?? []) as { id: number; kind: string; payload: Record<string, unknown>; user_id: string | null; created_at: string }[])
      .map((e) => ({ id: e.id, kind: e.kind, payload: e.payload, userId: e.user_id, createdAt: e.created_at }))
      .reverse(),
    myUserId: userId,
    myRole,
    myPending: pendingRow && ps?.state?.status === 'in_progress' ? (pendingRow.submission as Submission) : null,
  };
}

export async function listMyOnlineGames(): Promise<OnlineGameSummary[]> {
  const { userId } = await ensureSession();
  const sb = await supabase();
  const { data: mine, error } = await sb.from('game_participants').select('game_id, role').eq('user_id', userId);
  if (error) throw new Error(error.message);
  const ids = (mine ?? []).map((m) => m.game_id as string);
  if (!ids.length) return [];
  const [games, pubs] = await Promise.all([
    sb.from('games').select('id, room_code, route_id, status, updated_at').in('id', ids).order('updated_at', { ascending: false }),
    sb.from('game_public_state').select('game_id, climber_committed, belayer_committed, state').in('game_id', ids),
  ]);
  if (games.error) throw new Error(games.error.message);
  return (games.data ?? []).map((g) => {
    const role = ((mine ?? []).find((m) => m.game_id === g.id)?.role as Role | null) ?? null;
    const pub = (pubs.data ?? []).find((p) => p.game_id === g.id);
    const myCommitted = role ? !!pub?.[`${role}_committed` as 'climber_committed'] : true;
    const status = g.status as OnlineStatus;
    const round = (pub?.state as GameState | null)?.round;
    const statusText =
      status === 'lobby'
        ? 'In lobby'
        : status === 'in_progress'
          ? myCommitted
            ? `Round ${round} · waiting for partner`
            : `Round ${round} · your move`
          : status === 'won'
            ? 'Summit!'
            : status === 'abandoned'
              ? 'Abandoned'
              : 'Failed ascent';
    return {
      id: g.id as string,
      roomCode: g.room_code as string,
      routeId: g.route_id as string,
      status,
      role,
      statusText,
      yourTurn: status === 'in_progress' && !myCommitted,
      updatedAt: g.updated_at as string,
    };
  });
}
