function Bolt({ x, y, clipped, reduced }: { x: number; y: number; clipped: boolean; reduced: boolean }) {
  const hanger = art('bolt-hanger');
  const hw = 13;
  const hh = hanger ? (hw * hanger.h) / hanger.w : 0;
  return (
    <g aria-hidden>
      {hanger ? (
        <image href={hanger.url} x={x - hw * 0.42} y={y - hh * 0.28} width={hw} height={hh} />
      ) : (
        <>
          <circle cx={x} cy={y} r={5.5} fill="#c9ced3" stroke="#4b5257" strokeWidth={1.6} />
          <circle cx={x} cy={y} r={2} fill="#4b5257" />
        </>
      )}
      {clipped && (
        <motion.g
          initial={reduced ? false : { scale: 0.2, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ type: 'spring', stiffness: 420, damping: 16 }}
          style={{ transformOrigin: `${x}px ${y}px` }}
        >
          <ellipse cx={x} cy={y + 9} rx={3.5} ry={6} fill="none" stroke="#e07a3f" strokeWidth={2} />
          <rect x={x - 2.5} y={y + 14} width={5} height={10} rx={2} fill="#2f8f83" />
          <ellipse cx={x} cy={y + 29} rx={3.5} ry={6} fill="none" stroke="#e07a3f" strokeWidth={2} />
        </motion.g>
      )}
    </g>
  );
}

function RestIcon({ x, y }: { x: number; y: number }) {
  // A small tent-and-leaf badge: rest holds are marked by shape and label, not only colour.
  return (
    <g aria-hidden transform={`translate(${x},${y})`}>
      <rect x={-17} y={-8} width={34} height={14} rx={7} fill="#1e3d34" opacity={0.85} />
      <text x={0} y={2.5} textAnchor="middle" fontSize={8.5} fontWeight={800} fill="#fbf5ea" letterSpacing={0.6}>
        REST
      </text>
    </g>
  );
}

/**
 * The rope as cubic curves that hang under gravity: each span bows downward (and, when nearly
 * vertical, a little to the side) by an amount that grows with its length. The span to the climber
 * also sags with the rope available, so feeding slack is visible.
 */
function ropePath(points: { x: number; y: number }[], slack: number) {
  if (points.length < 2) return '';
  let d = `M${points[0]!.x},${points[0]!.y}`;
  for (let i = 1; i < points.length; i++) {
    const a = points[i - 1]!;
    const b = points[i]!;
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const len = Math.hypot(dx, dy) || 1;
    const last = i === points.length - 1;
    const sag = len * (last ? 0.07 + slack * 0.035 : 0.05) + (last ? 3 : 1.5);
    // Unit normal on the downhill side; vertical spans bow outward to the right.
    let nx = -dy / len;
    let ny = dx / len;
    if (ny < 0 || (Math.abs(ny) < 0.2 && nx < 0)) {
      nx = -nx;
      ny = -ny;
    }
    const ox = nx * sag;
    const oy = ny * sag + sag * 0.6;
    const c1 = { x: a.x + dx / 3 + ox, y: a.y + dy / 3 + oy };
    const c2 = { x: a.x + (2 * dx) / 3 + ox, y: a.y + (2 * dy) / 3 + oy };
    d += ` C${c1.x.toFixed(1)},${c1.y.toFixed(1)} ${c2.x.toFixed(1)},${c2.y.toFixed(1)} ${b.x},${b.y}`;
  }
  return d;
}

/** Painted-style kernmantle rope: shadow, dark outline, gold body, light core and braid flecks. */
const ROPE_LAYERS = [
  { stroke: '#1d2422', width: 1.9, opacity: 0.25, dx: 1.2, dy: 1.8 },
  { stroke: '#6b4513', width: 1.7 },
  { stroke: '#d9a038', width: 1.3 },
  { stroke: '#f3c95c', width: 0.75 },
  // Fine braid texture, then thin coloured tracer threads (narrower than the rope, so they read as
  // flecks in the sheath rather than bands across it).
  { stroke: '#a8691d', width: 1.05, opacity: 0.55, dash: '0.45 0.75' },
  { stroke: '#c8643b', width: 0.42, dash: '1.4 4.6' },
  { stroke: '#2f8f83', width: 0.42, dash: '1.4 4.6', dashOffset: -3 },
  { stroke: '#fff1c4', width: 0.2, opacity: 0.75, dash: '7 3' },
] as const;

function Rope({ d, width, reduced }: { d: string; width: number; reduced: boolean }) {
  const transition = reduced ? { duration: 0 } : { type: 'spring' as const, stiffness: 120, damping: 18 };
  return (
    <g aria-hidden data-testid="rope">
      {ROPE_LAYERS.map((l, i) => (
        <motion.path
          key={i}
          d={d}
          animate={{ d }}
          transition={transition}
          transform={'dx' in l ? `translate(${l.dx},${l.dy})` : undefined}
          stroke={l.stroke}
          strokeOpacity={'opacity' in l ? l.opacity : 1}
          strokeWidth={width * l.width}
          strokeDasharray={'dash' in l ? l.dash.split(' ').map((n) => Number(n) * width).join(' ') : undefined}
          strokeDashoffset={'dashOffset' in l ? l.dashOffset * width : undefined}
          fill="none"
          strokeLinecap={'dash' in l ? 'butt' : 'round'}
          strokeLinejoin="round"
        />
      ))}
    </g>
  );
}

/** Size and rope tie-in point of a character image, in wall units relative to its anchor. */
function spriteBox(a: ArtAsset & { name: string }, standing = false) {
  const anchor = CHARACTER_ANCHORS[a.name] ?? { harness: [0.5, 0.48] as [number, number], height: 64, top: 6 };
  const height = anchor.height;
  const width = (height * a.w) / a.h;
  const top = standing ? height - 4 : (anchor.top ?? 0);
  return {
    width,
    height,
    top,
    harnessFromTop: height * anchor.harness[1],
    // For climbers the image hangs from the hold at (0,0); for belayers x is relative to the feet.
    harness: { x: -width / 2 + width * anchor.harness[0], y: -top + height * anchor.harness[1] },
  };
}

export function ClimbingWall({
  route,
  position,
  clippedBolts,
  rope,
  showReach = false,
  perspective = 'neutral',
  fallFrom = null,
  summit = false,
  className,
  title,
  fit = 'contain',
  climberPose,
  belayerPose,
}: WallProps) {
  const reduced = !!useReducedMotion();
  const [ref, box] = useBoxSize<SVGSVGElement>();
  const climberAt = holdPoint(route, position);
  const belayerAt = { x: 96, y: GROUND_Y + 2 };
  const backdrop = art(`route-${route.id}`);
  // Painted characters (with the vector ones as fallback). The arms-up summit pose stands in for
  // the climbing pose until a dedicated one exists.
  const climberArt = summit
    ? firstArt('climber-summit', 'climber-climb')
    : fallFrom !== null
      ? firstArt('climber-fall', 'climber-climb', 'climber-summit')
      : firstArt(`climber-${climberPose ?? 'climb'}`, 'climber-climb', 'climber-summit');
  const belayerArt = firstArt(`belayer-${belayerPose ?? 'belay'}`, 'belayer-belay', 'belayer-brace');
  // On the ground (position 0) the climber stands rather than hanging from a hold.
  const climberSprite = climberArt ? spriteBox(climberArt, position === 0 && fallFrom === null) : null;
  const belayerSprite = belayerArt ? spriteBox(belayerArt) : null;
  const harness = climberSprite
    ? { x: climberAt.x + climberSprite.harness.x, y: climberAt.y + climberSprite.harness.y }
    : { x: climberAt.x + 2, y: climberAt.y - 4 };
  const clippedPoints = [...clippedBolts].sort((a, b) => a - b).map((b) => {
    const p = boltPoint(route, b);
    return { x: p.x, y: p.y + 29 };
  });
  const belayDevice = belayerSprite
    ? { x: belayerAt.x + belayerSprite.harness.x, y: belayerAt.y + 2 - belayerSprite.height + belayerSprite.harnessFromTop }
    : { x: belayerAt.x + 10, y: belayerAt.y - 22 };
  const ropePts = [belayDevice, ...clippedPoints, harness];
  const anchor = holdPoint(route, route.length);
  const anchorArt = art('anchor');
  const fallStart = fallFrom !== null ? holdPoint(route, fallFrom) : null;

  const reachable = showReach ? [position + 1, position + 2].filter((p) => p <= route.length) : [];

  // Camera: in 'follow' mode the visible window keeps the wall's full width and is as tall as
  // the box allows; it keeps the climber in the lower part so the next holds stay in view.
  let viewBox = `0 0 ${WALL_W} ${WALL_H}`;
  if (fit === 'follow' && box) {
    // Tall boxes (tablets, desktops) show the whole route; short phone boxes zoom and follow.
    const windowH = box.h >= 560 ? WALL_H : Math.min(WALL_H, Math.max(MIN_WINDOW, (box.h * WALL_W) / box.w));
    const focusY = (fallStart && fallStart.y < climberAt.y ? climberAt.y : climberAt.y) - windowH * 0.66;
    const y0 = Math.max(0, Math.min(WALL_H - windowH, focusY));
    viewBox = `0 ${y0.toFixed(1)} ${WALL_W} ${windowH.toFixed(1)}`;
  }

  return (
    <motion.svg
      ref={ref}
      initial={false}
      animate={{ viewBox }}
      transition={reduced ? { duration: 0 } : { type: 'spring', stiffness: 70, damping: 18 }}
      viewBox={viewBox}
      className={`overflow-hidden ${className ?? ''}`}
      role="img"
      aria-label={title ?? `${route.name} climbing wall. Climber at position ${position} of ${route.length}. ${rope} rope available.`}
      preserveAspectRatio="xMidYMid meet"
      overflow="visible"
      pointerEvents="none"
    >
      <Scenery route={route} />
      {backdrop ? (
        // Painted backdrop: 2:3 art scaled so its ground ledge lines up with the belay stance.
        <image href={backdrop.url} x={-46.7} y={-44} width={453.4} height={680} preserveAspectRatio="xMidYMid slice" />
      ) : (
        <RockFace route={route} />
      )}

      {/* Route line hint */}
      <path
        d={Array.from({ length: route.length + 1 }, (_, p) => holdPoint(route, p))
          .map((pt, i) => `${i ? 'L' : 'M'}${pt.x},${pt.y}`)
          .join(' ')}
        stroke="#ffffff"
        strokeOpacity={backdrop ? 0.12 : 0.16}
        strokeWidth={10}
        strokeLinejoin="round"
        fill="none"
      />

      {/* Holds 1..length-1, anchor at length */}
      {Array.from({ length: route.length - 1 }, (_, i) => i + 1).map((p) => {
        const pt = holdPoint(route, p);
        const d = route.difficulty[p - 1]!;
        const rest = route.restHolds.includes(p);
        const isReach = reachable.includes(p);
        const badgeX = pt.x + (p % 2 === 0 ? 30 : -30);
        return (
          <g key={p} data-position={p}>
            {isReach && !reduced && (
              <motion.circle
                cx={pt.x}
                cy={pt.y}
                r={24}
                fill="none"
                stroke="#fbf5ea"
                strokeWidth={2.5}
                strokeDasharray="5 5"
                animate={{ rotate: 360 }}
                transition={{ repeat: Infinity, duration: 12, ease: 'linear' }}
                style={{ transformOrigin: `${pt.x}px ${pt.y}px` }}
              />
            )}
            {isReach && reduced && <circle cx={pt.x} cy={pt.y} r={24} fill="none" stroke="#fbf5ea" strokeWidth={2.5} strokeDasharray="5 5" />}
            <HoldShape difficulty={d} x={pt.x} y={pt.y} rest={rest} fill={route.theme.accent} shade="#1d2422" />
            <g transform={`translate(${p % 2 === 0 ? badgeX - 46 : badgeX + 46},${pt.y})`}>
              <circle r={11} fill="#fbf5ea" stroke="#1d2422" strokeWidth={1.5} />
              <text y={4} textAnchor="middle" fontSize={11.5} fontWeight={800} fill="#1d2422">
                {d}
              </text>
            </g>
            {rest && <RestIcon x={pt.x} y={pt.y + 20} />}
            {route.bolts.includes(p) && <Bolt {...boltPoint(route, p)} clipped={clippedBolts.includes(p)} reduced={reduced} />}
            {isReach && (
              <text x={pt.x} y={pt.y - 28} textAnchor="middle" fontSize={9} fontWeight={800} fill="#fbf5ea" letterSpacing={0.8}>
                {p === position + 1 ? 'STEP' : 'REACH'}
              </text>
            )}
          </g>
        );
      })}

      {/* Finishing anchor: chains and ring */}
      <g aria-hidden>
        {anchorArt ? (
          // The painted ring sits 78% of the way down the image, at the same point as the drawn ring.
          <image href={anchorArt.url} x={anchor.x - 17} y={anchor.y + 10 - (34 * anchorArt.h * 0.78) / anchorArt.w} width={34} height={(34 * anchorArt.h) / anchorArt.w} />
        ) : (
          <>
            <circle cx={anchor.x - 9} cy={anchor.y - 12} r={4.5} fill="#c9ced3" stroke="#4b5257" strokeWidth={1.5} />
            <circle cx={anchor.x + 9} cy={anchor.y - 12} r={4.5} fill="#c9ced3" stroke="#4b5257" strokeWidth={1.5} />
            <path d={`M${anchor.x - 9},${anchor.y - 8} L${anchor.x},${anchor.y + 6} L${anchor.x + 9},${anchor.y - 8}`} stroke="#4b5257" strokeWidth={2.5} fill="none" strokeDasharray="3 2" />
            <circle cx={anchor.x} cy={anchor.y + 10} r={6} fill="none" stroke="#e9b44c" strokeWidth={3} />
          </>
        )}
        <rect x={anchor.x - 30} y={anchor.y - 40} width={60} height={15} rx={7.5} fill="#1e3d34" />
        <text x={anchor.x} y={anchor.y - 29.5} textAnchor="middle" fontSize={8.5} fontWeight={800} fill="#fbf5ea" letterSpacing={1}>
          ANCHOR {route.difficulty[route.length - 1]}
        </text>
        {reachable.includes(route.length) && (
          <circle cx={anchor.x} cy={anchor.y + 6} r={22} fill="none" stroke="#fbf5ea" strokeWidth={2.5} strokeDasharray="5 5" />
        )}
      </g>

      {!backdrop && <Ground />}

      {/* Rope: belayer → ground anchor → clipped bolts → climber. Sag grows with available rope. */}
      <Rope d={ropePath(ropePts, rope)} width={perspective === 'belayer' ? 3.6 : 3} reduced={!!reduced} />
      {/* Coiled rope at the belayer's feet shows how much is available to feed. */}
      <g aria-hidden transform={`translate(${belayerAt.x - 32},${GROUND_Y + 6})`}>
        {Array.from({ length: 1 + rope }, (_, i) => (
          <g key={i}>
            <ellipse cx={0} cy={-i * 3} rx={12 - i} ry={4} fill="none" stroke="#6b4513" strokeWidth={3.6} />
            <ellipse cx={0} cy={-i * 3} rx={12 - i} ry={4} fill="none" stroke="#d4962c" strokeWidth={2.6} />
            <ellipse cx={0} cy={-i * 3} rx={12 - i} ry={4} fill="none" stroke="#c8643b" strokeWidth={2} strokeDasharray="2 5" />
            <ellipse cx={0} cy={-i * 3 - 0.6} rx={12 - i} ry={4} fill="none" stroke="#f3c95c" strokeWidth={0.9} />
          </g>
        ))}
      </g>

      {belayerSprite && belayerArt ? (
        <g aria-hidden>
          {perspective === 'belayer' && <ellipse cx={belayerAt.x} cy={belayerAt.y - 36} rx={30} ry={44} fill="#fbf5ea" opacity={0.18} />}
          <image
            href={belayerArt.url}
            x={belayerAt.x - belayerSprite.width / 2}
            y={belayerAt.y + 2 - belayerSprite.height}
            width={belayerSprite.width}
            height={belayerSprite.height}
          />
        </g>
      ) : (
        <Belayer x={belayerAt.x} y={belayerAt.y} highlight={perspective === 'belayer'} />
      )}

      <motion.g
        initial={false}
        animate={{ x: climberAt.x, y: climberAt.y }}
        transition={
          reduced
            ? { duration: 0 }
            : fallStart
              ? { type: 'spring', stiffness: 260, damping: 9, mass: 1.1 }
              : { type: 'spring', stiffness: 90, damping: 14 }
        }
      >
        {climberSprite && climberArt ? (
          <motion.g
            aria-hidden
            animate={summit && !reduced ? { y: [0, -8, 0] } : { y: 0 }}
            transition={summit ? { repeat: Infinity, duration: 0.9 } : { duration: 0.2 }}
          >
            {perspective === 'climber' && <circle cx={climberSprite.harness.x} cy={climberSprite.harness.y - 8} r={30} fill="#fbf5ea" opacity={0.2} />}
            <image href={climberArt.url} x={-climberSprite.width / 2} y={-climberSprite.top} width={climberSprite.width} height={climberSprite.height} />
          </motion.g>
        ) : (
          <Climber highlight={perspective === 'climber'} celebrating={summit} />
        )}
      </motion.g>

      {perspective === 'belayer' && (
        <g aria-hidden>
          <rect x={10} y={GROUND_Y - 64} width={70} height={22} rx={11} fill="#1e3d34" opacity={0.9} />
          <text x={45} y={GROUND_Y - 49} textAnchor="middle" fontSize={10} fontWeight={800} fill="#e9b44c">
            ROPE {rope}/3
          </text>
        </g>
      )}
    </motion.svg>
  );
}
