import { ART_MANIFEST } from './manifest.generated.ts';

/**
 * Painted artwork from art-source/ (see docs/ART_BRIEF.md). Every lookup can return null: the
 * game then uses its built-in vector art, so assets can be added one at a time.
 */
export interface ArtAsset {
  url: string;
  w: number;
  h: number;
}

export function art(name: string): ArtAsset | null {
  const a = ART_MANIFEST[name];
  if (!a) return null;
  const base = (import.meta.env?.BASE_URL as string | undefined) ?? '/';
  return { url: `${base}${a.file}`, w: a.w, h: a.h };
}

/** First available asset among candidates (preferred first). */
export function firstArt(...names: string[]): (ArtAsset & { name: string }) | null {
  for (const n of names) {
    const a = art(n);
    if (a) return { ...a, name: n };
  }
  return null;
}

