import { useState } from 'react';
import { navigate } from '../app/router.tsx';
import { useSettings } from '../app/settings.tsx';
import { Avatar, AVATARS } from '../components/ui/Avatar.tsx';
import { Button, Panel, Screen, ScreenHeader } from '../components/ui/Primitives.tsx';
import { onlineConfigured } from '../multiplayer/client.ts';
import { signInWithEmail, upgradeAccount, useOnlineSession } from '../multiplayer/auth.ts';
import { nicknameSchema } from '../schemas/index.ts';

export function ProfileScreen({ onDone }: { onDone?: () => void }) {
  const { profile, updateProfile } = useSettings();
  const session = useOnlineSession();
  const [nickname, setNickname] = useState(profile.nickname);
  const [avatar, setAvatar] = useState(profile.avatar);
  const [error, setError] = useState<string | null>(null);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [accountMsg, setAccountMsg] = useState<string | null>(null);

  const save = () => {
    const parsed = nicknameSchema.safeParse(nickname);
    if (!parsed.success) return setError(parsed.error.issues[0]?.message ?? 'Invalid nickname');
    updateProfile({ nickname: parsed.data, avatar });
    if (onDone) onDone();
    else navigate({ name: 'home' });
  };

  const account = async (mode: 'upgrade' | 'signin') => {
    setAccountMsg(null);
    try {
      if (mode === 'upgrade') await upgradeAccount(email, password);
      else await signInWithEmail(email, password);
      setAccountMsg(mode === 'upgrade' ? 'Account saved. Check your email if confirmation is required.' : 'Signed in.');
    } catch (e) {
      setAccountMsg(e instanceof Error ? e.message : String(e));
    }
  };

  return (
    <Screen>
      <ScreenHeader title="Your climber" onBack={() => navigate({ name: 'home' })} />
      <div className="mx-auto grid max-w-3xl gap-4 md:grid-cols-2">
        <Panel>
          <label className="block">
            <span className="text-xs font-black uppercase tracking-wider text-ink-soft">Nickname</span>
            <input
              className="focus-ring mt-1 block min-h-12 w-full rounded-xl border border-black/15 bg-white px-3 text-lg"
              value={nickname}
              maxLength={20}
              onChange={(e) => {
                setNickname(e.target.value);
                setError(null);
              }}
              placeholder="e.g. Crimp Queen"
              data-testid="nickname-input"
            />
          </label>
          {error && <p className="mt-1 text-sm font-bold text-danger">{error}</p>}
          <div className="mt-3 text-xs font-black uppercase tracking-wider text-ink-soft">Avatar</div>
          <div className="mt-1 grid grid-cols-4 gap-2" role="radiogroup" aria-label="Avatar">
            {AVATARS.map((a) => (
              <button key={a} type="button" role="radio" aria-checked={avatar === a} aria-label={a} onClick={() => setAvatar(a)} className={`focus-ring grid place-items-center rounded-2xl p-1.5 ${avatar === a ? 'bg-ember/20 ring-2 ring-ember' : 'bg-sand/60'}`}>
                <Avatar id={a} size={52} />
              </button>
            ))}
          </div>
          <Button className="mt-4 w-full" onClick={save} data-testid="save-profile">
            Save
          </Button>
        </Panel>
        <Panel>
          <h2 className="font-display text-xl font-bold">Online account (optional)</h2>
          {!onlineConfigured ? (
            <p className="mt-1 text-sm text-ink-soft">Online play is not configured in this build.</p>
          ) : (
            <>
              <p className="mt-1 text-sm text-ink-soft">
                {session?.isAnonymous !== false
                  ? 'You play online as a guest — your identity is saved on this device. Add an email to keep your games on other devices.'
                  : `Signed in as ${session.email}.`}
              </p>
              {session?.isAnonymous !== false && (
                <div className="mt-2 flex flex-col gap-2">
                  <input className="focus-ring min-h-12 rounded-xl border border-black/15 bg-white px-3" type="email" placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} autoComplete="email" />
                  <input className="focus-ring min-h-12 rounded-xl border border-black/15 bg-white px-3" type="password" placeholder="Password (8+ characters)" value={password} onChange={(e) => setPassword(e.target.value)} autoComplete="new-password" />
                  <div className="flex gap-2">
                    <Button size="sm" className="flex-1" onClick={() => void account('upgrade')} disabled={!email || password.length < 8}>
                      Save my guest account
                    </Button>
                    <Button size="sm" variant="secondary" className="flex-1" onClick={() => void account('signin')} disabled={!email || !password}>
                      Sign in instead
                    </Button>
                  </div>
                  {accountMsg && <p className="text-sm font-bold">{accountMsg}</p>}
                </div>
              )}
            </>
          )}
        </Panel>
      </div>
    </Screen>
  );
}
