import { gameStateShape } from '../schemas/index.ts';
import { findRoute } from '../data/routes/index.ts';
import { db, type LocalMatchRecord, type RouteResultRecord } from './db.ts';

/**
 * Local game storage. IndexedDB is the durable store; an in-memory copy is always kept too, so
 * the game stays playable for the session when the browser blocks storage (private windows,
 * embedded frames, cleared site data). Storage failures are never fatal.
 */
const memoryMatches = new Map<string, LocalMatchRecord>();
const memoryResults: RouteResultRecord[] = [];

async function tryDb<T>(fn: () => Promise<T>): Promise<T | undefined> {
  try {
    return await fn();
  } catch {
    return undefined;
  }
}

/** Validate a record read back from IndexedDB; corrupt or foreign data is ignored, not trusted. */
export function isValidRecord(r: unknown): r is LocalMatchRecord {
  if (!r || typeof r !== 'object') return false;
  const rec = r as Partial<LocalMatchRecord>;
  if (typeof rec.id !== 'string' || !rec.core || !findRoute(String(rec.routeId))) return false;
  return gameStateShape.safeParse(rec.core.state).success && typeof rec.core.seed === 'string';
}

export async function saveMatch(input: LocalMatchRecord): Promise<void> {
  // A finished game's result is recorded once, even though later saves (e.g. after the reveal)
  // come from in-memory copies that predate the recording.
  const prev = memoryMatches.get(input.id) ?? (await tryDb(() => db.matches.get(input.id)));
  const r = prev?.recorded && prev.core.state.status !== 'in_progress' ? { ...input, recorded: true } : input;
  const finishing = r.core.state.status !== 'in_progress' && !r.recorded;
  const stored = finishing ? { ...r, recorded: true } : r;
  memoryMatches.set(r.id, stored);
  if (!finishing) {
    await tryDb(() => db.matches.put(r));
    return;
  }
  const s = r.core.state;
  const result: RouteResultRecord = {
    routeId: r.routeId,
    mode: r.mode,
    won: s.status === 'won',
    carabiners: s.result?.carabiners ?? 0,
    rounds: s.result?.roundsUsed ?? s.history.length,
    falls: s.stats.falls,
    recoveryRemaining: s.recoveryTokens,
    finishedAt: Date.now(),
  };
  memoryResults.push(result);
  await tryDb(() =>
    db.transaction('rw', db.matches, db.results, async () => {
      await db.results.add({ ...result });
      await db.matches.put(stored);
    }),
  );
}

export async function loadMatch(id: string): Promise<LocalMatchRecord | null> {
  const r = (await tryDb(() => db.matches.get(id))) ?? memoryMatches.get(id);
  return isValidRecord(r) ? r : null;
}

export async function listMatches(): Promise<LocalMatchRecord[]> {
  const stored = (await tryDb(() => db.matches.toArray())) ?? [];
  const byId = new Map<string, LocalMatchRecord>();
  for (const m of memoryMatches.values()) byId.set(m.id, m);
  for (const m of stored) if (!byId.has(m.id) || byId.get(m.id)!.updatedAt < m.updatedAt) byId.set(m.id, m);
  return [...byId.values()].filter(isValidRecord).sort((a, b) => b.updatedAt - a.updatedAt);
}

export async function deleteMatch(id: string): Promise<void> {
  memoryMatches.delete(id);
  await tryDb(() => db.matches.delete(id));
}

export interface PersonalBest {
  routeId: string;
  completions: number;
  attempts: number;
  bestCarabiners: number;
  fewestRounds: number | null;
}

export async function personalBests(): Promise<Record<string, PersonalBest>> {
  // Stored results already include this session's results when IndexedDB works.
  const results = (await tryDb(() => db.results.toArray())) ?? memoryResults;
  const out: Record<string, PersonalBest> = {};
  for (const r of results) {
    const pb = (out[r.routeId] ??= { routeId: r.routeId, completions: 0, attempts: 0, bestCarabiners: 0, fewestRounds: null });
    pb.attempts++;
    if (r.won) {
      pb.completions++;
      pb.bestCarabiners = Math.max(pb.bestCarabiners, r.carabiners);
      pb.fewestRounds = pb.fewestRounds === null ? r.rounds : Math.min(pb.fewestRounds, r.rounds);
    }
  }
  return out;
}

export async function addResult(r: RouteResultRecord) {
  memoryResults.push(r);
  await tryDb(() => db.results.add({ ...r }));
}
