import type { GameState } from './types.ts';

/**
 * Carabiners (cumulative):
 *  1 — completed the route
 *  2 — completed with at least `twoCarabinerTokens` Recovery tokens remaining
 *  3 — also completed within `threeCarabinerRounds` rounds without losing any Recovery tokens
 */
export function computeCarabiners(state: GameState): 0 | 1 | 2 | 3 {
  if (state.status !== 'won') return 0;
  const cfg = state.config;
  if (state.recoveryTokens < cfg.twoCarabinerTokens) return 1;
  const rounds = state.result?.roundsUsed ?? state.round;
  const noLoss = state.recoveryTokens === cfg.recoveryTokens;
  if (rounds <= cfg.threeCarabinerRounds && noLoss) return 3;
  return 2;
}

export interface GameSummary {
  outcome: 'won' | 'lost' | 'in_progress';
  roundsUsed: number;
  falls: number;
  recoveryRemaining: number;
  boltsClipped: number;
  teamworkUsed: boolean;
  teamworkUse: 'RESCUE' | 'CONVERT' | null;
  carabiners: 0 | 1 | 2 | 3;
}

export function summarize(state: GameState): GameSummary {
  return {
    outcome: state.status,
    roundsUsed: state.result?.roundsUsed ?? state.history.length,
    falls: state.stats.falls,
    recoveryRemaining: state.recoveryTokens,
    boltsClipped: state.clippedBolts.length,
    teamworkUsed: !state.teamworkAvailable,
    teamworkUse: state.stats.teamworkUse,
    carabiners: state.result?.carabiners ?? 0,
  };
}
