import { useEffect, useState } from 'react';
import { onlineConfigured, supabase } from './client.ts';

export interface OnlineSession {
  userId: string;
  isAnonymous: boolean;
  email: string | null;
  accessToken: string;
}

function toSession(s: { user: { id: string; is_anonymous?: boolean; email?: string | null }; access_token: string } | null): OnlineSession | null {
  if (!s) return null;
  return { userId: s.user.id, isAnonymous: !!s.user.is_anonymous, email: s.user.email ?? null, accessToken: s.access_token };
}

/**
 * Persistent guest identity: a Supabase anonymous user whose session is stored on the device.
 * It survives refreshes and restarts, and can later be upgraded to an email account.
 */
export async function ensureSession(): Promise<OnlineSession> {
  const sb = await supabase();
  const { data } = await sb.auth.getSession();
  if (data.session) return toSession(data.session)!;
  const { data: created, error } = await sb.auth.signInAnonymously();
  if (error || !created.session) throw new Error(error?.message ?? 'Could not create a guest identity');
  return toSession(created.session)!;
}

export async function currentAccessToken(): Promise<string> {
  return (await ensureSession()).accessToken;
}

/** Turn the guest identity into an email account, keeping all games. */
export async function upgradeAccount(email: string, password: string) {
  const { error } = await (await supabase()).auth.updateUser({ email, password });
  if (error) throw new Error(error.message);
}

export async function signInWithEmail(email: string, password: string) {
  const { error } = await (await supabase()).auth.signInWithPassword({ email, password });
  if (error) throw new Error(error.message);
}

export async function signOut() {
  if (!onlineConfigured) return;
  await (await supabase()).auth.signOut();
}

export function useOnlineSession(): OnlineSession | null {
  const [session, setSession] = useState<OnlineSession | null>(null);
  useEffect(() => {
    if (!onlineConfigured) return;
    let unsub: (() => void) | null = null;
    let alive = true;
    void supabase().then((sb) => {
      if (!alive) return;
      void sb.auth.getSession().then(({ data }) => alive && setSession(toSession(data.session)));
      const { data } = sb.auth.onAuthStateChange((_e, s) => alive && setSession(toSession(s)));
      unsub = () => data.subscription.unsubscribe();
    });
    return () => {
      alive = false;
      unsub?.();
    };
  }, []);
  return session;
}
