import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';
import { kvGet, kvSet } from '../offline/db.ts';

export interface Settings {
  sound: boolean;
  music: boolean;
  volume: number;
  reducedMotion: boolean;
  colorblind: boolean;
  highContrast: boolean;
  notifications: boolean;
  autoContinue: boolean;
  largeText: boolean;
}

export interface Profile {
  nickname: string;
  avatar: string;
  tutorialDone: boolean;
}

export const DEFAULT_SETTINGS: Settings = {
  sound: true,
  music: false,
  volume: 0.7,
  reducedMotion: false,
  colorblind: false,
  highContrast: false,
  notifications: false,
  autoContinue: false,
  largeText: false,
};

export const DEFAULT_PROFILE: Profile = { nickname: '', avatar: 'summit', tutorialDone: false };

interface Ctx {
  settings: Settings;
  profile: Profile;
  ready: boolean;
  updateSettings(patch: Partial<Settings>): void;
  updateProfile(patch: Partial<Profile>): void;
}

const SettingsContext = createContext<Ctx | null>(null);

const systemReducedMotion = () =>
  typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;

export function SettingsProvider({ children }: { children: ReactNode }) {
  const [settings, setSettings] = useState<Settings>({ ...DEFAULT_SETTINGS, reducedMotion: !!systemReducedMotion() });
  const [profile, setProfile] = useState<Profile>(DEFAULT_PROFILE);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    void Promise.all([kvGet<Partial<Settings>>('settings', {}), kvGet<Partial<Profile>>('profile', {})]).then(([s, p]) => {
      setSettings((cur) => ({ ...cur, ...s }));
      setProfile({ ...DEFAULT_PROFILE, ...p });
      setReady(true);
    });
  }, []);

  useEffect(() => {
    const root = document.documentElement;
    root.dataset.reducedMotion = String(settings.reducedMotion);
    root.dataset.colorblind = String(settings.colorblind);
    root.dataset.contrast = settings.highContrast ? 'high' : 'normal';
    root.style.fontSize = settings.largeText ? '112.5%' : '';
  }, [settings]);

  const updateSettings = useCallback((patch: Partial<Settings>) => {
    setSettings((cur) => {
      const next = { ...cur, ...patch };
      void kvSet('settings', next);
      return next;
    });
  }, []);

  const updateProfile = useCallback((patch: Partial<Profile>) => {
    setProfile((cur) => {
      const next = { ...cur, ...patch };
      void kvSet('profile', next);
      return next;
    });
  }, []);

  const value = useMemo(() => ({ settings, profile, ready, updateSettings, updateProfile }), [settings, profile, ready, updateSettings, updateProfile]);
  return <SettingsContext.Provider value={value}>{children}</SettingsContext.Provider>;
}

export function useSettings(): Ctx {
  const ctx = useContext(SettingsContext);
  if (!ctx) throw new Error('useSettings outside SettingsProvider');
  return ctx;
}
