import { AnimatePresence } from 'motion/react';
import { useEffect, useRef, useState } from 'react';
import { navigate } from '../app/router.tsx';
import { useSettings } from '../app/settings.tsx';
import { GameTable } from '../components/game/GameTable.tsx';
import { Resolution } from '../components/game/Resolution.tsx';
import { ResultsPanel } from '../components/game/ResultsPanel.tsx';
import { IconChat, IconWifiOff } from '../components/ui/Icons.tsx';
import { Button, CompactHeader, GameScreen, Panel, Screen, ScreenHeader } from '../components/ui/Primitives.tsx';
import { getRoute } from '../data/routes/index.ts';
import type { Role } from '../engine/types.ts';
import { forfeitGame, rematch, sendChat, type OnlineGameView } from '../multiplayer/api.ts';
import { readSeenRounds, useOnlineGame, writeSeenRounds } from '../multiplayer/useOnlineGame.ts';

function notifyTurn(v: OnlineGameView, enabled: boolean) {
  if (!enabled || typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
  if (document.visibilityState === 'visible') return;
  if (!v.myRole || v.status !== 'in_progress' || v.committed[v.myRole]) return;
  const title = 'On Belay — your move';
  const options = { body: `Round ${v.state?.round} on ${getRoute(v.routeId).name} is waiting for you.`, tag: `ob-${v.id}`, icon: 'icons/icon-192.png' };
  // Android only allows notifications from the service worker; fall back to the page API elsewhere.
  const viaPage = () => {
    try {
      new Notification(title, options);
    } catch {
      /* not allowed on this platform */
    }
  };
  if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
    void navigator.serviceWorker.ready.then((r) => r.showNotification(title, options)).catch(viaPage);
  } else viaPage();
}

export function OnlineGameScreen({ gameId }: { gameId: string }) {
  const { settings } = useSettings();
  const { view, error, connection, busy, pending, notice, setNotice, submit, declare, refresh } = useOnlineGame(gameId, {
    onPartnerMove: (v) => notifyTurn(v, settings.notifications),
  });
  const [seen, setSeen] = useState(() => readSeenRounds(gameId));
  const [confirmLeave, setConfirmLeave] = useState(false);
  const [chatOpen, setChatOpen] = useState(false);
  const firstLoad = useRef(true);

  // On first load, don't replay rounds the player already saw on another device or before a
  // refresh beyond the most recent one.
  useEffect(() => {
    if (!view?.state || !firstLoad.current) return;
    firstLoad.current = false;
    const n = view.state.history.length;
    if (seen < n - 1) {
      writeSeenRounds(gameId, n - 1);
      setSeen(n - 1);
    }
  }, [view, seen, gameId]);

  if (error && !view) {
    return (
      <Screen>
        <ScreenHeader title="Online game" onBack={() => navigate({ name: 'online' })} />
        <Panel>
          <span role="alert">{error}</span>
        </Panel>
      </Screen>
    );
  }
  if (!view) return <Screen><p className="p-8 text-center text-cream">Loading the climb…</p></Screen>;
  if (view.status === 'lobby') {
    navigate({ name: 'lobby', gameId }, true);
    return null;
  }
  if (!view.state || !view.myRole) {
    return (
      <Screen>
        <ScreenHeader title="Online game" onBack={() => navigate({ name: 'online' })} />
        <Panel>This game has no climb for you to play.</Panel>
      </Screen>
    );
  }

  const route = getRoute(view.routeId);
  const state = view.state;
  const role: Role = view.myRole;
  const partnerRole: Role = role === 'climber' ? 'belayer' : 'climber';
  const nameOf = (r: Role) => view.participants.find((p) => p.role === r)?.nickname ?? r;
  const names = { climber: nameOf('climber'), belayer: nameOf('belayer') };
  const partner = view.participants.find((p) => p.role === partnerRole);
  const history = state.history;
  const toReveal = history.length > seen ? history[history.length - 1] : null;
  const finished = state.status !== 'in_progress';
  const pendingThisRound = pending && pending.round === state.round && pending.stateVersion === view.stateVersion;
  const myCommitted = view.committed[role] || !!pendingThisRound;
  const chats = view.events.filter((e) => e.kind === 'chat');

  const markSeen = () => {
    writeSeenRounds(gameId, history.length);
    setSeen(history.length);
  };

  const banner = (
    <>
      {connection === 'offline' && (
        <div className="flex items-center gap-2 rounded-xl bg-ink px-3 py-2 text-sm font-bold text-cream" role="status" data-testid="online-offline">
          <IconWifiOff size={18} /> Offline — showing the last state from the server. Moves can't be sent until you reconnect.
        </div>
      )}
      {pendingThisRound && !view.committed[role] && (
        <div className="rounded-xl bg-[var(--warn)] px-3 py-2 text-sm font-black text-ink" role="status" data-testid="pending-local">
          Your card is saved on this device but NOT sent yet. It will be sent, and checked against the latest board, when you reconnect.
        </div>
      )}
      {notice && (
        <div className="flex items-start justify-between gap-2 rounded-xl bg-cream px-3 py-2 text-sm font-bold text-ink" role="alert">
          <span>{notice}</span>
          <button type="button" className="focus-ring underline" onClick={() => setNotice(null)}>
            OK
          </button>
        </div>
      )}
    </>
  );

  return (
    <GameScreen>
      <CompactHeader
        title={route.name}
        subtitle={`Online · Room ${view.roomCode} · with ${partner?.nickname ?? 'your partner'} · ${connection === 'live' ? 'live' : connection}`}
        onBack={() => navigate({ name: 'online' })}
        right={
          <div className="flex gap-2">
            <Button variant="ghost" size="sm" onClick={() => setChatOpen((o) => !o)} aria-label="Messages" aria-expanded={chatOpen}>
              <IconChat size={18} />
              {chats.length > 0 && <span className="text-xs">{chats.length}</span>}
            </Button>
            {!finished && (
              <Button variant="ghost" size="sm" onClick={() => setConfirmLeave(true)}>
                Forfeit
              </Button>
            )}
          </div>
        }
      />

      {chatOpen && <ChatPanel gameId={gameId} view={view} onSent={() => void refresh()} onClose={() => setChatOpen(false)} />}

      {finished && !toReveal ? (
        <div className="mx-auto flex min-h-0 w-full max-w-lg flex-1 flex-col justify-center overflow-y-auto">
          <ResultsPanel
            state={state}
            route={route}
            onRematch={async () => {
              const r = await rematch(gameId);
              navigate({ name: 'onlineGame', gameId: r.gameId });
            }}
            rematchLabel={view.rematchGameId ? 'Join the rematch' : 'Rematch'}
            onHome={() => navigate({ name: 'home' })}
          />
        </div>
      ) : (
        <GameTable
          route={route}
          state={state}
          role={role}
          names={names}
          myCommitted={myCommitted}
          partnerCommitted={view.committed[partnerRole]}
          partner={view.declarations[partnerRole]}
          mine={view.declarations[role] ?? (pendingThisRound ? { signal: pending!.submission.signal, teamworkPolicy: pending!.submission.teamworkPolicy, committed: true } : null)}
          busy={busy}
          onSubmit={(s) => void submit(s)}
          onDeclare={declare}
          banner={banner}
          waitingExtras={
            <div className="flex flex-wrap gap-2">
              <Button size="sm" variant="secondary" onClick={() => navigate({ name: 'home' })}>
                Leave — I'll come back later
              </Button>
              {!settings.notifications && typeof Notification !== 'undefined' && (
                <Button size="sm" variant="ghost" className="!bg-pine-700" onClick={() => navigate({ name: 'settings' })}>
                  Turn on notifications
                </Button>
              )}
            </div>
          }
        />
      )}

      <AnimatePresence>
        {toReveal && (
          <Resolution key={toReveal.round} result={toReveal} route={route} clippedAfter={state.clippedBolts} names={names} onDone={markSeen} />
        )}
      </AnimatePresence>

      {confirmLeave && (
        <div className="fixed inset-0 z-50 grid place-items-center bg-black/60 p-4" role="dialog" aria-modal="true" aria-label="Forfeit this climb?">
          <Panel className="max-w-sm">
            <h2 className="font-display text-2xl font-bold">Forfeit for both of you?</h2>
            <p className="mt-1 text-ink-soft">This ends the climb as a failed ascent for your partner too. If you just need a break, leave instead — the climb will wait.</p>
            <div className="mt-4 flex gap-2">
              <Button variant="secondary" className="flex-1" onClick={() => setConfirmLeave(false)}>
                Cancel
              </Button>
              <Button
                variant="danger"
                className="flex-1"
                onClick={async () => {
                  setConfirmLeave(false);
                  await forfeitGame(gameId);
                  await refresh();
                }}
              >
                Forfeit
              </Button>
            </div>
          </Panel>
        </div>
      )}
    </GameScreen>
  );
}

function ChatPanel({ gameId, view, onSent, onClose }: { gameId: string; view: OnlineGameView; onSent: () => void; onClose: () => void }) {
  const [text, setText] = useState('');
  const [err, setErr] = useState<string | null>(null);
  const chats = view.events.filter((e) => e.kind === 'chat').slice(-20);
  return (
    <div className="fixed inset-0 z-50 flex items-end bg-black/50" onClick={onClose} role="dialog" aria-modal="true" aria-label="Messages">
    <div className="mx-auto w-full max-w-lg" onClick={(e) => e.stopPropagation()} style={{ paddingBottom: 'var(--safe-bottom)' }}>
    <Panel className="rounded-b-none" as="div">
      <div className="mb-2 flex items-center justify-between">
        <h2 className="font-display text-lg font-bold">Messages</h2>
        <button type="button" className="focus-ring min-h-10 rounded-full px-3 text-sm font-bold underline" onClick={onClose}>
          Close
        </button>
      </div>
      <div className="max-h-48 space-y-1 overflow-y-auto text-sm" aria-live="polite" data-testid="chat-log">
        {chats.length === 0 && <p className="text-ink-soft">No messages yet. Signals work fine on their own — chat is optional.</p>}
        {chats.map((c) => (
          <p key={c.id}>
            <b>{String(c.payload.nickname ?? 'Partner')}:</b> {String(c.payload.text ?? '')}
          </p>
        ))}
      </div>
      <form
        className="mt-2 flex gap-2"
        onSubmit={async (e) => {
          e.preventDefault();
          if (!text.trim()) return;
          try {
            await sendChat(gameId, text);
            setText('');
            setErr(null);
            onSent();
          } catch (x) {
            setErr(x instanceof Error ? x.message : String(x));
          }
        }}
      >
        <input className="focus-ring min-h-11 flex-1 rounded-xl border border-black/15 bg-white px-3" maxLength={140} value={text} onChange={(e) => setText(e.target.value)} placeholder="Short message…" aria-label="Message" />
        <Button size="sm" type="submit">
          Send
        </Button>
      </form>
      {err && <p className="mt-1 text-xs font-bold text-danger">{err}</p>}
    </Panel>
    </div>
    </div>
  );
}
