import type { BelayerAction, ClimberAction } from '../../engine/types.ts';
import { art } from '../../art/art.ts';

/** Small illustrations for each action card. Distinct silhouettes, so cards read without colour. */
export function CardArt({ action }: { action: ClimberAction | BelayerAction }) {
  const painted = art(`card-${action.toLowerCase().replace('_', '-')}`);
  if (painted) return <img src={painted.url} alt="" aria-hidden className="h-full w-full rounded-[inherit] object-cover" draggable={false} />;
  const common = { width: '100%', height: '100%', viewBox: '0 0 80 60', 'aria-hidden': true } as const;
  switch (action) {
    case 'STEP':
      return (
        <svg {...common}>
          <rect x="8" y="40" width="26" height="8" rx="3" fill="#2f8f83" />
          <rect x="44" y="24" width="26" height="8" rx="3" fill="#2f8f83" />
          <path d="M20 38c0-10 8-16 16-16" stroke="#1d2422" strokeWidth="3" fill="none" strokeDasharray="3 4" />
          <path d="M40 18l6 5-7 3" fill="#1d2422" />
          <path d="M46 22l8-1 2 4h-10z" fill="#c8643b" />
        </svg>
      );
    case 'REACH':
      return (
        <svg {...common}>
          <rect x="6" y="46" width="22" height="7" rx="3" fill="#2f8f83" />
          <rect x="52" y="8" width="22" height="7" rx="3" fill="#2f8f83" />
          <path d="M18 44 C22 24 40 14 58 16" stroke="#1d2422" strokeWidth="3" fill="none" />
          <path d="M54 10l8 6-9 4" fill="#1d2422" />
          <text x="34" y="44" fontSize="14" fontWeight="900" fill="#c8643b">+2</text>
        </svg>
      );
    case 'CLIP':
      return (
        <svg {...common}>
          <circle cx="40" cy="12" r="6" fill="#c9ced3" stroke="#4b5257" strokeWidth="2" />
          <ellipse cx="40" cy="25" rx="5" ry="8" fill="none" stroke="#e07a3f" strokeWidth="3" />
          <rect x="36.5" y="32" width="7" height="12" rx="3" fill="#2f8f83" />
          <ellipse cx="40" cy="50" rx="5" ry="8" fill="none" stroke="#e07a3f" strokeWidth="3" />
          <path d="M14 56 C24 40 30 52 40 50 S56 40 66 56" stroke="#e9b44c" strokeWidth="3.5" fill="none" />
        </svg>
      );
    case 'REST':
      return (
        <svg {...common}>
          <path d="M8 46 q32 -14 64 0 l-4 6 q-28 8 -56 0 z" fill="#2f8f83" />
          <path d="M52 10 a10 10 0 1 0 8 16 a8 8 0 1 1 -8 -16z" fill="#e9b44c" />
          <path d="M22 30 q4 -6 8 0 t8 0" stroke="#1d2422" strokeWidth="2.5" fill="none" strokeLinecap="round" />
        </svg>
      );
    case 'FEED':
      return (
        <svg {...common}>
          <path d="M12 52 C20 30 30 50 40 30 S56 10 64 14" stroke="#e9b44c" strokeWidth="5" fill="none" strokeLinecap="round" />
          <path d="M60 6l10 8-12 4z" fill="#1d2422" />
          <text x="10" y="22" fontSize="15" fontWeight="900" fill="#2f8f83">+1</text>
        </svg>
      );
    case 'TAKE_IN':
      return (
        <svg {...common}>
          <path d="M64 8 C56 30 46 14 40 32 S22 52 14 48" stroke="#e9b44c" strokeWidth="5" fill="none" strokeLinecap="round" />
          <path d="M18 56l-10-8 12-3z" fill="#1d2422" />
          <text x="52" y="54" fontSize="15" fontWeight="900" fill="#c8643b">−1</text>
        </svg>
      );
    case 'BRACE':
      return (
        <svg {...common}>
          <path d="M40 6 L62 14 V30 C62 44 52 52 40 56 C28 52 18 44 18 30 V14 Z" fill="#2f8f83" stroke="#1d2422" strokeWidth="2.5" />
          <path d="M30 30 l7 7 l13 -14" stroke="#fbf5ea" strokeWidth="4" fill="none" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      );
    case 'ENCOURAGE':
      return (
        <svg {...common}>
          <path d="M14 26 h10 l20 -12 v32 l-20 -12 h-10 z" fill="#e07a3f" stroke="#1d2422" strokeWidth="2.5" strokeLinejoin="round" />
          <path d="M52 20 q6 10 0 20 M58 14 q10 16 0 32" stroke="#1d2422" strokeWidth="3" fill="none" strokeLinecap="round" />
          <text x="60" y="58" fontSize="13" fontWeight="900" fill="#2f8f83">+1</text>
        </svg>
      );
  }
}
