import { useEffect, useState } from 'react';
import { navigate } from '../app/router.tsx';
import { ClimbingWall } from '../components/climbing/ClimbingWall.tsx';
import { CarabinerRow } from '../components/ui/Carabiner.tsx';
import { Button, Panel, Screen, ScreenHeader } from '../components/ui/Primitives.tsx';
import { ROUTES } from '../data/routes/index.ts';
import { personalBests, type PersonalBest } from '../offline/repository.ts';

export function RoutesScreen() {
  const [pbs, setPbs] = useState<Record<string, PersonalBest>>({});
  useEffect(() => void personalBests().then(setPbs), []);
  const totalStars = Object.values(pbs).reduce((a, p) => a + p.bestCarabiners, 0);
  return (
    <Screen>
      <ScreenHeader title="Route Collection" subtitle={`${totalStars} of ${ROUTES.length * 3} carabiners earned`} onBack={() => navigate({ name: 'home' })} />
      <div className="grid gap-4 md:grid-cols-3">
        {ROUTES.map((r) => {
          const pb = pbs[r.id];
          return (
            <Panel key={r.id} className="flex flex-col gap-2" as="article">
              <ClimbingWall className="h-72 w-full rounded-xl" route={r} position={0} clippedBolts={[]} rope={1} />
              <div className="flex items-center justify-between">
                <h2 className="font-display text-2xl font-bold">{r.name}</h2>
                <CarabinerRow count={pb?.bestCarabiners ?? 0} size={18} />
              </div>
              <div className="text-sm font-bold text-ink-soft">
                {r.grade} · {r.terrain}
              </div>
              <p className="text-sm">{r.description}</p>
              <p className="text-sm italic text-ink-soft">{r.flavor}</p>
              <div className="text-xs text-ink-soft">
                Holds: {r.difficulty.join(' · ')} · Rests at {r.restHolds.join(', ')} · Bolts at {r.bolts.join(', ')}
              </div>
              <div className="text-xs font-bold text-ink-soft">
                {pb ? `${pb.completions}/${pb.attempts} completed${pb.fewestRounds ? ` · best ${pb.fewestRounds} rounds` : ''}` : 'Not attempted yet'}
              </div>
              <Button className="mt-auto" onClick={() => navigate({ name: 'setup', mode: 'solo' })}>
                Climb it
              </Button>
            </Panel>
          );
        })}
      </div>
      <div className="mt-4 text-center">
        <button type="button" className="focus-ring text-sm font-bold text-sand/70 underline" onClick={() => navigate({ name: 'editor' })}>
          Route editor (developer tool)
        </button>
      </div>
      <p className="mt-2 text-center text-xs text-sand/60">Grades are preliminary game-balance labels, not validated equivalents of real outdoor climbing difficulty.</p>
    </Screen>
  );
}
