import { useEffect, useState } from 'react';
import { navigate } from '../app/router.tsx';
import { Avatar } from '../components/ui/Avatar.tsx';
import { IconCheck, IconCopy, IconShare } from '../components/ui/Icons.tsx';
import { Button, Panel, Screen, ScreenHeader } from '../components/ui/Primitives.tsx';
import { getRoute } from '../data/routes/index.ts';
import type { Role } from '../engine/types.ts';
import { chooseRole, forfeitGame, startGame } from '../multiplayer/api.ts';
import { useOnlineGame } from '../multiplayer/useOnlineGame.ts';

export function inviteLink(code: string) {
  return `${location.origin}${location.pathname}#/join/${code}`;
}

const isRecent = (iso: string) => Date.now() - new Date(iso).getTime() < 2.5 * 60_000;

export function LobbyScreen({ gameId }: { gameId: string }) {
  const { view, error, connection, refresh } = useOnlineGame(gameId);
  const [copied, setCopied] = useState(false);
  const [busy, setBusy] = useState(false);
  const [actionError, setActionError] = useState<string | null>(null);

  useEffect(() => {
    if (view && view.status !== 'lobby') navigate({ name: 'onlineGame', gameId }, true);
  }, [view, gameId]);

  if (error && !view) {
    return (
      <Screen>
        <ScreenHeader title="Lobby" onBack={() => navigate({ name: 'online' })} />
        <Panel><span role="alert">{error}</span></Panel>
      </Screen>
    );
  }
  if (!view) return <Screen><p className="p-8 text-center text-cream">Opening the lobby…</p></Screen>;

  const route = getRoute(view.routeId);
  const link = inviteLink(view.roomCode);
  const bothRoles = view.participants.filter((p) => p.role).length === 2;

  const run = async (fn: () => Promise<unknown>) => {
    setBusy(true);
    setActionError(null);
    try {
      await fn();
      await refresh();
    } catch (e) {
      setActionError(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  };

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(link);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      setActionError('Copy failed — select the link and copy it manually.');
    }
  };
  const share = async () => {
    try {
      await navigator.share({ title: 'On Belay', text: `Climb ${route.name} with me on On Belay! Room code ${view.roomCode}`, url: link });
    } catch {
      /* cancelled */
    }
  };

  return (
    <Screen>
      <ScreenHeader title="Lobby" subtitle={`${route.name} · ${route.grade}`} onBack={() => navigate({ name: 'online' })} />
      <div className="mx-auto grid max-w-3xl gap-4 md:grid-cols-2">
        <Panel className="flex flex-col items-center gap-3 text-center">
          <div className="text-xs font-black uppercase tracking-[0.3em] text-ink-soft">Room code</div>
          <div className="font-mono text-5xl font-black tracking-[0.25em]" data-testid="room-code">
            {view.roomCode}
          </div>
          <div className="w-full break-all rounded-xl bg-sand/70 px-3 py-2 text-xs" data-testid="invite-link">
            {link}
          </div>
          <div className="flex w-full gap-2">
            <Button variant="secondary" className="flex-1" onClick={() => void copy()}>
              {copied ? <IconCheck /> : <IconCopy />} {copied ? 'Copied' : 'Copy invite'}
            </Button>
            {typeof navigator.share === 'function' && (
              <Button variant="secondary" className="flex-1" onClick={() => void share()}>
                <IconShare /> Share
              </Button>
            )}
          </div>
          <p className="text-sm text-ink-soft">Your partner can join any time — they don't need to be here right now.</p>
        </Panel>

        <Panel className="flex flex-col gap-3">
          <h2 className="font-display text-xl font-bold">Rope team</h2>
          {(['climber', 'belayer'] as Role[]).map((r) => {
            const p = view.participants.find((x) => x.role === r);
            const mine = p?.userId === view.myUserId;
            return (
              <div key={r} className="flex items-center gap-3 rounded-2xl bg-sand/60 p-2.5" data-testid={`slot-${r}`}>
                {p ? <Avatar id={p.avatar} size={44} /> : <div className="h-11 w-11 rounded-full border-2 border-dashed border-granite" />}
                <div className="min-w-0 flex-1">
                  <div className="text-xs font-black uppercase tracking-wider text-ink-soft">{r}</div>
                  <div className="truncate font-extrabold">{p ? `${p.nickname}${mine ? ' (you)' : ''}` : 'Waiting for a partner…'}</div>
                  {p && <div className="text-xs text-ink-soft">{isRecent(p.lastSeenAt) ? '● here now' : '○ away'}</div>}
                </div>
                {!mine && view.myRole !== r && (
                  <Button size="sm" variant="ghost" className="!bg-pine-700 !text-cream" disabled={busy} onClick={() => void run(() => chooseRole(gameId, r))}>
                    {p ? 'Swap' : 'Take'}
                  </Button>
                )}
              </div>
            );
          })}
          <Button size="lg" disabled={!bothRoles || busy} onClick={() => void run(() => startGame(gameId))} data-testid="start-online">
            {bothRoles ? 'Start the climb' : 'Waiting for your partner'}
          </Button>
          <button type="button" className="focus-ring text-sm font-bold text-ink-soft underline" onClick={() => void run(async () => { await forfeitGame(gameId); navigate({ name: 'online' }); })}>
            Close this room
          </button>
          {actionError && <p className="text-sm font-bold text-danger" role="alert">{actionError}</p>}
          <p className="text-xs text-ink-soft">Connection: {connection}</p>
        </Panel>
      </div>
    </Screen>
  );
}
