import { runAiTask, type AiAnswer, type AiTask } from './localGame.ts';

/**
 * Runs AI partner decisions in a Web Worker so the planner never blocks the UI. If the worker
 * cannot start (unsupported, failed to load while offline, crashed) or is too slow, the decision
 * is computed on the main thread instead — the AI must never leave a game stuck.
 */

let worker: Worker | null = null;
let workerBroken = false;
let nextId = 1;
const waiting = new Map<number, { task: AiTask; resolve(a: AiAnswer): void; timer: ReturnType<typeof setTimeout> }>();
const TIMEOUT_MS = 20_000;

function settleAllOnMainThread() {
  for (const [id, w] of waiting) {
    clearTimeout(w.timer);
    waiting.delete(id);
    w.resolve(runAiTask(w.task));
  }
}

function getWorker(): Worker | null {
  if (worker || workerBroken) return worker;
  if (typeof Worker === 'undefined') return null;
  try {
    worker = new Worker(new URL('./ai.worker.ts', import.meta.url), { type: 'module' });
    worker.onmessage = (e: MessageEvent<{ id: number; answer?: AiAnswer; error?: string }>) => {
      const w = waiting.get(e.data.id);
      if (!w) return;
      clearTimeout(w.timer);
      waiting.delete(e.data.id);
      w.resolve(e.data.answer ?? runAiTask(w.task));
    };
    worker.onerror = () => {
      workerBroken = true;
      worker?.terminate();
      worker = null;
      settleAllOnMainThread();
    };
    return worker;
  } catch {
    workerBroken = true;
    return null;
  }
}

/** Ask the AI partner for a decision. */
export function askAi(task: AiTask): Promise<AiAnswer> {
  const w = getWorker();
  if (!w) return new Promise((resolve) => setTimeout(() => resolve(runAiTask(task)), 0));
  const id = nextId++;
  return new Promise<AiAnswer>((resolve) => {
    const timer = setTimeout(() => {
      if (!waiting.has(id)) return;
      waiting.delete(id);
      resolve(runAiTask(task));
    }, TIMEOUT_MS);
    waiting.set(id, { task, resolve, timer });
    w.postMessage({ id, task });
  });
}

/** Start the worker early (e.g. on the setup screen) so it is loaded before connectivity drops. */
export function preloadAi() {
  getWorker();
}
