import { art } from '../../art/art.ts';

/** Original illustrated avatars: a climber's helmet in different colours with an outdoorsy badge. */
export const AVATARS = ['summit', 'pine', 'river', 'ember', 'raven', 'sun', 'moss', 'granite'] as const;
export type AvatarId = (typeof AVATARS)[number];

const STYLE: Record<string, { bg: string; helmet: string; badge: 'peak' | 'tree' | 'wave' | 'flame' | 'bird' | 'sun' | 'leaf' | 'stone' }> = {
  summit: { bg: '#f6b76b', helmet: '#e07a3f', badge: 'peak' },
  pine: { bg: '#7cc4bb', helmet: '#1e3d34', badge: 'tree' },
  river: { bg: '#a9cfe0', helmet: '#3a7ca5', badge: 'wave' },
  ember: { bg: '#f3e3c7', helmet: '#c8643b', badge: 'flame' },
  raven: { bg: '#d9b48a', helmet: '#1d2422', badge: 'bird' },
  sun: { bg: '#fde6c4', helmet: '#e9b44c', badge: 'sun' },
  moss: { bg: '#c9d6a3', helmet: '#6f8f4e', badge: 'leaf' },
  granite: { bg: '#c9d6df', helmet: '#555b61', badge: 'stone' },
};

export function Avatar({ id, size = 40 }: { id: string; size?: number }) {
  const painted = art(`avatar-${id}`) ?? (STYLE[id] ? null : art('avatar-summit'));
  if (painted) return <img src={painted.url} width={size} height={size} alt="" aria-hidden className="shrink-0 rounded-full object-cover" draggable={false} />;
  const s = STYLE[id] ?? STYLE.summit!;
  return (
    <svg width={size} height={size} viewBox="0 0 48 48" aria-hidden>
      <circle cx="24" cy="24" r="23" fill={s.bg} />
      <circle cx="24" cy="27" r="11" fill="#e8b48c" />
      <path d="M12 25 a12 12 0 0 1 24 0 z" fill={s.helmet} />
      <rect x="11" y="23.5" width="26" height="3.5" rx="1.7" fill={s.helmet} opacity="0.8" />
      <circle cx="20" cy="30" r="1.3" fill="#1d2422" />
      <circle cx="28" cy="30" r="1.3" fill="#1d2422" />
      <path d="M21 34 q3 2.4 6 0" stroke="#1d2422" strokeWidth="1.5" fill="none" strokeLinecap="round" />
      <g transform="translate(24 17)" fill="#fbf5ea">
        {s.badge === 'peak' && <path d="M-5 3 L0 -4 L5 3 Z" />}
        {s.badge === 'tree' && <path d="M0 -5 L4 3 L-4 3 Z" />}
        {s.badge === 'wave' && <path d="M-5 1 q2.5 -4 5 0 t5 0" stroke="#fbf5ea" strokeWidth="1.8" fill="none" />}
        {s.badge === 'flame' && <path d="M0 -5 C4 -1 3 3 0 3 C-3 3 -4 -1 0 -5 Z" />}
        {s.badge === 'bird' && <path d="M-5 0 q2.5 -3 5 0 q2.5 -3 5 0" stroke="#fbf5ea" strokeWidth="1.8" fill="none" />}
        {s.badge === 'sun' && <circle r="3.5" />}
        {s.badge === 'leaf' && <path d="M-4 3 C-4 -3 2 -5 4 -5 C4 1 0 3 -4 3 Z" />}
        {s.badge === 'stone' && <path d="M-4 2 L-2 -3 L3 -3 L5 2 Z" />}
      </g>
    </svg>
  );
}
